const KEY='hplc_csv_state_v1';
const USERS={
 qc:{role:'QC',label:'Quality Control',username:'qualitycontrol',password:'qc123'},
 qa:{role:'QA',label:'Quality Assurance',username:'qualityassurance',password:'qa123'},
 admin:{role:'Admin',label:'Administration',username:'administration',password:'admin123'}
};
const NAV=[
 ['dashboard','Dashboard','Dashboard'],['methods','Analytical Method','Analytical Method'],['sequence','Sequence','Sequence'],['instrument','Instrument','Instrument'],
 ['chromatogram','Chromatogram','Chromatogram'],['assay','Assay / Data Review','Assay / Data Review'],['urs','URS Verification','URS Verification'],
 ['csv','CSV Validation Center','CSV Validation Center'],['report','Validation Report','Validation Report'],['audit','Audit Trail','Audit Trail'],['admin','Administration','Administration']
];
const seed={
 config:{application:'HPLC-UV CSV Validation System',systemId:'HPLC-UV-001',detector:'UV',softwareVersion:'1.0.0',dataIntegrity:'ALCOA+',lastValidation:'',nextDue:''},
 methods:[],sequences:[],tests:[],instruments:[],assays:[],urs:[],activities:[],notifications:[],session:null
};
let state=load(); let currentPage='dashboard'; let currentMethodId=null;
function load(){try{return {...seed,...JSON.parse(localStorage.getItem(KEY)||'null')}}catch(e){return structuredClone(seed)}}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function now(){return new Date().toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'short'})}
function uid(p='ID'){return p+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6)}
function esc(v=''){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function role(){return state.session?.role||''}
function log(action,detail){state.activities.unshift({id:uid('ACT'),date:now(),user:state.session?.username||'system',role:role(),action,detail});state.activities=state.activities.slice(0,300);save()}
function badge(s){let c=s==='Approved'||s==='Passed'?'approved':(s==='Rejected'||s==='Failed'?'rejected':(s==='Draft'?'draft':'pending'));return `<span class="badge ${c}">${esc(s||'No Data')}</span>`}
function openModal(title,body,foot=''){document.getElementById('modalRoot').innerHTML=`<div class="modal-back show" id="modal"><div class="modal"><div class="modal-head"><h3>${title}</h3><button class="close" onclick="closeModal()">×</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}</div></div>`}
function closeModal(){document.getElementById('modalRoot').innerHTML=''}
function layout(){const u=state.session;document.getElementById('root').innerHTML=`<div class="app"><aside class="sidebar">
<div class="brand"><div class="logo">HPLC</div><div><b>HPLC-UV CSV</b><span>Validation System</span></div></div>
<nav class="nav">${NAV.map(n=>`<button class="${currentPage===n[0]?'active':''}" onclick="go('${n[0]}')"><span class="ico">${MENU_ICONS[n[0]]}</span><span class="label">${n[2]}</span></button>`).join('')}</nav>
<div class="side-bottom"><div class="profile"><div class="avatar">${u.role[0]}</div><div><b style="font-size:10px">${u.role}</b><small>${u.label}</small></div></div><button class="logout" onclick="logout()">↪ <span>Logout</span></button></div>
</aside><main class="main"><header class="topbar"><div class="top-actions"><button class="notification-bell" onclick="showNotifications()" aria-label="Notifications"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 10a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"></path><path d="M10 21h4"></path></svg>${state.notifications.length ? `<span class="notification-count">${state.notifications.length}</span>` : ''}</button><div class="user-menu"><div class="avatar">${u.role[0]}</div><span>${u.role}⌄</span></div></div></header><section class="content" id="content"></section></main></div>`;render()}
function go(p){currentPage=p;layout()}
function render(){const c=document.getElementById('content');({dashboard:renderDashboard,methods:renderMethods,sequence:renderSequence,instrument:renderInstrument,chromatogram:renderChromatogram,assay:renderAssay,urs:renderURS,csv:renderCSV,report:renderReport,audit:renderAudit,admin:renderAdmin}[currentPage]||renderDashboard)(c)}
function header(title,sub,extra=''){return `<div class="title-row"><div class="title"><div class="eyebrow">COMPUTERIZED SYSTEM VALIDATION</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${extra}</div>`}
function renderDashboard(c){
 const total=state.tests.length,pending=state.tests.filter(t=>t.status==='Pending Execution').length,review=state.tests.filter(t=>t.status==='Pending QA Review').length,approved=state.tests.filter(t=>t.status==='Approved').length,failed=state.tests.filter(t=>t.status==='Failed').length,progress=total?Math.round(approved/total*100):0;
 c.innerHTML=header('Dashboard',`Welcome back, ${role()}. Here’s an overview of the HPLC-UV CSV validation status.`, `<div class="status-box"><div>System Status<b class="ready">● Ready</b></div><div>System ID<b>${esc(state.config.systemId)}</b></div><div>Software Version<b>${esc(state.config.softwareVersion)}</b></div></div>`)+
 `<div class="cards">${[['Total Tests',total],['Pending Execution',pending],['Pending QA Review',review],['Approved',approved],['Failed',failed],['Overall Progress',progress+'%']].map(x=>`<div class="card"><label>${x[0]}</label><strong>${x[1]}</strong><div class="tiny">Dynamic system data</div></div>`).join('')}</div>
 <div class="grid2"><div class="panel"><div class="panel-head"><h3>Validation Progress (IQ, OQ, PQ)</h3></div>${progressChart()}</div><div class="panel"><div class="panel-head"><h3>Test Status Breakdown</h3></div>${statusBreakdown()}</div></div>
 <div class="grid2" style="margin-top:12px"><div class="panel"><div class="panel-head"><h3>System Information</h3></div><table class="info-table">${[['Application',state.config.application],['System ID',state.config.systemId],['Detector',state.config.detector],['Software Version',state.config.softwareVersion],['Data Integrity',state.config.dataIntegrity],['Last Validation',state.config.lastValidation||'No Data'],['Next Due',state.config.nextDue||'No Data']].map(x=>`<tr><td class="method-select-col"><input type="checkbox" class="method-row-check" aria-label="Select method"></td>
<td>${x[0]}</td><td><b>${esc(x[1])}</b></td></tr>`).join('')}</table></div><div class="panel"><div class="panel-head"><h3>Recent Activity</h3><small onclick="go('audit')">View All →</small></div>${state.activities.length?`<table class="info-table">${state.activities.slice(0,5).map(a=>`<tr><td class="method-select-col"><input type="checkbox" class="method-row-check" aria-label="Select method"></td>
<td>${esc(a.date)}</td><td>${esc(a.user)}</td><td>${esc(a.action)}</td></tr>`).join('')}</table>`:`<div class="empty">No recent activity</div>`}</div></div>
 <div class="panel" style="margin-top:12px"><div class="panel-head"><h3>My Tasks</h3><small onclick="go('csv')">View All →</small></div>${myTasks()}</div>`;
}
function progressChart(){let cats=['IQ','OQ','PQ'];return `<div class="mini-grid">${cats.map(cat=>{let a=state.tests.filter(t=>t.category===cat),done=a.filter(t=>t.status==='Approved').length,p=a.length?Math.round(done/a.length*100):0;return `<div class="mini"><span style="font-size:9px;color:#718095">${cat}</span><b>${p}%</b><div class="progress"><i style="width:${p}%"></i></div><small style="font-size:8px;color:#8b98a8">${done}/${a.length||0} approved</small></div>`}).join('')}</div>`}
function statusBreakdown(){let all=['Pending Execution','Pending QA Review','Approved','Failed'];return all.map(s=>{let n=state.tests.filter(t=>t.status===s).length,p=state.tests.length?Math.round(n/state.tests.length*100):0;return `<div style="display:flex;align-items:center;gap:8px;margin:11px 0"><div style="width:120px;font-size:9px">${badge(s)}</div><div class="progress" style="flex:1"><i style="width:${p}%"></i></div><b style="font-size:9px">${n} (${p}%)</b></div>`}).join('')||'<div class="empty">No Data</div>'}
function myTasks(){let tasks=[]; if(role()==='QA')tasks=state.methods.filter(m=>m.status==='Pending QA Approval').map(m=>({module:'Analytical Method',task:'Review '+m.methodId,priority:'High',due:'—',status:m.status})); if(role()==='QC')tasks=state.methods.filter(m=>m.status==='Request Revision').map(m=>({module:'Analytical Method',task:'Revise '+m.methodId,priority:'High',due:'—',status:m.status})); if(role()==='Admin')tasks=state.activities.slice(0,5).map(a=>({module:'Administration',task:a.action,priority:'Normal',due:'—',status:'Recorded'}));return tasks.length?`<table class="table"><thead><tr><th>Module</th><th>Task</th><th>Priority</th><th>Due Date</th><th>Status</th></tr></thead><tbody>${tasks.map(t=>`<tr><td>${t.module}</td><td>${esc(t.task)}</td><td>${t.priority}</td><td>${t.due}</td><td>${badge(t.status)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No pending tasks</div>'}

function initializeExampleMethods(){
 if(state.methodExamplesInitialized)return;
 const examples=[
  ['AM-HPLC-001','Paracetamol Assay','Paracetamol 500 mg Tablet','Approved','Assay','USP Monograph'],
  ['AM-HPLC-002','Caffeine Content','Caffeine Reference Standard','Pending QA Approval','Assay','Internal Method'],
  ['AM-HPLC-003','Ibuprofen Related Substances','Ibuprofen 400 mg Tablet','Draft','Impurities','Ph. Eur. Monograph'],
  ['AM-HPLC-004','Metformin Assay','Metformin HCl 500 mg Tablet','Request Revision','Assay','USP Monograph'],
  ['AM-HPLC-005','Amlodipine Dissolution','Amlodipine 5 mg Tablet','Rejected','Dissolution','Internal Method']
 ];
 state.methods=Array.isArray(state.methods)?state.methods:[];
 examples.forEach(([methodId,name,product,status,category,reference],i)=>{
  if(state.methods.some(m=>m.methodId===methodId))return;
  const submitted=['Approved','Pending QA Approval','Request Revision','Rejected'].includes(status);
  const review=['Approved','Request Revision','Rejected'].includes(status)?{by:'qualityassurance',date:'18 Sep 2026, 09:00',decision:status==='Approved'?'Approve':status==='Rejected'?'Reject':'Request Revision',comment:status==='Approved'?'Method and supporting data accepted.':'Please revise the method and supporting evidence.'}:null;
  state.methods.push({id:`SAMPLE-METHOD-${i+1}`,methodId,name,product,version:'V1.0',status,lastModified:'18 Sep 2026, 09:00',category,reference,description:`Example HPLC-UV ${category.toLowerCase()} method for ${product}.`,attachments:[],revisions:[{date:'18 Sep 2026, 09:00',user:submitted?'qualitycontrol':'qualitycontrol',action:submitted?'Submit':'Save',changes:'Example method record',version:'V1.0'}],chat:[],...(review?{review}:{}),systemSuitability:{retentionTime:'',resolution:'',tailingFactor:'',theoreticalPlates:'',rsdPeakArea:''},chromatographicConditions:{column:'C18, 150 × 4.6 mm',mobilePhaseA:'Water',mobilePhaseB:'Acetonitrile',columnTemperature:'30',injectionVolume:'10',elutionMode:'Isocratic',isocraticComposition:{a:'70',b:'30'},flowRate:'1.0',detectionWavelength:'254',runTime:'10',sampleTemperature:'25',gradientProgram:[]}});
 });
 state.methodExamplesInitialized=true;save();
}
function methodRoleMessage(){
 if(role()==='QC')return ['QC workspace','Prepare method details and supporting evidence, save a draft, then send it to QA. Revise methods returned by QA.'];
 if(role()==='QA')return ['QA review workspace','Inspect submitted methods and evidence, then approve, request revision, or reject with an electronic signature.'];
 return ['Admin overview','View method status, history, and reports. Method creation and review are handled by QC and QA.'];
}
function methodNextStep(m){
 if(m.status==='Draft')return role()==='QC'?'Complete method, then send to QA':'Awaiting QC submission';
 if(m.status==='Pending QA Approval')return role()==='QA'?'Review evidence and decide':'Awaiting QA decision';
 if(m.status==='Request Revision')return role()==='QC'?'Revise based on QA feedback':'Awaiting QC revision';
 if(m.status==='Rejected')return role()==='QC'?'Review QA feedback and prepare a new submission':'QA decision recorded';
 return 'Approved for use';
}
function methodQueue(){
 const r=role(),items=r==='QC'?state.methods.filter(m=>['Draft','Request Revision','Rejected'].includes(m.status)):r==='QA'?state.methods.filter(m=>m.status==='Pending QA Approval'):[];
 const heading=r==='QC'?'QC work queue':r==='QA'?'QA review queue':'Method workflow';
 const detail=r==='QC'?'Draft and returned methods needing QC action':r==='QA'?'Submitted methods awaiting QA decision':'QC prepares methods; QA reviews and approves; Admin monitors the record.';
 return `<section class="method-queue" id="methodQueue"><div class="method-queue-header"><div><h3>${heading}</h3><p>${detail}</p></div><span class="method-queue-count">${items.length} ${items.length===1?'item':'items'}</span></div>${items.length?`<div class="method-queue-items">${items.slice(0,4).map(m=>`<button type="button" onclick="${r==='QA'?`viewMethod('${m.id}')`:`editMethod('${m.id}')`}"><span><b>${esc(m.methodId)}</b><small>${esc(m.name)}</small></span>${badge(m.status)}<span class="method-queue-link">${r==='QA'?'Open review':'Continue'} →</span></button>`).join('')}</div>`:`<div class="method-queue-empty">${r==='Admin'?'The method list below shows the current approval status and history.':'No methods currently need your action.'}</div>`}</section>`;
}
function methodFilterStatus(status){document.getElementById('methodStatus').value=status;filterMethods();document.getElementById('methodQ').focus()}
function renderMethods(c){
 initializeExampleMethods();
 const [title,description]=methodRoleMessage(),counts=['All','Draft','Pending QA Approval','Request Revision','Approved','Rejected'].map(status=>[status,status==='All'?state.methods.length:state.methods.filter(m=>m.status===status).length]);
 c.innerHTML=header('Analytical Method','Manage analytical methods, approval workflow, evidence, and revision history.',`<div class="title-actions analytical-method-actions">${role()==='QC'?'<button class="btn primary" onclick="addMethod()">＋ Add New Method</button>':''}<button type="button" class="btn btn-secondary" onclick="downloadMethodsPDF()">Export PDF</button><button type="button" class="btn btn-secondary" onclick="printAnalyticalMethods()">Print</button></div>`)+
 `<div class="method-workflow"><div class="method-workflow-icon">${LOGIN_ICONS[role().toLowerCase()]||LOGIN_ICONS.qc}</div><div><small>ANALYTICAL METHOD · ${esc(role())}</small><h2>${esc(title)}</h2><p>${esc(description)}</p></div><div class="method-flow">QC prepares <span>→</span> QA reviews <span>→</span> Approved method</div></div>`+
 `<div class="method-overview">${counts.map(([status,value])=>`<button type="button" class="method-overview-card" data-status="${esc(status)}" onclick="methodFilterStatus('${status}')"><span>${esc(status==='All'?'Total Methods':status)}</span><strong>${value}</strong></button>`).join('')}</div>`+
 methodQueue()+`<div class="panel method-list-panel"><div class="toolbar"><div class="filters"><input class="input" id="methodQ" placeholder="Search Method ID, Method Name, Product/Material, Version..." oninput="filterMethods()"><select class="select" id="methodStatus" onchange="filterMethods()"><option>All</option><option>Approved</option><option>Pending QA Approval</option><option>Draft</option><option>Rejected</option><option>Request Revision</option></select></div></div><div id="methodTable"></div></div>`;filterMethods()
}
function filterMethods(){
 const q=(document.getElementById('methodQ')?.value||'').toLowerCase(),status=document.getElementById('methodStatus')?.value||'All';
 const arr=state.methods.filter(m=>(status==='All'||m.status===status)&&JSON.stringify(m).toLowerCase().includes(q));
 document.querySelectorAll('.method-overview-card').forEach(el=>{el.classList.toggle('active',el.dataset.status===status);el.querySelector('strong').textContent=el.dataset.status==='All'?state.methods.length:state.methods.filter(m=>m.status===el.dataset.status).length});const queue=document.getElementById('methodQueue');if(queue)queue.outerHTML=methodQueue();
 document.getElementById('methodTable').innerHTML=arr.length?`<div class="table-wrap"><table class="table method-list-table"><thead><tr><th class="method-select-col"><input type="checkbox" aria-label="Select all methods" onchange="toggleAllMethods(this.checked)"></th><th>No.</th><th>Method ID</th><th>Method Name</th><th>Product/Material</th><th>Version</th><th>Status</th><th>Last Modified</th><th>Actions</th></tr></thead><tbody>${arr.map((m,i)=>`<tr><td class="method-select-col" onclick="event.stopPropagation()"><input type="checkbox" class="method-row-check" value="${esc(m.id)}" aria-label="Select method ${i+1}"></td><td>${i+1}</td><td><b>${esc(m.methodId)}</b></td><td>${esc(m.name)}<small class="method-next-step">${esc(methodNextStep(m))}</small></td><td>${esc(m.product)}</td><td>${esc(m.version)}</td><td>${badge(m.status)}</td><td>${esc(m.lastModified)}</td><td><div class="actions"><button class="btn" onclick="viewMethod('${m.id}')">View</button>${role()==='QA'&&m.status==='Pending QA Approval'?`<button class="btn blue" onclick="qaReview('${m.id}')">Review</button>`:''}${role()==='QC'&&!['Pending QA Approval','Approved'].includes(m.status)?`<button class="btn" onclick="editMethod('${m.id}')">Edit</button>`:''}${role()==='QC'&&m.status==='Draft'?`<button class="btn danger" onclick="deleteMethod('${m.id}')">Delete</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No methods match this search or status. Try another filter.</div>';
}

function suitabilityRows(m,editable=false){
 const s=m.systemSuitability||{};
 const defs=[
  {key:'retentionTime',label:'Retention Time',criteria:'4.0–6.0 min',unit:'min',test:v=>v!==''&&Number(v)>=4&&Number(v)<=6},
  {key:'resolution',label:'Resolution',criteria:'≥ 2.0',unit:'',test:v=>v!==''&&Number(v)>=2},
  {key:'tailingFactor',label:'Tailing Factor',criteria:'≤ 2.0',unit:'',test:v=>v!==''&&Number(v)<=2},
  {key:'theoreticalPlates',label:'Theoretical Plates',criteria:'≥ 2000',unit:'',test:v=>v!==''&&Number(v)>=2000},
  {key:'rsdPeakArea',label:'%RSD (Peak Area)',criteria:'≤ 2.0%',unit:'%',test:v=>v!==''&&Number(v)<=2}
 ];
 return defs.map(d=>{
   const value=s[d.key]??'';
   const status=value===''?'Not Evaluated':(d.test(String(value))?'Pass':'Fail');
   const cls=status==='Pass'?'ss-pass':status==='Fail'?'ss-fail':'ss-ne';
   return `<tr>
     <td><b>${d.label}</b></td>
     <td>${d.criteria}</td>
     <td>${editable
       ? `<input class="input ss-input" type="number" step="any" min="0" value="${esc(value)}" data-ss-key="${d.key}" onchange="updateSuitability('${m.id}',this)">`
       : `<span>${esc(value||'')}</span>`}</td>
     <td>${d.unit}</td>
     <td><span id="ss-status-${d.key}-${m.id}" class="${cls}">${status}</span></td>
   </tr>`;
 }).join('');
}
function suitabilityBody(m,editable=false){
 return `<div class="panel system-suitability-panel">
   <div class="panel-head"><h3>System Suitability</h3></div>
   <div class="table-wrap"><table class="table suitability-table">
    <thead><tr><th>Parameter</th><th>Acceptance Criteria</th><th>Actual Result</th><th>Unit</th><th>Status</th></tr></thead>
    <tbody>${suitabilityRows(m,editable)}</tbody>
   </table></div>
 </div>`;
}
function updateIsocraticComposition(id,key,input){if(role()!=='QC'||['Pending QA Approval','Approved'].includes(state.methods.find(x=>x.id===id)?.status))return;
 const m=state.methods.find(x=>x.id===id);
 if(!m)return;
 m.chromatographicConditions=m.chromatographicConditions||{};
 m.chromatographicConditions.isocraticComposition=m.chromatographicConditions.isocraticComposition||{a:'70',b:'30'};
 m.chromatographicConditions.isocraticComposition[key]=input.value;
 save();
}
function updateSuitability(id,input){if(role()!=='QC'||['Pending QA Approval','Approved'].includes(state.methods.find(x=>x.id===id)?.status))return;
 const m=state.methods.find(x=>x.id===id);
 if(!m)return;
 m.systemSuitability=m.systemSuitability||{};
 m.systemSuitability[input.dataset.ssKey]=input.value;
 save();
 const s=m.systemSuitability;
 const defs={
  retentionTime:v=>v!==''&&Number(v)>=4&&Number(v)<=6,
  resolution:v=>v!==''&&Number(v)>=2,
  tailingFactor:v=>v!==''&&Number(v)<=2,
  theoreticalPlates:v=>v!==''&&Number(v)>=2000,
  rsdPeakArea:v=>v!==''&&Number(v)<=2
 };
 const value=input.value;
 const status=value===''?'Not Evaluated':(defs[input.dataset.ssKey](value)?'Pass':'Fail');
 const el=document.getElementById(`ss-status-${input.dataset.ssKey}-${id}`);
 if(el){
   el.textContent=status;
   el.className=status==='Pass'?'ss-pass':status==='Fail'?'ss-fail':'ss-ne';
 }
}
function viewMethod(id){currentMethodId=id;const m=state.methods.find(x=>x.id===id);if(m)openMethodModal(m,false)}
function editMethod(id){if(role()!=='QC'){viewMethod(id);return}const m=state.methods.find(x=>x.id===id);if(!m||['Pending QA Approval','Approved'].includes(m.status)){alert('This method is locked for editing.');return}currentMethodId=id;if(window.__methodDraft)delete window.__methodDraft[id];openMethodModal(m,true)}
function openMethodModal(m,editable){let active='details';openModal(`${esc(m.methodId)} — ${esc(m.name)}`,`<div class="method-detail-flow"><span>${badge(m.status)}</span><b>${esc(methodNextStep(m))}</b><small>QC prepares → QA reviews → Approved method</small></div><div class="tabs"><button class="tab active" onclick="methodTab('${m.id}','details',${editable},this)">Method Details</button><button class="tab" onclick="methodTab('${m.id}','conditions',${editable},this)">Chromatographic Conditions</button><button class="tab" onclick="methodTab('${m.id}','suitability',${editable},this)">System Suitability</button><button class="tab" onclick="methodTab('${m.id}','attachments',${editable},this)">Attachments</button><button class="tab" onclick="methodTab('${m.id}','history',${editable},this)">Revision History</button></div><div id="methodTabBody">${methodBody(m,active,editable)}</div>${!editable&&m.status==='Pending QA Approval'&&role()==='QA'?`<div class="notice">This method was submitted by QC and requires QA review.</div>`:''}${!editable&&m.review?.decision?reviewBlock(m):''}${!editable&&(role()==='QC'||role()==='QA')?discussionBlock(m):''}`,editable?`<button class="btn" onclick="downloadMethodPDF('${m.id}')">Download PDF</button><button class="btn" onclick="closeModal()">Cancel</button><button class="btn" onclick="saveMethod('${m.id}')">Save Method</button><button class="btn blue" onclick="sendQA('${m.id}')">Send to QA</button>`:role()==='QA'&&m.status==='Pending QA Approval'?`<button class="btn" onclick="downloadMethodPDF('${m.id}')">Download PDF</button><button class="btn" onclick="closeModal()">Cancel</button><button class="btn blue" onclick="qaReview('${m.id}')">Review Method</button>`:`<button class="btn" onclick="downloadMethodPDF('${m.id}')">Download PDF</button><button class="btn" onclick="closeModal()">Close</button>`)}
function methodTab(id,tab,editable,el){
 const m=state.methods.find(x=>x.id===id);if(!m)return;
 if(editable&&document.getElementById('f_methodId'))methodCaptureDraft(id);
 document.querySelectorAll('.tabs .tab').forEach(x=>x.classList.remove('active'));el.classList.add('active');
 document.getElementById('methodTabBody').innerHTML=methodBody(editable?{...m,...(window.__methodDraft?.[id]||{})}:m,tab,editable);
}
function methodCaptureDraft(id){
 const keys={methodId:'f_methodId',name:'f_name',product:'f_product',version:'f_version',category:'f_category',reference:'f_reference',description:'f_description'};
 window.__methodDraft=window.__methodDraft||{};window.__methodDraft[id]=Object.fromEntries(Object.entries(keys).map(([key,field])=>[key,document.getElementById(field).value.trim()]));
}
function reviewBlock(m){return `<div class="panel" style="margin-top:12px;background:#fafcff"><b style="font-size:10px">QA Review</b><p style="font-size:9px">Reviewed by <b>${esc(m.review.by)}</b> on ${esc(m.review.date)} — ${badge(m.review.decision)}</p><p style="font-size:9px">${esc(m.review.comment||'No comment')}</p></div>`}
function discussionBlock(m){
 const messages=m.chat||[];
 return `<div class="panel discussion-panel" style="margin-top:12px;background:#fafcff">
 <div class="panel-head"><h3>Discussion</h3><small>${messages.length} message${messages.length===1?'':'s'}</small></div>
 <div class="chat discussion-chat">${messages.length?messages.map(x=>`<div class="msg ${x.user===state.session.username?'me':''}"><small>${esc(x.user)} · ${esc(x.date)}</small><div>${esc(x.text)}</div></div>`).join(''):`<div class="empty">No discussion yet.<br><small>Messages sent by QC or QA will appear here.</small></div>`}</div>
 <div style="display:flex;gap:6px;margin-top:7px">
 <input id="chatInput" class="input" style="flex:1" placeholder="Type a message..." onkeydown="if(event.key==='Enter'){event.preventDefault();sendChat('${m.id}')}">
 <button class="btn blue" onclick="sendChat('${m.id}')">Send</button>
 </div>
 </div>`;
}
function addMethod(){if(role()!=='QC')return;const m={id:uid('M'),methodId:'',name:'',product:'',version:'V1.0',status:'Draft',lastModified:now(),category:'',description:'',reference:'',attachments:[],revisions:[],chat:[],systemSuitability:{retentionTime:'',resolution:'',tailingFactor:'',theoreticalPlates:'',rsdPeakArea:''},chromatographicConditions:{column:'',mobilePhaseA:'',mobilePhaseB:'',columnTemperature:'',injectionVolume:'',elutionMode:'Isocratic',isocraticComposition:{a:'70',b:'30'},flowRate:'',detectionWavelength:'',runTime:'',sampleTemperature:'',isocraticComposition:{a:'70',b:'30'},gradientProgram:[{time:'0',a:'95',b:'5'},{time:'5',a:'80',b:'20'},{time:'10',a:'60',b:'40'},{time:'12',a:'60',b:'40'},{time:'12.1',a:'95',b:'5'},{time:'15',a:'95',b:'5'}]}};openModal('Add New Method',methodBody(m,'details',true),`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="createMethod()">Save Method</button>`)}
function readForm(m){if(document.getElementById('f_methodId'))methodCaptureDraft(m.id);Object.assign(m,window.__methodDraft?.[m.id]||{});m.lastModified=now()}
function validateMethod(m){if(!m.methodId||!m.name||!m.product||!m.version||!m.category)return 'Please complete all required method fields.';if(state.methods.some(x=>x.methodId===m.methodId&&x.id!==m.id))return 'Method ID already exists.';return ''}
function createMethod(){if(role()!=='QC')return;const m={id:uid('M'),methodId:'',name:'',product:'',version:'V1.0',status:'Draft',lastModified:now(),category:'',description:'',reference:'',attachments:[],revisions:[],chat:[],chromatographicConditions:{column:'',mobilePhaseA:'',mobilePhaseB:'',columnTemperature:'',injectionVolume:'',elutionMode:'Isocratic',isocraticComposition:{a:'70',b:'30'},flowRate:'',detectionWavelength:'',runTime:'',sampleTemperature:'',isocraticComposition:{a:'70',b:'30'},gradientProgram:[{time:'0',a:'95',b:'5'},{time:'5',a:'80',b:'20'},{time:'10',a:'60',b:'40'},{time:'12',a:'60',b:'40'},{time:'12.1',a:'95',b:'5'},{time:'15',a:'95',b:'5'}]},systemSuitability:{retentionTime:'',resolution:'',tailingFactor:'',theoreticalPlates:'',rsdPeakArea:''}};m.methodId=document.getElementById('f_methodId').value.trim();m.name=document.getElementById('f_name').value.trim();m.product=document.getElementById('f_product').value.trim();m.version=document.getElementById('f_version').value.trim();m.status='Draft';m.category=document.getElementById('f_category').value.trim();m.reference=document.getElementById('f_reference').value.trim();m.description=document.getElementById('f_description').value.trim();let e=validateMethod(m);if(e){alert(e);return}m.revisions.push({date:now(),user:state.session.username,action:'Save',changes:'Initial method creation',version:m.version});state.methods.push(m);log('Create Method',m.methodId);save();closeModal();renderMethods(document.getElementById('content'))}
function saveMethod(id){const m=state.methods.find(x=>x.id===id);if(role()!=='QC'||!m||['Pending QA Approval','Approved'].includes(m.status))return;readForm(m);let e=validateMethod(m);if(e){alert(e);return}m.revisions=m.revisions||[];m.revisions.unshift({date:now(),user:state.session.username,action:'Save',changes:'Updated method information/details',version:m.version});log('Save Method',m.methodId);save();delete window.__methodDraft?.[id];closeModal();filterMethods()}
function sendQA(id){const m=state.methods.find(x=>x.id===id);if(role()!=='QC'||!m||['Pending QA Approval','Approved'].includes(m.status))return;if(document.getElementById('f_methodId'))methodCaptureDraft(id);const changes=window.__methodDraft?.[id];if(changes){const candidate={...m,...changes},error=validateMethod(candidate);if(error){alert(error);return}Object.assign(m,changes);m.lastModified=now();save();delete window.__methodDraft[id]}openModal('Send to QA',`<div class="notice">The method will be locked after submission and sent to the QA review queue.</div><div class="field"><label>Comment (optional)</label><textarea id="sendComment" class="textarea" placeholder="Write a comment to QA..."></textarea></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn blue" onclick="confirmSendQA('${id}')">Send to QA</button>`)}
function confirmSendQA(id){const m=state.methods.find(x=>x.id===id);if(role()!=='QC'||!m||['Pending QA Approval','Approved'].includes(m.status))return;m.status='Pending QA Approval';m.sendComment=document.getElementById('sendComment').value;m.lastModified=now();m.revisions.unshift({date:now(),user:state.session.username,action:'Submit',changes:'Submitted for QA approval',version:m.version});state.notifications.push({text:`${m.methodId} is waiting for QA approval.`});log('Send to QA',m.methodId);save();closeModal();filterMethods()}
function qaReview(id){const m=state.methods.find(x=>x.id===id);if(role()!=='QA'||m?.status!=='Pending QA Approval')return;openModal('QA Review',`<div class="notice">Submitted by ${esc(m.revisions?.[0]?.user||'QC')} · ${esc(m.lastModified)}</div><div class="field"><label>Approval Decision</label><select id="decision" class="select" style="width:100%"><option>Approve</option><option>Request Revision</option><option>Reject</option></select></div><div class="field" style="margin-top:10px"><label>Review Comment</label><textarea id="qaComment" class="textarea" placeholder="Explain your QA decision to QC..."></textarea></div><div class="notice">Electronic signature required. Enter QA password to submit review.</div><div class="field"><label>QA Password</label><input id="qaPass" type="password" class="input" style="width:100%" placeholder="Password"></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn blue" onclick="submitQAReview('${id}')">Submit Review</button>`)}
function submitQAReview(id){if(role()!=='QA'||state.methods.find(x=>x.id===id)?.status!=='Pending QA Approval')return;if(document.getElementById('qaPass').value!=='qa123'){alert('Invalid QA electronic signature password.');return}if(document.getElementById('decision').value!=='Approve'&&!document.getElementById('qaComment').value.trim()){alert('Explain the revision or rejection to QC.');return}const m=state.methods.find(x=>x.id===id),d=document.getElementById('decision').value;m.review={by:state.session.username,date:now(),decision:d,comment:document.getElementById('qaComment').value};m.status=d==='Approve'?'Approved':d==='Reject'?'Rejected':'Request Revision';m.revisions.unshift({date:now(),user:state.session.username,action:d,changes:'QA review submitted',version:m.version});state.notifications.push({text:`${m.methodId}: QA decision ${d}.`});log('Submit QA Review',`${m.methodId} — ${d}`);save();closeModal();filterMethods()}
function sendChat(id){
 if(!['QC','QA'].includes(role()))return;
 const m=state.methods.find(x=>x.id===id);
 const input=document.getElementById('chatInput');
 if(!m||!input)return;
 const v=input.value.trim();
 if(!v)return;
 m.chat=m.chat||[];
 m.chat.push({user:state.session.username,date:now(),text:v});
 log('Discussion',m.methodId);
 save();
 openMethodModal(m,false);
}
function submitRevision(id){const m=state.methods.find(x=>x.id===id);if(role()!=='QC'||m?.status!=='Request Revision')return;openModal('Submit Revision',`<div class="field"><label>Revision Comment</label><textarea id="revComment" class="textarea"></textarea></div><div class="field" style="margin-top:10px"><label>Attach Evidence</label><input id="revFile" type="file" class="input"></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn blue" onclick="confirmRevision('${id}')">Submit Revision to QA</button>`)}
function confirmRevision(id){const m=state.methods.find(x=>x.id===id);if(role()!=='QC'||m?.status!=='Request Revision')return;m.status='Pending QA Approval';m.revisionComment=document.getElementById('revComment').value;m.revisions.unshift({date:now(),user:state.session.username,action:'Revision Submitted',changes:m.revisionComment||'Revision submitted',version:m.version});log('Submit Revision',m.methodId);save();closeModal();filterMethods()}
function deleteMethod(id){const m=state.methods.find(x=>x.id===id);if(role()!=='QC'||m?.status!=='Draft')return;openModal('Delete Method',`<div class="notice danger-note">This action cannot be undone. The deletion will be recorded in revision history/audit trail.</div><p style="font-size:10px"><b>${esc(m.methodId)}</b> · ${esc(m.name)} · ${esc(m.version)}</p>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn danger" onclick="confirmDelete('${id}')">Delete</button>`)}
function confirmDelete(id){const m=state.methods.find(x=>x.id===id);if(role()!=='QC'||m?.status!=='Draft')return;state.methods=state.methods.filter(x=>x.id!==id);log('Delete Method',m.methodId);save();closeModal();filterMethods()}
function uploadAttachment(id,file){if(role()!=='QC'||!file||['Pending QA Approval','Approved'].includes(state.methods.find(x=>x.id===id)?.status))return;if(file.size>5*1024*1024){alert('Maximum file size is 5 MB.');return}const r=new FileReader();r.onload=()=>{const m=state.methods.find(x=>x.id===id);m.attachments=m.attachments||[];m.attachments.push({name:file.name,size:file.size,type:file.type,data:r.result});m.revisions.unshift({date:now(),user:state.session.username,action:'Upload Evidence',changes:file.name,version:m.version});log('Upload Evidence',file.name);save();openMethodModal(m,false)};r.readAsDataURL(file)}
function previewAttachment(id,i){const a=state.methods.find(x=>x.id===id).attachments[i];if(a.type.startsWith('image/')||a.type==='application/pdf'){openModal('Evidence Preview',`<div style="text-align:center">${a.type.startsWith('image/')?`<img src="${a.data}" style="max-width:100%;max-height:60vh">`:`<iframe src="${a.data}" style="width:100%;height:55vh;border:0"></iframe>`}</div>`)}else alert('Preview is available for images and PDF files. Use Download for this file type.')}
function downloadAttachment(id,i){const a=state.methods.find(x=>x.id===id).attachments[i],link=document.createElement('a');link.href=a.data;link.download=a.name;link.click()}
function removeAttachment(id,i){if(role()!=='QC'||['Pending QA Approval','Approved'].includes(state.methods.find(x=>x.id===id)?.status))return;const m=state.methods.find(x=>x.id===id);m.attachments.splice(i,1);log('Delete Evidence',m.methodId);save();openMethodModal(m,false)}
function exportMethods(){window.print()}


function sequenceRoleCanEdit(){return ['QC','ADMIN'].includes(String(role()).toUpperCase())}
function sequenceRoleCanRun(){return ['QC','ADMIN'].includes(String(role()).toUpperCase())}
function sequenceData(){
  state.sequences=Array.isArray(state.sequences)?state.sequences:[];
  state.sequences.forEach(s=>{
    s.injectionList=Array.isArray(s.injectionList)?s.injectionList:(Array.isArray(s.injections)?(typeof s.injections[0]==='object'?s.injections:[]):[]);
    if(typeof s.injections!=='number') s.injections=s.injectionList.length;
    if(!s.status) s.status='Draft';
  });
  return state.sequences;
}
function selectedSequence(){return sequenceData().find(s=>s.id===window.__selectedSequenceId)||sequenceData()[0]||null}
function seqMethod(id){return state.methods.find(m=>m.id===id||m.methodId===id)||null}
function seqInstrument(id){return state.instruments.find(i=>i.id===id||i.idn===id)||null}
function seqMethodLabel(id){const m=seqMethod(id);return m?`${m.methodId||''}${m.name?' — '+m.name:''}`:id||'—'}
function seqInstrumentLabel(id){const i=seqInstrument(id);return i?`${i.idn||''}${i.name?' — '+i.name:''}`:id||'—'}
function seqNextId(){const n=sequenceData().reduce((a,s)=>Math.max(a,parseInt(String(s.idn||'').match(/(\d+)$/)?.[1]||0)),0)+1;return `SEQ-${new Date().toISOString().slice(0,10).replace(/-/g,'')}-${String(n).padStart(3,'0')}`}
function injNextId(s){const n=(s.injectionList||[]).reduce((a,x)=>Math.max(a,parseInt(String(x.injectionId||'').match(/(\d+)$/)?.[1]||0)),0)+1;return `INJ-${String(n).padStart(3,'0')}`}
function syncSequence(s){s.injectionList=Array.isArray(s.injectionList)?s.injectionList:[];s.injections=s.injectionList.length;return s}
function sequenceStatusClass(s){return {'Draft':'draft','Ready':'pending','In Progress':'pending','Completed':'approved','Aborted':'rejected'}[s]||'draft'}
function seqBadge(s){return `<span class="badge ${sequenceStatusClass(s)}">${esc(s||'Draft')}</span>`}
function renderSequence(c){
  const seqs=sequenceData(); if(!window.__selectedSequenceId&&seqs[0])window.__selectedSequenceId=seqs[0].id;
  const sel=selectedSequence();
  c.innerHTML=header('Sequence','Manage HPLC-UV injection sequences and sample order.',`<div class="seq-actions"><button class="btn primary" ${sequenceRoleCanEdit()?'':'disabled'} onclick="addSequence()">＋ Add Sequence</button><button class="btn blue" ${sequenceRoleCanRun()?'':'disabled'} onclick="runSelectedSequence()">▶ Run Sequence</button><button class="btn" onclick="exportSequenceData()">Export</button><button class="btn" onclick="printSequence()">Print</button></div>`)+
  `<div class="panel seq-filter-panel"><div class="panel-head"><h3>Search & Filter</h3></div><div class="seq-filter-grid"><input id="seqSearch" class="input" placeholder="Search Sequence ID or Name"><select id="seqMethodFilter" class="select"><option value="">All Methods</option>${state.methods.map(m=>`<option value="${esc(m.id)}">${esc(m.methodId)} — ${esc(m.name)}</option>`).join('')}</select><select id="seqStatusFilter" class="select"><option value="">All Status</option>${['Draft','Ready','In Progress','Completed','Aborted'].map(x=>`<option>${x}</option>`).join('')}</select><input id="seqDateFrom" type="date" class="input"><input id="seqDateTo" type="date" class="input"><button class="btn" onclick="resetSequenceFilters()">Reset</button><button class="btn primary" onclick="filterSequences()">Search</button></div></div>
  <div class="panel"><div class="panel-head"><h3>Sequence List</h3><small id="seqCount">${seqs.length} sequence${seqs.length===1?'':'s'}</small></div><div class="table-wrap" id="sequenceTable"></div></div>
  <div id="sequenceDetailsArea">${sel?sequenceDetailsMarkup(sel):'<div class="panel"><div class="empty">Select or create a sequence to view details.</div></div>'}</div>`;
  filterSequences();
}
function filteredSequences(){const q=(document.getElementById('seqSearch')?.value||'').trim().toLowerCase(),mf=document.getElementById('seqMethodFilter')?.value||'',sf=document.getElementById('seqStatusFilter')?.value||'',df=document.getElementById('seqDateFrom')?.value||'',dt=document.getElementById('seqDateTo')?.value||'';return sequenceData().filter(s=>{const txt=`${s.idn||''} ${s.name||''}`.toLowerCase();const d=String(s.date||'').slice(0,10);return (!q||txt.includes(q))&&(!mf||s.method===mf)&&(!sf||s.status===sf)&&(!df||d>=df)&&(!dt||d<=dt)})}
function filterSequences(){const arr=filteredSequences();const box=document.getElementById('sequenceTable');if(!box)return;box.innerHTML=arr.length?`<table class="table sequence-table"><thead><tr><th><input type="checkbox" onchange="toggleAllSequences(this)"></th><th>No.</th><th>Sequence ID</th><th>Sequence Name</th><th>Method</th><th>Instrument</th><th>Created By</th><th>Date Created</th><th>Total Injections</th><th>Status</th><th>Actions</th></tr></thead><tbody>${arr.map((s,i)=>{syncSequence(s);return `<tr class="seq-row ${selectedSequence()?.id===s.id?'selected':''}" onclick="selectSequence('${s.id}')"><td onclick="event.stopPropagation()"><input type="checkbox" class="seq-check" value="${s.id}"></td><td>${i+1}</td><td><b>${esc(s.idn)}</b></td><td>${esc(s.name)}</td><td>${esc(seqMethodLabel(s.method))}</td><td>${esc(seqInstrumentLabel(s.instrument))}</td><td>${esc(s.createdBy||'—')}</td><td>${esc(s.date||'—')}</td><td>${s.injectionList.length}</td><td>${seqBadge(s.status)}</td><td class="actions" onclick="event.stopPropagation()"><button class="btn mini-btn" ${sequenceRoleCanRun()?'':'disabled'} onclick="runSequence('${s.id}')">▶</button><button class="btn mini-btn" onclick="viewSequence('${s.id}')">👁</button><button class="btn mini-btn" onclick="sequenceReport('${s.id}')">📄</button><button class="btn mini-btn" ${sequenceRoleCanEdit()?'':'disabled'} onclick="editSequence('${s.id}')">✏</button><button class="btn danger mini-btn" ${sequenceRoleCanEdit()?'':'disabled'} onclick="removeSequence('${s.id}')">🗑</button></td></tr>`}).join('')}</tbody></table>`:'<div class="empty">No sequence matches the current filter.</div>';const count=document.getElementById('seqCount');if(count)count.textContent=`${arr.length} sequence${arr.length===1?'':'s'}`}
function toggleAllSequences(el){document.querySelectorAll('.seq-check').forEach(x=>x.checked=el.checked)}
function resetSequenceFilters(){['seqSearch','seqMethodFilter','seqStatusFilter','seqDateFrom','seqDateTo'].forEach(id=>{const e=document.getElementById(id);if(e)e.value=''});filterSequences()}
function selectSequence(id){window.__selectedSequenceId=id;renderSequence(document.getElementById('content'))}
function sequenceDetailsMarkup(s){syncSequence(s);return `<div class="panel sequence-details"><div class="panel-head"><h3>Sequence Details</h3><div><button class="btn" ${sequenceRoleCanEdit()?'':'disabled'} onclick="editSequence('${s.id}')">Edit</button></div></div><div class="detail-grid"><div class="detail-item"><span>Sequence ID</span><b>${esc(s.idn)}</b></div><div class="detail-item"><span>Sequence Name</span><b>${esc(s.name)}</b></div><div class="detail-item"><span>Analytical Method</span><b>${esc(seqMethodLabel(s.method))}</b></div><div class="detail-item"><span>Instrument</span><b>${esc(seqInstrumentLabel(s.instrument))}</b></div><div class="detail-item"><span>Created By</span><b>${esc(s.createdBy||'—')}</b></div><div class="detail-item"><span>Date Created</span><b>${esc(s.date||'—')}</b></div><div class="detail-item"><span>Status</span><b>${seqBadge(s.status)}</b></div><div class="detail-item"><span>Total Injections</span><b>${s.injectionList.length}</b></div></div><div class="detail-item" style="margin-top:8px"><span>Comments</span>${esc(s.comments||'No comments')}</div></div><div class="panel"><div class="panel-head"><h3>Injection List (${esc(s.idn)})</h3><div class="seq-actions-inline"><button class="btn primary" ${sequenceRoleCanEdit()?'':'disabled'} onclick="addInjection('${s.id}')">＋ Add Injection</button><button class="btn" onclick="importInjectionData('${s.id}')">Import</button><button class="btn" ${sequenceRoleCanEdit()?'':'disabled'} onclick="deleteSelectedInjections('${s.id}')">Delete</button><button class="btn" ${sequenceRoleCanEdit()?'':'disabled'} onclick="reorderInjections('${s.id}')">Reorder</button></div></div>${injectionTableMarkup(s)}</div>`}
function injectionTableMarkup(s){syncSequence(s);return s.injectionList.length?`<div class="table-wrap"><table class="table injection-table"><thead><tr><th><input type="checkbox" onchange="toggleAllInjections(this)"></th><th>No.</th><th>Injection ID</th><th>Sample Name</th><th>Sample Type</th><th>Vial Position</th><th>RT (min)</th><th>Status</th><th>Actions</th></tr></thead><tbody>${s.injectionList.map((x,i)=>`<tr><td onclick="event.stopPropagation()"><input type="checkbox" class="inj-check" value="${x.id}"></td><td>${i+1}</td><td><b>${esc(x.injectionId)}</b></td><td>${esc(x.sampleName)}</td><td>${esc(x.sampleType)}</td><td>${esc(x.vialPosition)}</td><td>${x.result?.rt!=null?esc(x.result.rt):'—'}</td><td>${seqBadge(x.status||'Pending')}</td><td class="actions"><button class="btn mini-btn" onclick="viewInjection('${s.id}','${x.id}')">👁</button><button class="btn mini-btn" onclick="viewInjectionResult('${s.id}','${x.id}')">📄</button><button class="btn mini-btn" onclick="viewInjectionChromatogram('${s.id}','${x.id}')">📈</button><button class="btn mini-btn" ${sequenceRoleCanEdit()?'':'disabled'} onclick="deleteInjection('${s.id}','${x.id}')">🗑</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No injections added yet. Add an injection to build the run order.</div>'}
function toggleAllInjections(el){document.querySelectorAll('.inj-check').forEach(x=>x.checked=el.checked)}
function refreshSequenceDetails(){const s=selectedSequence();if(s){syncSequence(s);document.getElementById('sequenceDetailsArea').innerHTML=sequenceDetailsMarkup(s)}filterSequences()}
function addSequence(editId){if(!sequenceRoleCanEdit()){alert('Only QC or Admin can create/edit sequences.');return}const s=editId?sequenceData().find(x=>x.id===editId):{id:uid('SEQ'),idn:seqNextId(),name:'',date:new Date().toISOString().slice(0,10),startTime:'',endTime:'',method:'',instrument:'',plannedInjections:1,purpose:'Routine Assay',comments:'',status:'Draft',createdBy:state.session.username,injectionList:[]};if(!s)return;openModal(editId?'Edit Sequence':'Add New Sequence',`<div class="formgrid"><div class="field"><label>Sequence ID *</label><input id="sq_id" class="input" value="${esc(s.idn)}"></div><div class="field"><label>Sequence Name *</label><input id="sq_name" class="input" value="${esc(s.name)}"></div><div class="field"><label>Date *</label><input id="sq_date" type="date" class="input" value="${esc(s.date)}"></div><div class="field"><label>Start Time *</label><input id="sq_start" type="time" class="input" value="${esc(s.startTime)}"></div><div class="field"><label>End Time (Estimated) *</label><input id="sq_end" type="time" class="input" value="${esc(s.endTime)}"></div><div class="field"><label>Analytical Method *</label><select id="sq_method" class="select"><option value="">Select method</option>${state.methods.map(m=>`<option value="${esc(m.id)}" ${s.method===m.id?'selected':''}>${esc(m.methodId)} — ${esc(m.name)}</option>`).join('')}</select></div><div class="field"><label>Instrument *</label><input id="sq_instrument" class="input" list="sequenceInstrumentOptions" value="${esc(seqInstrumentLabel(s.instrument)==='—'?'':seqInstrumentLabel(s.instrument))}" placeholder="Type Instrument ID or Name" autocomplete="off"><datalist id="sequenceInstrumentOptions">${state.instruments.map(i=>`<option value="${esc(i.idn)}">${esc(i.name||'')}</option>`).join('')}</datalist></div><div class="field"><label>Total Injections (Planned) *</label><input id="sq_planned" type="number" min="1" class="input" value="${esc(s.plannedInjections||1)}"></div><div class="field"><label>Sample Set / Purpose *</label><select id="sq_purpose" class="select">${['Routine Assay','System Suitability','Validation','Other'].map(x=>`<option ${s.purpose===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field" style="margin-top:10px"><label>Comments *</label><textarea id="sq_comments" class="textarea">${esc(s.comments||'')}</textarea></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveSequence('${editId||''}')">${editId?'Save Changes':'Create Sequence'}</button>`)}
function saveSequence(id){if(!sequenceRoleCanEdit())return;const x=id?sequenceData().find(s=>s.id===id):{id:uid('SEQ'),injectionList:[]};x.idn=document.getElementById('sq_id').value.trim();x.name=document.getElementById('sq_name').value.trim();x.date=document.getElementById('sq_date').value;x.startTime=document.getElementById('sq_start').value;x.endTime=document.getElementById('sq_end').value;x.method=document.getElementById('sq_method').value;const instrumentInput=document.getElementById('sq_instrument').value.trim();const instrumentMatch=state.instruments.find(i=>i.id===instrumentInput||i.idn===instrumentInput||`${i.idn||''} — ${i.name||''}`===instrumentInput||String(i.name||'').toLowerCase()===instrumentInput.toLowerCase());x.instrument=instrumentMatch?instrumentMatch.id:instrumentInput;x.plannedInjections=Number(document.getElementById('sq_planned').value);x.purpose=document.getElementById('sq_purpose').value;x.comments=document.getElementById('sq_comments').value.trim();x.createdBy=x.createdBy||state.session.username;x.status=x.injectionList?.length?'Ready':'Draft';if(!x.idn||!x.name||!x.date||!x.startTime||!x.endTime||!x.method||!x.instrument||!x.plannedInjections||x.plannedInjections<1||!x.purpose||!x.comments){alert('Please complete all required sequence fields.');return}if(sequenceData().some(s=>s.idn===x.idn&&s.id!==x.id)){alert('Sequence ID must be unique.');return}if(!seqMethod(x.method)){alert('Please select an Analytical Method from the available saved methods.');return}if(!x.instrument){alert('Please enter an Instrument.');return}syncSequence(x);if(!id)state.sequences.push(x);log(id?'Edit Sequence':'Create Sequence',x.idn);save();window.__selectedSequenceId=x.id;closeModal();renderSequence(document.getElementById('content'))}
function editSequence(id){addSequence(id)}
function removeSequence(id){if(!sequenceRoleCanEdit())return;const s=sequenceData().find(x=>x.id===id);if(!s)return;syncSequence(s);const warn=s.injectionList.some(x=>x.status==='Completed'&&x.result);if(!confirm(`Delete sequence ${s.idn} with ${s.injectionList.length} injection(s)?${warn?' Some completed injections have results.':''}`))return;state.sequences=state.sequences.filter(x=>x.id!==id);if(window.__selectedSequenceId===id)window.__selectedSequenceId=state.sequences[0]?.id||null;log('Delete Sequence',s.idn);save();renderSequence(document.getElementById('content'))}
function addInjection(seqId,editId){if(!sequenceRoleCanEdit()){alert('Only QC or Admin can add/edit injections.');return}const s=sequenceData().find(x=>x.id===seqId);if(!s)return;syncSequence(s);const old=editId?s.injectionList.find(x=>x.id===editId):null,m=seqMethod(s.method);const x=old||{id:uid('INJ'),injectionId:injNextId(s),sampleName:'',sampleType:'Sample',vialPosition:'',status:'Pending',result:null};const cc=m?.chromatographicConditions||{};openModal(editId?'Edit Injection':'Add Injection',`<div class="formgrid"><div class="field"><label>Sequence ID *</label><input class="input" value="${esc(s.idn)}" disabled></div><div class="field"><label>Method *</label><input class="input" value="${esc(seqMethodLabel(s.method))}" disabled></div><div class="field"><label>Injection ID *</label><input id="inj_id" class="input" value="${esc(x.injectionId)}" disabled></div><div class="field"><label>Sample Name *</label><input id="inj_name" class="input" value="${esc(x.sampleName)}"></div><div class="field"><label>Sample Type *</label><select id="inj_type" class="select">${['Blank','Standard','Sample','QC'].map(t=>`<option ${x.sampleType===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>Vial Position *</label><input id="inj_vial" class="input" value="${esc(x.vialPosition)}" placeholder="A01"></div><div class="field"><label>Injection Volume (μL) *</label><input id="inj_vol" type="number" min="0.001" step="0.001" class="input" value="${esc(x.injectionVolume??cc.injectionVolume??'')}"></div><div class="field"><label>Run Time (min) *</label><input id="inj_runtime" type="number" min="0.001" step="0.001" class="input" value="${esc(x.runTime??cc.runTime??'')}"></div><div class="field"><label>Instrument *</label><input class="input" value="${esc(seqInstrumentLabel(s.instrument))}" disabled></div><div class="field"><label>Acquisition Method *</label><input id="inj_acq" class="input" value="${esc(x.acquisitionMethod||'Use sequence method')}"></div><div class="field"><label>Processing Method *</label><input id="inj_proc" class="input" value="${esc(x.processingMethod||'Use sequence method')}"></div><div class="field"><label>Sample Weight / Concentration *</label><input id="inj_conc" class="input" value="${esc(x.concentration||'')}"></div><div class="field"><label>Dilution Factor *</label><input id="inj_dil" class="input" value="${esc(x.dilutionFactor||'')}"></div><div class="field"><label>Start Time *</label><input id="inj_start" type="datetime-local" class="input" value="${esc(x.startTime||'')}"></div><div class="field"><label>Include in Sequence *</label><label style="display:flex;gap:7px;align-items:center"><input id="inj_include" type="checkbox" ${x.includeInSequence!==false?'checked':''}> Include this injection in Run Sequence *</label></div></div><div class="field" style="margin-top:10px"><label>Comments *</label><textarea id="inj_comments" class="textarea">${esc(x.comments||'')}</textarea></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveInjection('${seqId}','${editId||''}')">Save Injection</button>`)}
function saveInjection(seqId,id){if(!sequenceRoleCanEdit())return;const s=sequenceData().find(x=>x.id===seqId);if(!s)return;syncSequence(s);const x=id?s.injectionList.find(i=>i.id===id):{id:uid('INJ'),injectionId:injNextId(s),status:'Pending',result:null};x.sampleName=document.getElementById('inj_name').value.trim();x.sampleType=document.getElementById('inj_type').value;x.vialPosition=document.getElementById('inj_vial').value.trim();x.injectionVolume=document.getElementById('inj_vol').value;x.runTime=document.getElementById('inj_runtime').value;x.acquisitionMethod=document.getElementById('inj_acq').value.trim();x.processingMethod=document.getElementById('inj_proc').value.trim();x.concentration=document.getElementById('inj_conc').value.trim();x.dilutionFactor=document.getElementById('inj_dil').value.trim();x.startTime=document.getElementById('inj_start').value;x.includeInSequence=document.getElementById('inj_include').checked;x.comments=document.getElementById('inj_comments').value.trim();if(!x.sampleName||!x.sampleType||!x.vialPosition||!x.injectionVolume||Number(x.injectionVolume)<=0||!x.runTime||Number(x.runTime)<=0||!seqInstrumentLabel(s.instrument)||!x.acquisitionMethod||!x.processingMethod||!x.concentration||!x.dilutionFactor||!x.startTime||!x.comments){alert('Semua kolom bertanda * wajib diisi. Pastikan Injection Volume (μL) dan Run Time (min) valid.');return}if(s.injectionList.some(i=>i.injectionId===x.injectionId&&i.id!==x.id)){alert('Injection ID must be unique within the sequence.');return}if(!id)s.injectionList.push(x);syncSequence(s);if(s.status==='Draft')s.status='Ready';log(id?'Edit Injection':'Add Injection',`${s.idn} / ${x.injectionId}`);save();closeModal();refreshSequenceDetails()}
function deleteSelectedInjections(seqId){if(!sequenceRoleCanEdit())return;const s=sequenceData().find(x=>x.id===seqId);const ids=[...document.querySelectorAll('.inj-check:checked')].map(x=>x.value);if(!ids.length){alert('Select at least one injection.');return}const items=s.injectionList.filter(x=>ids.includes(x.id));const warn=items.some(x=>x.status==='Completed'&&x.result);if(!confirm(`Delete ${items.length} selected injection(s)?${warn?' Completed results will also be removed.':''}`))return;s.injectionList=s.injectionList.filter(x=>!ids.includes(x.id));syncSequence(s);log('Delete Injection',`${s.idn}: ${ids.length} injection(s)`);save();refreshSequenceDetails()}
function deleteInjection(seqId,id){if(!sequenceRoleCanEdit())return;const s=sequenceData().find(x=>x.id===seqId),x=s?.injectionList.find(i=>i.id===id);if(!x)return;const warn=x.status==='Completed'&&x.result;if(!confirm(`Delete ${x.injectionId}?${warn?' This injection has completed results.':''}`))return;s.injectionList=s.injectionList.filter(i=>i.id!==id);syncSequence(s);log('Delete Injection',`${s.idn} / ${x.injectionId}`);save();refreshSequenceDetails()}
function reorderInjections(seqId){if(!sequenceRoleCanEdit())return;const s=sequenceData().find(x=>x.id===seqId);openModal('Reorder Injection',`<div class="notice">Move injections up/down. This order is persisted and used by Run Sequence.</div><div id="reorderList" class="reorder-list">${s.injectionList.map((x,i)=>`<div class="reorder-item" data-id="${x.id}"><span>${i+1}. <b>${esc(x.injectionId)}</b> — ${esc(x.sampleName)}</span><span><button class="btn mini-btn" onclick="moveInjection('${seqId}','${x.id}',-1)">↑</button><button class="btn mini-btn" onclick="moveInjection('${seqId}','${x.id}',1)">↓</button></span></div>`).join('')||'<div class="empty">No injections.</div>'}</div>`,`<button class="btn" onclick="closeModal()">Done</button>`)}
function moveInjection(seqId,id,dir){const s=sequenceData().find(x=>x.id===seqId),a=s.injectionList,i=a.findIndex(x=>x.id===id),j=i+dir;if(i<0||j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];syncSequence(s);log('Reorder Injection',`${s.idn} / ${id}`);save();reorderInjections(seqId)}
function runSelectedSequence(){const s=selectedSequence();if(s)runSequence(s.id)}
function runSequence(id){if(!sequenceRoleCanRun()){alert('Only QC or Admin can run a sequence.');return}const s=sequenceData().find(x=>x.id===id);syncSequence(s);if(!s||!s.method||!s.instrument||!s.injectionList.length||s.status==='In Progress'){alert('Run requires a method, instrument, at least one injection, and a sequence that is not already In Progress.');return}const invalid=s.injectionList.filter(x=>x.includeInSequence!==false&&!x.sampleName&&!x.vialPosition);if(invalid.length){alert('One or more injections are invalid.');return}openModal('Run Sequence',`<div class="detail-grid"><div class="detail-item"><span>Sequence ID</span><b>${esc(s.idn)}</b></div><div class="detail-item"><span>Sequence Name</span><b>${esc(s.name)}</b></div><div class="detail-item"><span>Instrument</span><b>${esc(seqInstrumentLabel(s.instrument))}</b></div><div class="detail-item"><span>Analytical Method</span><b>${esc(seqMethodLabel(s.method))}</b></div></div><div class="field" style="margin-top:10px"><label>Injection Range</label><select id="run_range" class="select" onchange="document.getElementById('customRange').style.display=this.value==='Custom Range'?'grid':'none'"><option>All Injections</option><option>Custom Range</option></select></div><div id="customRange" class="formgrid" style="display:none"><div class="field"><label>From</label><input id="run_from" type="number" min="1" class="input" value="1"></div><div class="field"><label>To</label><input id="run_to" type="number" min="1" class="input" value="${s.injectionList.length}"></div></div><div class="run-options"><label><input id="run_equil" type="checkbox" checked> Equilibrate system before run</label><label><input id="run_process" type="checkbox" checked> Auto process after run</label><label><input id="run_order" type="checkbox" checked> Run in sequence order</label></div><div class="field" style="margin-top:10px"><label>Comments</label><textarea id="run_comments" class="textarea"></textarea></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn blue" onclick="startSequenceRun('${id}')">▶ Start Run</button>`)}
function startSequenceRun(id){const s=sequenceData().find(x=>x.id===id);let list=s.injectionList.filter(x=>x.includeInSequence!==false);if(document.getElementById('run_range').value==='Custom Range'){const a=Math.max(1,Number(document.getElementById('run_from').value)||1),b=Math.min(list.length,Number(document.getElementById('run_to').value)||list.length);list=list.slice(a-1,b)}if(!list.length){alert('No injections selected for run.');return}s.status='In Progress';s.run={startedAt:now(),current:0,total:list.length,paused:false,comments:document.getElementById('run_comments').value};list.forEach(x=>{x.status='Pending';x.acquisition=null});log('Start Run',`${s.idn} — ${list.length} injection(s)`);save();closeModal();showRunProgress(id,list.map(x=>x.id),0)}
const HPLC_SIM_DURATION_MS=20000;
function canonicalChromatogramPeaks(x){if(x.sampleType==='Blank')return [];const existing=Array.isArray(x.result?.peaks)&&x.result.peaks.length?x.result.peaks:null;if(existing)return existing.map(p=>({name:p.name,rt:Number(p.rt),area:Number(p.area)||0,height:Number(p.height)||0,areaPct:p.areaPct,heightPct:p.heightPct,resolution:p.resolution,tailing:p.tailing}));return [{name:'Peak 1',rt:2.35,area:142000,height:21000,areaPct:12.3,heightPct:13.0,resolution:'—',tailing:'1.12'},{name:x.sampleType==='Standard'?'Paracetamol':'Main Peak',rt:5.82,area:985214,height:125400,areaPct:85.4,heightPct:78.6,resolution:'3.42',tailing:'1.08'},{name:'Peak 3',rt:7.91,area:26500,height:18000,areaPct:2.3,heightPct:8.4,resolution:'2.76',tailing:'1.21'}]}
function chromatogramApexesMatch(data,peaks){if(!Array.isArray(data)||data.length<500||!peaks.length)return false;return peaks.every(pk=>{const rt=Number(pk.rt);const local=data.filter(d=>Math.abs(Number(d.t)-rt)<=0.35);if(local.length<3)return false;const apex=local.reduce((a,b)=>Number(b.y)>Number(a.y)?b:a,local[0]);return Math.abs(Number(apex.t)-rt)<=0.005&&Number(apex.y)>=250+Number(pk.height||0)*0.98})}
function deterministicChromatogramData(x){const peaks=canonicalChromatogramPeaks(x);const base=250,total=Math.max(10,Number(x.runTime)||10),step=0.005,out=[];for(let i=0;i<=Math.round(total/step);i++){const t=Number((i*step).toFixed(3));let y=base;for(const pk of peaks){const width=pk.rt<=3?0.16:pk.rt<7?0.18:0.16;y+=Number(pk.height||0)*Math.exp(-0.5*Math.pow((t-Number(pk.rt))/width,2))}out.push({t,y:Number(y.toFixed(2))})}
// Force each stored peak to have its discrete chromatogram apex exactly at the Peak Table RT.
peaks.forEach(pk=>{const idx=Math.max(0,Math.min(out.length-1,Math.round(Number(pk.rt)/step)));const t=Number(pk.rt);let y=base;for(const other of peaks){const width=other.rt<=3?0.16:other.rt<7?0.18:0.16;y+=Number(other.height||0)*Math.exp(-0.5*Math.pow((t-Number(other.rt))/width,2))}out[idx]={t:Number(t.toFixed(3)),y:Number(y.toFixed(2))};});return out}
function ensureAcquisitionData(x){const peaks=canonicalChromatogramPeaks(x);if(!chromatogramApexesMatch(x.acquisitionData,peaks)){x.acquisitionData=deterministicChromatogramData(x);if(x.result&&Array.isArray(x.result.peaks)){x.result.chromatogramData=x.acquisitionData}}return x.acquisitionData}
function resultFromChromatogram(x,data){const peaks=canonicalChromatogramPeaks(x);const main=peaks.find(p=>Math.abs(p.rt-5.82)<.01);return {rt:main?.rt??null,area:main?.area??0,height:main?.height??0,uvResponse:data.map(d=>d.y),chromatogramData:data,peaks,processingStatus:'Processed',resultStatus:'Pass',runAt:now()}}
function showRunProgress(seqId,ids,index){const s=sequenceData().find(x=>x.id===seqId);const list=ids.map(id=>s.injectionList.find(x=>x.id===id)).filter(Boolean);const x=list[index];if(!x)return;ensureAcquisitionData(x);x.status='Running';x.acquisition=x.acquisition||{status:'Running',currentTime:0,totalTime:Number(x.runTime)||10};x.acquisition.status='Running';x.acquisition.currentTime=Number(x.acquisition.currentTime)||0;save();const pct=Math.round((index/list.length)*100);openModal('Sequence Running',`<div class="run-progress"><div class="detail-grid"><div class="detail-item"><span>Current Injection</span><b>${esc(x.injectionId)}</b></div><div class="detail-item"><span>Total Injection</span><b>${index+1} of ${list.length}</b></div><div class="detail-item"><span>Progress</span><b id="seqRunPct">${pct}%</b></div><div class="detail-item"><span>Current Sample</span><b>${esc(x.sampleName||'—')}</b></div></div><div id="seqRunChart" class="chrom-live-chart" style="margin-top:12px"></div><div class="chrom-live-status running" id="seqRunStatus">● Acquisition Running</div><div class="detail-grid"><div class="detail-item"><span>Current Time</span><b id="seqRunTime">0.00 min</b></div><div class="detail-item"><span>Elapsed</span><b id="seqRunElapsed">0.00 / ${esc(x.acquisition.totalTime)} min</b></div></div></div>`,`<button class="btn" id="seqPauseBtn" onclick="pauseSequenceRun('${seqId}',${index},'${ids.join('|')}')">Ⅱ Pause</button><button class="btn danger" onclick="abortSequenceRun('${seqId}','${ids.join('|')}','')">■ Abort</button>`);runInjectionAcquisition(seqId,ids,index)}
function renderLiveChromSvg(data,currentTime,totalTime){const w=900,h=330,l=58,r=25,t=20,b=48,plotW=w-l-r,plotH=h-t-b;const dataMax=Math.max(1,...data.map(p=>Number(p.y)||0));const max=dataMax*1.08;const visible=data.filter(p=>p.t<=currentTime+0.0001);const pts=visible.map(p=>`${l+(p.t/totalTime)*plotW},${t+plotH-(p.y/max)*plotH}`).join(' ');const cx=l+Math.min(currentTime,totalTime)/totalTime*plotW;let grid='';for(let i=0;i<=5;i++){const yy=t+plotH-i*plotH/5;grid+=`<line class="gridline" x1="${l}" y1="${yy}" x2="${w-r}" y2="${yy}"/>`}for(let i=0;i<=5;i++){const xx=l+i*plotW/5;grid+=`<line class="gridline" x1="${xx}" y1="${t}" x2="${xx}" y2="${t+plotH}"/>`}return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Real-time HPLC-UV chromatogram"><g>${grid}</g><line class="axis" x1="${l}" y1="${t+plotH}" x2="${w-r}" y2="${t+plotH}"/><line class="axis" x1="${l}" y1="${t}" x2="${l}" y2="${t+plotH}"/><polyline class="trace" points="${pts}"/><line class="cursor" x1="${cx}" y1="${t}" x2="${cx}" y2="${t+plotH}"/><text x="${Math.min(cx+5,w-110)}" y="${t+14}">${currentTime.toFixed(2)} min</text><text x="${w/2-55}" y="${h-12}">Retention Time (min)</text><text x="16" y="${h/2+25}" transform="rotate(-90 16 ${h/2+25})">UV Response (mAU)</text><text x="${l-6}" y="${t+plotH+16}" text-anchor="end">0</text><text x="${w-r}" y="${t+plotH+16}">${totalTime.toFixed(2)}</text></svg>`}
function runInjectionAcquisition(seqId,ids,index){const s=sequenceData().find(x=>x.id===seqId),x=s?.injectionList.find(i=>i.id===ids[index]);if(!s||!x)return;const data=ensureAcquisitionData(x),total=Number(x.runTime)||10;let start=performance.now()-((Number(x.acquisition?.currentTime)||0)/total)*HPLC_SIM_DURATION_MS;window.__hplcRun={seqId,ids,index,raf:null,start,total,data};const tick=(ts)=>{const run=window.__hplcRun;if(!run||run.seqId!==seqId||run.index!==index)return;const cur=Math.min(total,Math.max(0,(ts-run.start)/HPLC_SIM_DURATION_MS*total));x.acquisition={status:x.acquisition?.status==='Paused'?'Paused':'Running',currentTime:Number(cur.toFixed(3)),totalTime:total};const chart=document.getElementById('seqRunChart');if(chart)chart.innerHTML=renderLiveChromSvg(data,cur,total);const time=document.getElementById('seqRunTime'),elapsed=document.getElementById('seqRunElapsed'),p=document.getElementById('seqRunPct');if(time)time.textContent=`${cur.toFixed(2)} min`;if(elapsed)elapsed.textContent=`${cur.toFixed(2)} / ${total.toFixed(2)} min`;if(p)p.textContent=`${Math.round((index+cur/total)/ids.length*100)}%`;if(ts%1000<20)save();if(cur>=total){completeInjectionStep(seqId,ids,index);return}if(x.acquisition.status==='Paused')return;run.raf=requestAnimationFrame(tick)};window.__hplcRun.raf=requestAnimationFrame(tick)}
function completeInjectionStep(seqId,ids,index){const s=sequenceData().find(x=>x.id===seqId);if(!s||s.status!=='In Progress')return;const x=s.injectionList.find(i=>i.id===ids[index]);if(!x)return;const data=ensureAcquisitionData(x);x.status='Completed';x.acquisition={status:'Completed',currentTime:Number(x.runTime)||10,totalTime:Number(x.runTime)||10};x.result=resultFromChromatogram(x,data);log('Complete Run',`${s.idn} / ${x.injectionId}`);s.run=s.run||{};s.run.current=index+1;save();if(index+1>=ids.length){s.status='Completed';s.run.completedAt=now();save();if(window.__hplcRun?.raf)cancelAnimationFrame(window.__hplcRun.raf);window.__hplcRun=null;closeModal();renderSequence(document.getElementById('content'));return}if(window.__hplcRun?.raf)cancelAnimationFrame(window.__hplcRun.raf);window.__hplcRun=null;showRunProgress(seqId,ids,index+1)}
function pauseSequenceRun(seqId,index,idstr){const ids=idstr.split('|').filter(Boolean),s=sequenceData().find(x=>x.id===seqId),x=s?.injectionList.find(i=>i.id===ids[index]);if(!s||!x)return;const run=window.__hplcRun;if(x.acquisition?.status==='Running'){x.acquisition.status='Paused';if(run?.raf)cancelAnimationFrame(run.raf);log('Pause Run',`${s.idn} — Paused`);save();const b=document.getElementById('seqPauseBtn');if(b)b.textContent='▶ Resume';const st=document.getElementById('seqRunStatus');if(st)st.textContent='Ⅱ Acquisition Paused';return}x.acquisition.status='Running';log('Resume Run',`${s.idn} — Resumed`);save();const b=document.getElementById('seqPauseBtn');if(b)b.textContent='Ⅱ Pause';const st=document.getElementById('seqRunStatus');if(st)st.textContent='● Acquisition Running';runInjectionAcquisition(seqId,ids,index)}
function abortSequenceRun(seqId,ids,reason){const s=sequenceData().find(x=>x.id===seqId);if(!s)return;openModal('Abort Run',`<div class="notice danger-note">Are you sure you want to abort this injection?</div><div class="field"><label>Abort Reason *</label><textarea id="abort_reason" class="textarea" placeholder="Enter reason for abort"></textarea></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn danger" onclick="confirmAbortSequence('${seqId}')">Abort Run</button>`)}
function confirmAbortSequence(seqId){const s=sequenceData().find(x=>x.id===seqId),r=document.getElementById('abort_reason')?.value.trim();if(!r){alert('Abort reason is required.');return}if(window.__hplcRun?.raf)cancelAnimationFrame(window.__hplcRun.raf);window.__hplcRun=null;s.status='Aborted';s.run=s.run||{};s.run.abortedAt=now();s.run.abortReason=r;s.injectionList.filter(x=>x.status==='Running').forEach(x=>{x.status='Failed';x.acquisition=x.acquisition||{};x.acquisition.status='Aborted';x.acquisition.abortedAt=now()});log('Abort Run',`${s.idn} — ${r}`);save();closeModal();renderSequence(document.getElementById('content'))}
function viewSequence(id){const s=sequenceData().find(x=>x.id===id);if(s)openModal(`${esc(s.idn)} — Sequence Details`,sequenceDetailsMarkup(s),`<button class="btn" onclick="closeModal()">Close</button>`)}
function viewInjection(seqId,id){const s=sequenceData().find(x=>x.id===seqId),x=s?.injectionList.find(i=>i.id===id);if(!x)return;openModal(`${esc(x.injectionId)} — Injection Details`,`<div class="detail-grid">${[['Injection ID',x.injectionId],['Sequence ID',s.idn],['Sample Name',x.sampleName],['Sample Type',x.sampleType],['Vial Position',x.vialPosition],['Method',seqMethodLabel(s.method)],['Instrument',seqInstrumentLabel(s.instrument)],['Injection Volume',x.injectionVolume],['Run Time',x.runTime||'—'],['Start Time',x.startTime||'—'],['Status',x.status||'Pending'],['RT',x.result?.rt??'No Data'],['Area',x.result?.area??'No Data'],['Height',x.result?.height??'No Data'],['Processing Status',x.result?.processingStatus||'No Data']].map(a=>`<div class="detail-item"><span>${a[0]}</span><b>${esc(a[1])}</b></div>`).join('')}</div>`,`<button class="btn" onclick="viewInjectionChromatogram('${seqId}','${id}')">View Chromatogram</button><button class="btn" onclick="viewInjectionResult('${seqId}','${id}')">View Result</button><button class="btn" onclick="closeModal()">Close</button>`)}
function viewInjectionResult(seqId,id){const s=sequenceData().find(x=>x.id===seqId),x=s?.injectionList.find(i=>i.id===id);if(!x)return;openModal(`${esc(x.injectionId)} — Result`,`<table class="info-table">${[['Retention Time',x.result?.rt??'No Data'],['Peak Area',x.result?.area??'No Data'],['Peak Height',x.result?.height??'No Data'],['UV Response',x.result?'Stored chromatogram points: '+(x.result.chromatogramData?.length||0):'No Data'],['Processing Status',x.result?.processingStatus||'No Data'],['Result Status',x.result?.resultStatus||'No Data'],['Run At',x.result?.runAt||'No Data']].map(a=>`<tr><td>${a[0]}</td><td><b>${esc(a[1])}</b></td></tr>`).join('')}</table>`,`<button class="btn" onclick="viewInjectionChromatogram('${seqId}','${id}')">View Chromatogram</button><button class="btn" onclick="closeModal()">Close</button>`)}
function chromatogramSvgForInjection(x){const d=x.result?.chromatogramData||[];if(!d.length)return '<div class="empty">No chromatogram data. Run the injection first.</div>';const max=Math.max(...d.map(p=>p.y),1),pts=d.map(p=>`${55+(p.t/12)*815},${240-(p.y/max)*205}`).join(' ');return `<div class="chartbox"><svg viewBox="0 0 900 280" width="100%" height="100%"><line x1="55" y1="240" x2="870" y2="240" stroke="#9aa8b8"/><line x1="55" y1="20" x2="55" y2="240" stroke="#9aa8b8"/><polyline fill="none" stroke="#2f70c9" stroke-width="2" points="${pts}"/><text x="440" y="272" font-size="11">Retention Time (min)</text><text x="13" y="140" font-size="11" transform="rotate(-90 13 140)">UV Response</text></svg></div>`}
function viewInjectionChromatogram(seqId,id){const s=sequenceData().find(x=>x.id===seqId),x=s?.injectionList.find(i=>i.id===id);if(!x)return;openModal(`${esc(x.injectionId)} — Chromatogram`,chromatogramSvgForInjection(x),`<button class="btn" onclick="window.print()">Print</button><button class="btn" onclick="closeModal()">Close</button>`)}
function sequenceReport(id){const s=sequenceData().find(x=>x.id===id);if(!s)return;syncSequence(s);openModal(`${esc(s.idn)} — Result / Report`,`<div class="detail-grid">${[['Sequence ID',s.idn],['Sequence Name',s.name],['Method',seqMethodLabel(s.method)],['Instrument',seqInstrumentLabel(s.instrument)],['Status',s.status],['Total Injections',s.injectionList.length]].map(a=>`<div class="detail-item"><span>${a[0]}</span><b>${esc(a[1])}</b></div>`).join('')}</div><div style="margin-top:12px">${injectionTableMarkup(s)}</div>`,`<button class="btn" onclick="exportOneSequenceCSV('${id}')">Export CSV</button><button class="btn" onclick="window.print()">Print / PDF</button><button class="btn" onclick="closeModal()">Close</button>`)}
function exportOneSequenceCSV(id){const s=sequenceData().find(x=>x.id===id);if(!s)return;downloadText(`${s.idn}.csv`,sequenceCsv(s))}
function sequenceCsv(s){return ['Sequence ID,Sequence Name,Method,Instrument,Created By,Date Created,Injection ID,Sample Name,Sample Type,Vial Position,RT,Area,Height,Status',...s.injectionList.map(x=>[s.idn,s.name,seqMethodLabel(s.method),seqInstrumentLabel(s.instrument),s.createdBy,s.date,x.injectionId,x.sampleName,x.sampleType,x.vialPosition,x.result?.rt??'',x.result?.area??'',x.result?.height??'',x.status||'Pending'].map(csvCell).join(','))].join('\n')}
function csvCell(v){return `"${String(v??'').replace(/"/g,'""')}"`}
function downloadText(name,text){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportSequenceData(){const arr=filteredSequences();if(!arr.length){alert('No sequence data to export.');return}downloadText('sequence-export.csv',['Sequence ID,Sequence Name,Method,Instrument,Created By,Date Created,Total Injections,Status',...arr.map(s=>[s.idn,s.name,seqMethodLabel(s.method),seqInstrumentLabel(s.instrument),s.createdBy,s.date,s.injectionList.length,s.status].map(csvCell).join(','))].join('\n'))}
function printSequence(){window.print()}
function importSequenceData(){if(!sequenceRoleCanEdit()){alert('Only QC or Admin can import sequence data.');return}const input=document.createElement('input');input.type='file';input.accept='.csv,.xlsx';input.onchange=()=>{const f=input.files[0];if(!f)return;if(!f.name.toLowerCase().endsWith('.csv')){alert('XLSX import requires an XLSX library. CSV import is available in this prototype.');return}const r=new FileReader();r.onload=()=>processSequenceCsv(r.result);r.readAsText(f)};input.click()}
function processSequenceCsv(txt){const lines=txt.split(/\r?\n/).filter(Boolean);if(lines.length<2){alert('No records found.');return}const rows=lines.slice(1).map(parseCsvLine);let ok=0,fail=[];rows.forEach((r,idx)=>{const [idn,name,method,instrument,createdBy,date]=r;if(!idn||!name||!date||!seqMethod(method)&&!seqMethod((state.methods.find(m=>m.methodId===method)||{}).id)||!seqInstrument(instrument)&&!seqInstrument((state.instruments.find(i=>i.idn===instrument)||{}).id)){fail.push(`Row ${idx+2}: required/invalid method or instrument`);return}if(state.sequences.some(s=>s.idn===idn)){fail.push(`Row ${idx+2}: duplicate Sequence ID ${idn}`);return}state.sequences.push({id:uid('SEQ'),idn,name,date,startTime:'',endTime:'',method:seqMethod(method)?.id||(state.methods.find(m=>m.methodId===method)||{}).id,instrument:seqInstrument(instrument)?.id||(state.instruments.find(i=>i.idn===instrument)||{}).id,createdBy:createdBy||state.session.username,plannedInjections:1,purpose:'Other',comments:'Imported',status:'Draft',injectionList:[]});ok++});log('Import',`Sequence import: ${ok} successful, ${fail.length} failed`);save();alert(`Import complete. Successful: ${ok}. Failed: ${fail.length}.${fail.length?'\n'+fail.join('\n'):''}`);renderSequence(document.getElementById('content'))}
function parseCsvLine(line){const out=[];let cur='',q=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'&&line[i+1]==='"'){cur+='"';i++;continue}if(ch==='"'){q=!q;continue}if(ch===','&&!q){out.push(cur);cur='';continue}cur+=ch}out.push(cur);return out}
function importInjectionData(seqId){if(!sequenceRoleCanEdit()){alert('Only QC or Admin can import injections.');return}const input=document.createElement('input');input.type='file';input.accept='.csv';input.onchange=()=>{const f=input.files[0];if(!f)return;const r=new FileReader();r.onload=()=>processInjectionCsv(seqId,r.result);r.readAsText(f)};input.click()}
function processInjectionCsv(seqId,txt){const s=sequenceData().find(x=>x.id===seqId),lines=txt.split(/\r?\n/).filter(Boolean),rows=lines.slice(1).map(parseCsvLine);let ok=0,fail=[];rows.forEach((r,idx)=>{const [injId,sampleName,sampleType,vial,vol]=r;if(!sampleName||!['Blank','Standard','Sample','QC'].includes(sampleType)||!vial||!vol||Number(vol)<=0||s.injectionList.some(x=>x.injectionId===injId)){fail.push(`Row ${idx+2}: invalid required field, sample type, vial, volume, or duplicate ID`);return}s.injectionList.push({id:uid('INJ'),injectionId:injId||injNextId(s),sampleName,sampleType,vialPosition:vial,injectionVolume:vol,runTime:'',status:'Pending',result:null,includeInSequence:true});ok++});syncSequence(s);log('Import',`${s.idn} injection import: ${ok} successful, ${fail.length} failed`);save();alert(`Import complete. Successful: ${ok}. Failed: ${fail.length}.${fail.length?'\n'+fail.join('\n'):''}`);refreshSequenceDetails()}

function instrumentCanEdit(){return role()==='QC'||role()==='ADMIN'}
function instrumentCanView(){return !!state.session}
function instrumentStatusClass(s){return s==='Ready'?'approved':(s==='In Use'?'pending':(s==='Maintenance'?'draft':'rejected'))}
function instrumentBadge(s){return `<span class="badge ${instrumentStatusClass(s)}">${esc(s||'No Data')}</span>`}
function instrumentRecords(){return state.instruments.map(i=>{i.modules=i.modules||[];i.configuration=i.configuration||{};i.calibrations=i.calibrations||[];i.attachments=i.attachments||[];return i})}
function instrumentRecordForEdit(iid){return state.instruments.find(i=>i.id===iid)||null}
function cancelInstrumentEdit(iid){const idx=state.instruments.findIndex(i=>i.id===iid&&i.__draft);if(idx>=0){state.instruments.splice(idx,1);save()}closeModal()}
function returnInstrumentEditor(iid,tab){closeModal();addInstrument(iid);instrumentEditTabs(iid,tab)}
function instrumentFiltered(){const q=(document.getElementById('insSearch')?.value||'').trim().toLowerCase();const st=document.getElementById('insStatus')?.value||'';const loc=(document.getElementById('insLocation')?.value||'').trim().toLowerCase();const from=document.getElementById('insFrom')?.value||'';const to=document.getElementById('insTo')?.value||'';return instrumentRecords().filter(i=>(!q||`${i.idn||''} ${i.name||''}`.toLowerCase().includes(q))&&(!st||i.status===st)&&(!loc||String(i.location||'').toLowerCase().includes(loc))&&(!from||String(i.installationDate||'')>=from)&&(!to||String(i.installationDate||'')<=to))}
function renderInstrument(c){const arr=instrumentFiltered();const locs=[...new Set(instrumentRecords().map(i=>i.location).filter(Boolean))];c.innerHTML=header('Instrument','Manage HPLC-UV instruments and configuration.',`<div class="title-actions instrument-actions"><button class="btn primary" ${instrumentCanEdit()?'':'disabled'} onclick="addInstrument()">＋ Add Instrument</button><button class="btn" onclick="exportInstrumentPDF()">Export PDF</button><button class="btn" onclick="printInstrument()">Print</button></div>`)+`<div class="panel no-print instrument-filter"><div class="formgrid"><div class="field"><label>Search Instrument ID or Name</label><input id="insSearch" class="input" placeholder="Search Instrument ID or Name" value="${esc(document.getElementById('insSearch')?.value||'')}"></div><div class="field"><label>Status</label><select id="insStatus" class="select" onchange="filterInstrument()"><option value="">All Status</option>${['Ready','In Use','Maintenance','Out of Service'].map(x=>`<option ${document.getElementById('insStatus')?.value===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Location</label><input id="insLocation" class="input" list="instrumentLocations" placeholder="Location" value="${esc(document.getElementById('insLocation')?.value||'')}" oninput="filterInstrument()"><datalist id="instrumentLocations">${locs.map(x=>`<option value="${esc(x)}">`).join('')}</datalist></div><div class="field"><label>Date From</label><input id="insFrom" type="date" class="input" value="${esc(document.getElementById('insFrom')?.value||'')}" onchange="filterInstrument()"></div><div class="field"><label>Date To</label><input id="insTo" type="date" class="input" value="${esc(document.getElementById('insTo')?.value||'')}" onchange="filterInstrument()"></div><div class="field filter-buttons"><label>&nbsp;</label><div><button class="btn" onclick="resetInstrumentFilters()">Reset</button><button class="btn primary" onclick="filterInstrument()">Search</button></div></div></div></div><div class="panel instrument-list-panel"><div class="panel-head"><h3>Instrument List</h3><span class="muted">${arr.length} instrument${arr.length===1?'':'s'}</span></div><div class="table-wrap">${arr.length?`<table class="table instrument-table" class="instrument-list-table"><thead><tr><th class="instrument-select-col"><input type="checkbox" aria-label="Select all instruments" onchange="toggleAllInstruments(this.checked)"></th><th>No.</th><th>Instrument ID</th><th>Instrument Name</th><th>Model</th><th>Location</th><th>Status</th><th>Last Calibration</th><th>Next Calibration</th><th>Actions</th></tr></thead><tbody>${arr.map((i,n)=>`<tr><td class="instrument-select-col" onclick="event.stopPropagation()"><input type="checkbox" class="instrument-row-check" aria-label="Select instrument" value="${esc(i.id)}"></td><td>${n+1}</td><td><b>${esc(i.idn)}</b></td><td>${esc(i.name)}</td><td>${esc(i.model)}</td><td>${esc(i.location||'—')}</td><td>${instrumentBadge(i.status)}</td><td>${esc(i.lastCalibration||'—')}</td><td>${esc(i.nextCalibration||'—')}</td><td class="actions"><button class="btn mini-btn" onclick="viewInstrument('${i.id}')">View</button><button class="btn mini-btn" ${instrumentCanEdit()?'':'disabled'} onclick="editInstrument('${i.id}')">Edit</button><button class="btn danger mini-btn" ${instrumentCanEdit()?'':'disabled'} onclick="removeInstrument('${i.id}')">Delete</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No instrument matches the current filter.</div>'}</div></div></div>`}
function filterInstrument(){renderInstrument(document.getElementById('content'))}
function resetInstrumentFilters(){['insSearch','insStatus','insLocation','insFrom','insTo'].forEach(id=>{const e=document.getElementById(id);if(e)e.value=''});renderInstrument(document.getElementById('content'))}
function nextInstrumentId(){let n=instrumentRecords().length+1;while(instrumentRecords().some(i=>i.idn===`HPLC-UV-${String(n).padStart(3,'0')}`))n++;return `HPLC-UV-${String(n).padStart(3,'0')}`}
function captureInstrumentEditTab(iid){
 const x=instrumentRecords().find(i=>i.id===iid); if(!x)return;
 const name=document.getElementById('i_name');
 if(name){
  x.name=name.value.trim();
  x.manufacturer=document.getElementById('i_manufacturer')?.value.trim()||'';
  x.model=document.getElementById('i_model')?.value.trim()||'';
  x.serialNumber=document.getElementById('i_serial')?.value.trim()||'';
  x.firmwareVersion=document.getElementById('i_firmware')?.value.trim()||'';
  x.softwareVersion=document.getElementById('i_software')?.value.trim()||'';
  x.location=document.getElementById('i_location')?.value.trim()||'';
  x.department=document.getElementById('i_department')?.value.trim()||'';
  x.installationDate=document.getElementById('i_install')?.value||'';
  x.powerSupply=document.getElementById('i_power')?.value.trim()||'';
  x.status=document.getElementById('i_status')?.value||'';
  x.description=document.getElementById('i_description')?.value.trim()||'';
 }
 const cfg=document.getElementById('cfg_pumpModel');
 if(cfg){
  x.configuration=x.configuration||{};
  const keys=['pumpModel','pumpSerial','defaultFlowRate','pressureLimit','numberOfPumpChannels','gradientCapability','autosamplerModel','autosamplerSerial','injectionVolumeRange','defaultInjectionVolume','trayCapacity','cooling','autosamplerTemperatureRange','columnOvenModel','columnOvenSerial','columnOvenTemperatureRange','defaultColumnTemperature','heatingCooling','temperatureAccuracy','detectorModel','detectorSerial','defaultWavelength','wavelengthRange','lampType','detectorChannels','dataSystem','computerName','dataStoragePath'];
  keys.forEach(k=>{const el=document.getElementById('cfg_'+k);if(el)x.configuration[k]=el.value.trim()});
 }
}
document.addEventListener('click',function(e){
 const editTab=e.target.closest('[data-instrument-edit-tab]');
 if(editTab){const wrap=document.getElementById('instrumentEditModalTabs');if(!wrap)return;e.preventDefault();captureInstrumentEditTab(wrap.dataset.instrumentId);instrumentEditTabs(wrap.dataset.instrumentId,editTab.dataset.instrumentEditTab);return}
 const viewTab=e.target.closest('[data-instrument-view-tab]');
 if(viewTab){const wrap=document.getElementById('instrumentViewModalTabs');if(!wrap)return;e.preventDefault();instrumentViewTabs(wrap.dataset.instrumentId,viewTab.dataset.instrumentViewTab);return}
});
function instrumentEditTabs(iid,tab){
 const x=instrumentRecords().find(i=>i.id===iid); if(!x)return;
 const tabs=['general','configuration','modules','calibration','attachments'];
 const labels={general:'General Information',configuration:'Configuration',modules:'Modules',calibration:'Calibration',attachments:'Attachments'};
 const body=document.getElementById('instrumentEditBody'); if(!body)return;
 document.querySelectorAll('#instrumentEditModalTabs .instrument-tab').forEach((el,idx)=>el.classList.toggle('active',tabs[idx]===tab));
 body.innerHTML=instrumentEditTabBody(x,tab);
}
function instrumentEditTabBody(x,tab){
 const c=x.configuration||{};
 if(tab==='general') return `<div class="formgrid"><div class="field"><label>Instrument ID *</label><input id="i_id" class="input" value="${esc(x.idn)}" disabled></div><div class="field"><label>Instrument Name *</label><input id="i_name" class="input" value="${esc(x.name||'')}"></div><div class="field"><label>Manufacturer</label><input id="i_manufacturer" class="input" value="${esc(x.manufacturer||'')}"></div><div class="field"><label>Model *</label><input id="i_model" class="input" value="${esc(x.model||'')}"></div><div class="field"><label>Serial Number *</label><input id="i_serial" class="input" value="${esc(x.serialNumber||'')}"></div><div class="field"><label>Firmware Version</label><input id="i_firmware" class="input" value="${esc(x.firmwareVersion||'')}"></div><div class="field"><label>Software Version</label><input id="i_software" class="input" value="${esc(x.softwareVersion||'')}"></div><div class="field"><label>Location *</label><input id="i_location" class="input" value="${esc(x.location||'')}"></div><div class="field"><label>Department</label><input id="i_department" class="input" value="${esc(x.department||'')}"></div><div class="field"><label>Installation Date *</label><input id="i_install" type="date" class="input" value="${esc(x.installationDate||'')}"></div><div class="field"><label>Power Supply</label><input id="i_power" class="input" value="${esc(x.powerSupply||'')}"></div><div class="field"><label>Status *</label><select id="i_status" class="select">${['Ready','In Use','Maintenance','Out of Service'].map(v=>`<option ${x.status===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="field" style="margin-top:10px"><label>Description</label><textarea id="i_description" class="textarea">${esc(x.description||'')}</textarea></div>`;
 if(tab==='configuration') return `<div class="formgrid">${[['pumpModel','Pump Model'],['pumpSerial','Pump Serial Number'],['defaultFlowRate','Default Flow Rate'],['pressureLimit','Pressure Limit'],['numberOfPumpChannels','Number of Channels'],['gradientCapability','Gradient Capability'],['autosamplerModel','Autosampler Model'],['autosamplerSerial','Autosampler Serial Number'],['injectionVolumeRange','Injection Volume Range'],['defaultInjectionVolume','Default Injection Volume'],['trayCapacity','Tray Capacity'],['cooling','Cooling'],['autosamplerTemperatureRange','Temperature Range'],['columnOvenModel','Column Oven Model'],['columnOvenSerial','Serial Number'],['columnOvenTemperatureRange','Temperature Range'],['defaultColumnTemperature','Default Column Temperature'],['heatingCooling','Heating/Cooling'],['temperatureAccuracy','Temperature Accuracy'],['detectorModel','Detector Model'],['detectorSerial','Serial Number'],['defaultWavelength','Default Wavelength'],['wavelengthRange','Wavelength Range'],['lampType','Lamp Type'],['detectorChannels','Number of Channels'],['dataSystem','Data System'],['computerName','Computer Name'],['dataStoragePath','Data Storage Path']].map(([k,l])=>`<div class="field"><label>${l}</label><input id="cfg_${k}" class="input" value="${esc(c[k]||'')}"></div>`).join('')}</div>`;
 if(tab==='modules') return `<div class="panel-head"><h4>Modules</h4><button class="btn primary" onclick="addInstrumentModule('${x.id}')">＋ Add Module</button></div>${instrumentModulesTable(x)}`;
 if(tab==='calibration') return `<div class="panel-head"><h4>Calibration Schedule & History</h4><button class="btn primary" onclick="addInstrumentCalibration('${x.id}')">＋ Add Calibration</button></div><div class="table-wrap">${instrumentCalibrationTable(x)}</div>`;
 return `<div class="panel-head"><h4>Attachments</h4><button class="btn primary" onclick="addInstrumentAttachment('${x.id}')">＋ Upload Attachment</button></div>${instrumentAttachmentsTable(x)}`;
}
function saveInstrumentEdit(iid){
 if(!instrumentCanEdit())return;
 const x=instrumentRecords().find(i=>i.id===iid); if(!x)return;
 captureInstrumentEditTab(iid);
 const ids=['i_name','i_manufacturer','i_model','i_serial','i_firmware','i_software','i_location','i_department','i_install','i_power','i_status','i_description'];
 if(document.getElementById('i_name')){x.name=document.getElementById('i_name').value.trim();x.manufacturer=document.getElementById('i_manufacturer').value.trim();x.model=document.getElementById('i_model').value.trim();x.serialNumber=document.getElementById('i_serial').value.trim();x.firmwareVersion=document.getElementById('i_firmware').value.trim();x.softwareVersion=document.getElementById('i_software').value.trim();x.location=document.getElementById('i_location').value.trim();x.department=document.getElementById('i_department').value.trim();x.installationDate=document.getElementById('i_install').value;x.powerSupply=document.getElementById('i_power').value.trim();x.status=document.getElementById('i_status').value;x.description=document.getElementById('i_description').value.trim();if(!x.name||!x.model||!x.serialNumber||!x.location||!x.installationDate||!x.status){alert('Please complete all required fields marked *.');return}}
 x.configuration=x.configuration||{};
 const cfgKeys=['pumpModel','pumpSerial','defaultFlowRate','pressureLimit','numberOfPumpChannels','gradientCapability','autosamplerModel','autosamplerSerial','injectionVolumeRange','defaultInjectionVolume','trayCapacity','cooling','autosamplerTemperatureRange','columnOvenModel','columnOvenSerial','columnOvenTemperatureRange','defaultColumnTemperature','heatingCooling','temperatureAccuracy','detectorModel','detectorSerial','defaultWavelength','wavelengthRange','lampType','detectorChannels','dataSystem','computerName','dataStoragePath'];
 cfgKeys.forEach(k=>{const el=document.getElementById('cfg_'+k);if(el)x.configuration[k]=el.value.trim()});
 x.__draft=false;save();log('Edit Instrument',x.idn);closeModal();viewInstrument(x.id);
}
function addInstrument(id){
 if(id&&!instrumentCanEdit())return;if(!id&&!instrumentCanEdit()){alert('Only QC or Admin can add instruments.');return}
 let x=id?instrumentRecords().find(i=>i.id===id):null;
 if(!x){x={id:uid('INS'),idn:nextInstrumentId(),name:'',manufacturer:'',model:'',serialNumber:'',firmwareVersion:'',softwareVersion:'',location:'',department:'',installationDate:'',powerSupply:'',status:'Ready',description:'',configuration:{},modules:[],calibrations:[],attachments:[],__draft:true};state.instruments.push(x)}
 if(!x)return;
 const tabs=['General Information','Configuration','Modules','Calibration','Attachments'];
 openModal(id?'Edit Instrument':'Add Instrument',`<div id="instrumentEditModalTabs" class="instrument-tabs" data-instrument-id="${esc(x.id)}">${tabs.map((t,i)=>`<button type="button" class="instrument-tab ${i===0?'active':''}" data-instrument-edit-tab="${['general','configuration','modules','calibration','attachments'][i]}">${t}</button>`).join('')}</div><div id="instrumentEditBody">${instrumentEditTabBody(x,'general')}</div>`,`<button class="btn" onclick="cancelInstrumentEdit('${x.id}')">Cancel</button><button class="btn primary" onclick="saveInstrumentEdit('${x.id}')">${id?'Save Changes':'Save Instrument'}</button>`,'instrumentEditModal');
}
function saveInstrument(id){if(!instrumentCanEdit()){alert('Only QC or Admin can edit instruments.');return}const x=id?instrumentRecords().find(i=>i.id===id):{id:uid('INS'),modules:[],calibrations:[],attachments:[]};x.idn=document.getElementById('i_id').value.trim();x.name=document.getElementById('i_name').value.trim();x.manufacturer=document.getElementById('i_manufacturer').value.trim();x.model=document.getElementById('i_model').value.trim();x.serialNumber=document.getElementById('i_serial').value.trim();x.firmwareVersion=document.getElementById('i_firmware').value.trim();x.softwareVersion=document.getElementById('i_software').value.trim();x.location=document.getElementById('i_location').value.trim();x.department=document.getElementById('i_department').value.trim();x.installationDate=document.getElementById('i_install').value;x.powerSupply=document.getElementById('i_power').value.trim();x.status=document.getElementById('i_status').value;x.description=document.getElementById('i_description').value.trim();if(!x.idn||!x.name||!x.model||!x.serialNumber||!x.location||!x.installationDate||!x.status){alert('Please complete all required fields marked *.');return}if(instrumentRecords().some(i=>i.idn===x.idn&&i.id!==x.id)){alert('Instrument ID must be unique.');return}x.configuration=x.configuration||{};x.modules=x.modules||[];x.calibrations=x.calibrations||[];x.attachments=x.attachments||[];if(!id)state.instruments.push(x);log(id?'Edit Instrument':'Create Instrument',x.idn);save();closeModal();renderInstrument(document.getElementById('content'))}
function editInstrument(id){addInstrument(id)}
function removeInstrument(id){if(!instrumentCanEdit()){alert('Only QC or Admin can delete instruments.');return}const x=instrumentRecords().find(i=>i.id===id);if(!x)return;if(!confirm(`Delete ${x.idn}? This instrument may be referenced by Sequence records.`))return;state.instruments=state.instruments.filter(i=>i.id!==id);log('Delete Instrument',x.idn);save();renderInstrument(document.getElementById('content'))}
function instrumentViewTabs(iid,tab){
 const x=instrumentRecords().find(i=>i.id===iid); if(!x)return;
 const tabs=['general','configuration','modules','calibration','attachments'];
 document.querySelectorAll('#instrumentViewModalTabs .instrument-tab').forEach((el,idx)=>el.classList.toggle('active',tabs[idx]===tab));
 const body=document.getElementById('instrumentViewBody'); if(body) body.innerHTML=instrumentViewTabBody(x,tab);
}
function instrumentViewTabBody(x,tab){
 const c=x.configuration||{};
 if(tab==='general') return `<div class="detail-grid">${[['Instrument ID',x.idn],['Instrument Name',x.name],['Manufacturer',x.manufacturer||'—'],['Model',x.model||'—'],['Serial Number',x.serialNumber||'—'],['Location',x.location||'—'],['Department',x.department||'—'],['Status',x.status||'—'],['Installation Date',x.installationDate||'—'],['Last Calibration',x.lastCalibration||'—'],['Next Calibration',x.nextCalibration||'—'],['Firmware Version',x.firmwareVersion||'—'],['Software Version',x.softwareVersion||'—'],['Description',x.description||'—']].map(a=>`<div class="detail-item"><span>${a[0]}</span><b>${esc(a[1])}</b></div>`).join('')}</div>`;
 if(tab==='configuration') return `<div class="detail-grid">${[['Pump Model',c.pumpModel],['Pump Serial Number',c.pumpSerial],['Default Flow Rate',c.defaultFlowRate],['Pressure Limit',c.pressureLimit],['Number of Channels',c.numberOfPumpChannels],['Gradient Capability',c.gradientCapability],['Autosampler Model',c.autosamplerModel],['Autosampler Serial Number',c.autosamplerSerial],['Injection Volume Range',c.injectionVolumeRange],['Default Injection Volume',c.defaultInjectionVolume],['Tray Capacity',c.trayCapacity],['Cooling',c.cooling],['Autosampler Temperature Range',c.autosamplerTemperatureRange],['Column Oven Model',c.columnOvenModel],['Column Oven Serial Number',c.columnOvenSerial],['Column Oven Temperature Range',c.columnOvenTemperatureRange],['Default Column Temperature',c.defaultColumnTemperature],['Heating/Cooling',c.heatingCooling],['Temperature Accuracy',c.temperatureAccuracy],['Detector Model',c.detectorModel],['Detector Serial Number',c.detectorSerial],['Default Wavelength',c.defaultWavelength],['Wavelength Range',c.wavelengthRange],['Lamp Type',c.lampType],['Detector Channels',c.detectorChannels],['Data System',c.dataSystem],['Computer Name',c.computerName],['Data Storage Path',c.dataStoragePath]].map(a=>`<div class="detail-item"><span>${a[0]}</span><b>${esc(a[1]||'—')}</b></div>`).join('')}</div>`;
 if(tab==='modules') return `<div class="panel-head"><h4>Modules</h4></div>${instrumentModulesViewTable(x)}`;
 if(tab==='calibration') return `<div class="panel-head"><h4>Calibration Schedule & History</h4></div><div class="table-wrap">${instrumentCalibrationViewTable(x)}</div>`;
 return `<div class="panel-head"><h4>Attachments</h4></div>${instrumentAttachmentsViewTable(x)}`;
}
function instrumentModulesViewTable(x){return x.modules?.length?`<div class="table-wrap"><table class="table"><thead><tr><th>No.</th><th>Module Type</th><th>Module Name / Model</th><th>Serial Number</th><th>Location</th><th>Status</th><th>Actions</th></tr></thead><tbody>${x.modules.map((m,n)=>`<tr><td class="instrument-select-col"><input type="checkbox" class="instrument-row-check" aria-label="Select instrument"></td>
<td>${n+1}</td><td>${esc(m.type)}</td><td>${esc(m.name)}</td><td>${esc(m.serial||'—')}</td><td>${esc(m.location||'—')}</td><td>${instrumentBadge(m.status)}</td><td><button class="btn mini-btn" onclick="viewInstrumentModule('${x.id}','${m.id}')">View</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No modules recorded.</div>'}
function instrumentCalibrationViewTable(x){return x.calibrations?.length?`<table class="table"><thead><tr><th>No.</th><th>Calibration Type</th><th>Date Performed</th><th>Next Due Date</th><th>Result</th><th>Performed By</th><th>Certificate</th></tr></thead><tbody>${x.calibrations.map((c,n)=>`<tr><td>${n+1}</td><td>${esc(c.type)}</td><td>${esc(c.date||'—')}</td><td>${esc(c.nextDue||'—')}</td><td>${instrumentBadge(c.result)}</td><td>${esc(c.performedBy||'—')}</td><td>${esc(c.certificateNumber||'—')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No calibration history recorded.</div>'}
function instrumentAttachmentsViewTable(x){return x.attachments?.length?`<div class="table-wrap"><table class="table"><thead><tr><th>No.</th><th>Type</th><th>File</th><th>Size</th><th>Actions</th></tr></thead><tbody>${x.attachments.map((a,n)=>`<tr><td>${n+1}</td><td>${esc(a.type)}</td><td>${esc(a.name)}</td><td>${Math.round((a.size||0)/1024)} KB</td><td><button class="btn mini-btn" onclick="previewInstrumentAttachment('${x.id}','${a.id}')">View</button><button class="btn mini-btn" onclick="downloadInstrumentAttachment('${x.id}','${a.id}')">Download</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No attachments recorded.</div>'}
function viewInstrument(id){const x=instrumentRecords().find(i=>i.id===id);if(!x)return;const tabKeys=['general','configuration','modules','calibration','attachments'];openModal(`${esc(x.idn)} — Instrument Details`,`<div id="instrumentViewModalTabs" class="instrument-tabs" data-instrument-id="${esc(x.id)}">${['General Information','Configuration','Modules','Calibration','Attachments'].map((t,i)=>`<button type="button" class="instrument-tab ${i===0?'active':''}" data-instrument-view-tab="${tabKeys[i]}">${t}</button>`).join('')}</div><div id="instrumentViewBody">${instrumentViewTabBody(x,'general')}</div>`,`<button class="btn" onclick="closeModal()">Close</button>`,'instrumentViewModal')}

function instrumentModulesTable(x){return x.modules?.length?`<div class="table-wrap"><table class="table"><thead><tr><th>No.</th><th>Module Type</th><th>Module Name / Model</th><th>Serial Number</th><th>Location</th><th>Status</th><th>Actions</th></tr></thead><tbody>${x.modules.map((m,n)=>`<tr><td>${n+1}</td><td>${esc(m.type)}</td><td>${esc(m.name)}</td><td>${esc(m.serial||'—')}</td><td>${esc(m.location||'—')}</td><td>${instrumentBadge(m.status)}</td><td class="actions"><button class="btn mini-btn" onclick="viewInstrumentModule('${x.id}','${m.id}')">View</button><button class="btn mini-btn" ${instrumentCanEdit()?'':'disabled'} onclick="editInstrumentModule('${x.id}','${m.id}')">Edit</button><button class="btn danger mini-btn" ${instrumentCanEdit()?'':'disabled'} onclick="deleteInstrumentModule('${x.id}','${m.id}')">Delete</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No modules recorded.</div>'}
function addInstrumentModule(iid,mid){if(!instrumentCanEdit()){alert('Only QC or Admin can manage modules.');return}const x=instrumentRecordForEdit(iid);if(!x)return;const old=mid?x.modules.find(m=>m.id===mid):null;const m=old||{id:uid('MOD'),type:'Pump',name:'',manufacturer:'',serial:'',partNumber:'',firmware:'',location:'',status:'Ready',description:''};openModal(mid?'Edit Module':'Add Module',`<div class="formgrid"><div class="field"><label>Module Type *</label><select id="mod_type" class="select">${['Pump','Autosampler','Column Oven','Detector (UV)','Data System','Other'].map(v=>`<option ${m.type===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Module Name / Model *</label><input id="mod_name" class="input" value="${esc(m.name)}"></div><div class="field"><label>Manufacturer</label><input id="mod_manufacturer" class="input" value="${esc(m.manufacturer||'')}"></div><div class="field"><label>Serial Number</label><input id="mod_serial" class="input" value="${esc(m.serial||'')}"></div><div class="field"><label>Part Number</label><input id="mod_part" class="input" value="${esc(m.partNumber||'')}"></div><div class="field"><label>Firmware Version</label><input id="mod_firmware" class="input" value="${esc(m.firmware||'')}"></div><div class="field"><label>Location</label><input id="mod_location" class="input" value="${esc(m.location||'')}"></div><div class="field"><label>Status *</label><select id="mod_status" class="select">${['Ready','In Use','Maintenance','Out of Service'].map(v=>`<option ${m.status===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="field"><label>Description</label><textarea id="mod_description" class="textarea">${esc(m.description||'')}</textarea></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveInstrumentModule('${iid}','${mid||''}')">Save Module</button>`)}
function saveInstrumentModule(iid,mid){const x=instrumentRecordForEdit(iid);if(!x)return;const m=mid?x.modules.find(v=>v.id===mid):{id:uid('MOD')};m.type=document.getElementById('mod_type').value;m.name=document.getElementById('mod_name').value.trim();m.manufacturer=document.getElementById('mod_manufacturer').value.trim();m.serial=document.getElementById('mod_serial').value.trim();m.partNumber=document.getElementById('mod_part').value.trim();m.firmware=document.getElementById('mod_firmware').value.trim();m.location=document.getElementById('mod_location').value.trim();m.status=document.getElementById('mod_status').value;m.description=document.getElementById('mod_description').value.trim();if(!m.type||!m.name||!m.status){alert('Please complete all required module fields marked *.');return}if(!mid)x.modules.push(m);log(mid?'Edit Module':'Add Module',`${x.idn} / ${m.name}`);save();closeModal();viewInstrument(iid)}
function viewInstrumentModule(iid,mid){const x=instrumentRecords().find(i=>i.id===iid),m=x?.modules.find(v=>v.id===mid);if(!m)return;openModal(`${esc(m.name)} — Module Details`,`<div class="detail-grid">${[['Module Type',m.type],['Module Name / Model',m.name],['Manufacturer',m.manufacturer||'—'],['Serial Number',m.serial||'—'],['Part Number',m.partNumber||'—'],['Firmware Version',m.firmware||'—'],['Location',m.location||'—'],['Status',m.status||'—'],['Description',m.description||'—']].map(a=>`<div class="detail-item"><span>${a[0]}</span><b>${esc(a[1])}</b></div>`).join('')}</div>`,`<button class="btn" onclick="closeModal();viewInstrument('${iid}')">Back</button>`)}
function editInstrumentModule(iid,mid){addInstrumentModule(iid,mid)}
function deleteInstrumentModule(iid,mid){if(!instrumentCanEdit())return;const x=instrumentRecords().find(i=>i.id===iid);if(!x)return;if(!confirm('Delete this module?'))return;x.modules=x.modules.filter(m=>m.id!==mid);log('Delete Module',`${x.idn} / ${mid}`);save();viewInstrument(iid)}
function instrumentCalibrationTable(x){return x.calibrations?.length?`<table class="table"><thead><tr><th>No.</th><th>Calibration Type</th><th>Date Performed</th><th>Next Due Date</th><th>Result</th><th>Performed By</th><th>Certificate</th><th>Actions</th></tr></thead><tbody>${x.calibrations.map((c,n)=>`<tr><td>${n+1}</td><td>${esc(c.type)}</td><td>${esc(c.date||'—')}</td><td>${esc(c.nextDue||'—')}</td><td>${instrumentBadge(c.result)}</td><td>${esc(c.performedBy||'—')}</td><td>${esc(c.certificateNumber||'—')}</td><td class="actions"><button class="btn mini-btn" ${instrumentCanEdit()?'':'disabled'} onclick="editInstrumentCalibration('${x.id}','${c.id}')">Edit</button><button class="btn danger mini-btn" ${instrumentCanEdit()?'':'disabled'} onclick="deleteInstrumentCalibration('${x.id}','${c.id}')">Delete</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No calibration history recorded.</div>'}
function addInstrumentCalibration(iid,cid){if(!instrumentCanEdit()){alert('Only QC or Admin can manage calibration.');return}const x=instrumentRecordForEdit(iid);if(!x)return;const old=cid?x.calibrations.find(c=>c.id===cid):null;const c=old||{id:uid('CAL'),type:'',date:'',nextDue:'',result:'Pending',performedBy:'',certificateNumber:'',certificateFile:'',remarks:''};openModal(cid?'Edit Calibration':'Add Calibration',`<div class="formgrid"><div class="field"><label>Calibration Type *</label><input id="cal_type" class="input" value="${esc(c.type)}"></div><div class="field"><label>Frequency *</label><input id="cal_frequency" class="input" value="${esc(c.frequency||'')}"></div><div class="field"><label>Calibration Date *</label><input id="cal_date" type="date" class="input" value="${esc(c.date)}"></div><div class="field"><label>Next Due Date *</label><input id="cal_next" type="date" class="input" value="${esc(c.nextDue)}"></div><div class="field"><label>Responsible Department</label><input id="cal_dept" class="input" value="${esc(c.department||'')}"></div><div class="field"><label>Responsible Person</label><input id="cal_person" class="input" value="${esc(c.responsiblePerson||'')}"></div><div class="field"><label>Reminder Before Due</label><input id="cal_reminder" class="input" value="${esc(c.reminder||'')}"></div><div class="field"><label>Result</label><select id="cal_result" class="select">${['Pass','Fail','Pending','Expired'].map(v=>`<option ${c.result===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Certificate Number</label><input id="cal_cert" class="input" value="${esc(c.certificateNumber||'')}"></div><div class="field"><label>Performed By</label><input id="cal_performed" class="input" value="${esc(c.performedBy||'')}"></div><div class="field" style="grid-column:1/-1"><label>Certificate File</label><input id="cal_file" type="file" class="input" accept=".pdf,.png,.jpg,.jpeg"></div></div><div class="field"><label>Remarks</label><textarea id="cal_remarks" class="textarea">${esc(c.remarks||'')}</textarea></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveInstrumentCalibration('${iid}','${cid||''}')">Save Calibration</button>`)}
function saveInstrumentCalibration(iid,cid){const x=instrumentRecords().find(i=>i.id===iid);const c=cid?x.calibrations.find(v=>v.id===cid):{id:uid('CAL')};c.type=document.getElementById('cal_type').value.trim();c.frequency=document.getElementById('cal_frequency').value.trim();c.date=document.getElementById('cal_date').value;c.nextDue=document.getElementById('cal_next').value;c.department=document.getElementById('cal_dept').value.trim();c.responsiblePerson=document.getElementById('cal_person').value.trim();c.reminder=document.getElementById('cal_reminder').value.trim();c.result=document.getElementById('cal_result').value;c.certificateNumber=document.getElementById('cal_cert').value.trim();c.performedBy=document.getElementById('cal_performed').value.trim();c.remarks=document.getElementById('cal_remarks').value.trim();const file=document.getElementById('cal_file').files[0];const finish=()=>{if(!c.type||!c.frequency||!c.date||!c.nextDue){alert('Please complete all required calibration fields marked *.');return}if(!cid)x.calibrations.push(c);x.lastCalibration=c.date;x.nextCalibration=c.nextDue;save();log(cid?'Edit Calibration':'Add Calibration',`${x.idn} / ${c.type}`);returnInstrumentEditor(iid,'calibration')};if(file){const r=new FileReader();r.onload=()=>{c.certificateFile={name:file.name,size:file.size,data:r.result};finish()};r.readAsDataURL(file)}else finish()}
function editInstrumentCalibration(iid,cid){addInstrumentCalibration(iid,cid)}
function deleteInstrumentCalibration(iid,cid){if(!instrumentCanEdit())return;const x=instrumentRecordForEdit(iid);if(!x||!confirm('Delete this calibration record?'))return;x.calibrations=x.calibrations.filter(c=>c.id!==cid);const latest=x.calibrations.slice().sort((a,b)=>String(b.date).localeCompare(String(a.date)))[0];x.lastCalibration=latest?.date||'';x.nextCalibration=latest?.nextDue||'';save();log('Delete Calibration',`${x.idn} / ${cid}`);returnInstrumentEditor(iid,'calibration')}
