function makeSimplePDF(lines){const pageW=595,pageH=842,left=36,top=806,lineH=12,perPage=61;const pages=[];for(let i=0;i<lines.length;i+=perPage)pages.push(lines.slice(i,i+perPage));const objs=[],add=s=>{objs.push(s);return objs.length},catalog=add(''),pagesObj=add(''),font=add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'),kids=[];pages.forEach((set,pi)=>{let stream=`BT /F1 8 Tf ${left} ${top} Td `;set.forEach((line,i)=>{if(i)stream+=`0 -${lineH} Td `;stream+=`(${pdfText(line)}) Tj `});stream+='ET';const content=add(`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`);kids.push(add(`<< /Type /Page /Parent ${pagesObj} 0 R /MediaBox [0 0 ${pageW} ${pageH}] /Resources << /Font << /F1 ${font} 0 R >> >> /Contents ${content} 0 R >>`))});objs[catalog-1]=`<< /Type /Catalog /Pages ${pagesObj} 0 R >>`;objs[pagesObj-1]=`<< /Type /Pages /Kids [${kids.map(k=>k+' 0 R').join(' ')}] /Count ${kids.length} >>`;let out='%PDF-1.4\n',offs=[0];objs.forEach((o,i)=>{offs[i+1]=out.length;out+=`${i+1} 0 obj\n${o}\nendobj\n`});const x=out.length;out+=`xref\n0 ${objs.length+1}\n0000000000 65535 f \n`;for(let i=1;i<offs.length;i++)out+=String(offs[i]).padStart(10,'0')+' 00000 n \n';return out+`trailer\n<< /Size ${objs.length+1} /Root ${catalog} 0 R >>\nstartxref\n${x}\n%%EOF`}
