function renderChromSelected(){const sid=document.getElementById('chromSequence')?.value,iid=document.getElementById('chromInjection')?.value,s=sequenceData().find(x=>x.id===sid),x=s?.injectionList.find(i=>i.id===iid),a=document.getElementById('chromArea');if(!a)return;if(!x){a.className='empty';a.textContent='Select a method, sequence, and injection to display chromatogram';return}const data=ensureAcquisitionData(x),total=Number(x.acquisition?.totalTime||x.runTime||10),cur=x.status==='Running'||x.status==='Paused'?Number(x.acquisition?.currentTime||0):total;const status=x.status==='Running'?'● Acquisition Running':x.status==='Paused'?'Ⅱ Acquisition Paused':x.status==='Completed'?'Completed':x.status==='Aborted'?'Aborted':'Ready';a.className='chrom-live-wrap';a.innerHTML=chromatogramInfo(x,s)+`<div class="chrom-live-status ${x.status==='Running'?'running':x.status==='Aborted'?'aborted':''}">${status}</div><div class="chrom-live-controls chrom-no-print"><button class="btn primary" onclick="startStandaloneAcquisition('${sid}','${iid}')">▶ Start</button><button class="btn" onclick="pauseStandaloneAcquisition('${sid}','${iid}')">Ⅱ Pause</button><button class="btn danger" onclick="abortStandaloneAcquisition('${sid}','${iid}')">■ Abort</button><button class="btn" onclick="resetStandaloneAcquisition('${sid}','${iid}')">↻ Reset</button><span class="speed-label">Simulation Speed</span><select id="chromSpeed" class="select"><option value="0.5">0.5×</option><option value="1" selected>1×</option><option value="2">2×</option></select></div><div class="chrom-live-progress"><i style="width:${Math.round(cur/total*100)}%"></i></div><div id="chromLiveChart" class="chrom-live-chart">${renderLiveChromSvg(data,cur,total)}</div>${x.status==='Completed'?chromatogramPeakTable(x):'<div class="empty" style="height:70px">Peak Table will be available after acquisition is completed.</div>'}`;if(x.status==='Running')startStandaloneAcquisition(sid,iid,true)}
function findInjection(seqId,injId){const s=sequenceData().find(x=>x.id===seqId);return {s,x:s?.injectionList.find(i=>i.id===injId)}}
function startStandaloneAcquisition(seqId,injId,continueExisting=false){const {s,x}=findInjection(seqId,injId);if(!s||!x)return;if(x.status==='Completed'&&!continueExisting)return;if(x.status==='Aborted'&&!continueExisting){x.status='Pending'}ensureAcquisitionData(x);const total=Number(x.runTime)||10;const speed=Number(document.getElementById('chromSpeed')?.value||1);x.status='Running';x.acquisition=x.acquisition||{status:'Running',currentTime:0,totalTime:total};x.acquisition.status='Running';x.acquisition.totalTime=total;const existing=Number(x.acquisition.currentTime)||0;const duration=HPLC_SIM_DURATION_MS/speed;let start=performance.now()-(existing/total)*duration;if(window.__hplcStandalone?.raf)cancelAnimationFrame(window.__hplcStandalone.raf);window.__hplcStandalone={seqId,injId,raf:null};const tick=(ts)=>{const run=window.__hplcStandalone;if(!run||run.seqId!==seqId||run.injId!==injId)return;const cur=Math.min(total,Math.max(0,(ts-start)/duration*total));x.acquisition.currentTime=Number(cur.toFixed(3));const chart=document.getElementById('chromLiveChart');if(chart)chart.innerHTML=renderLiveChromSvg(x.acquisitionData,cur,total);const p=document.querySelector('#chromArea .chrom-live-progress i');if(p)p.style.width=`${Math.round(cur/total*100)}%`;const meta=document.querySelector('#chromArea .chrom-live-meta .detail-item:nth-child(4) b');if(meta)meta.textContent=`${cur.toFixed(2)} / ${total.toFixed(2)} min`;if(cur>=total){x.status='Completed';x.acquisition.status='Completed';x.result=resultFromChromatogram(x,x.acquisitionData);log('Complete Acquisition',`${s.idn} / ${x.injectionId}`);save();window.__hplcStandalone=null;renderChromSelected();return}run.raf=requestAnimationFrame(tick)};save();window.__hplcStandalone.raf=requestAnimationFrame(tick)}
function pauseStandaloneAcquisition(seqId,injId){const {x}=findInjection(seqId,injId);if(!x)return;if(x.status!=='Running')return;if(window.__hplcStandalone?.raf)cancelAnimationFrame(window.__hplcStandalone.raf);window.__hplcStandalone=null;x.status='Paused';x.acquisition.status='Paused';save();renderChromSelected()}
function abortStandaloneAcquisition(seqId,injId){const {s,x}=findInjection(seqId,injId);if(!x)return;if(!confirm('Are you sure you want to abort this injection?'))return;if(window.__hplcStandalone?.raf)cancelAnimationFrame(window.__hplcStandalone.raf);window.__hplcStandalone=null;x.status='Aborted';x.acquisition=x.acquisition||{};x.acquisition.status='Aborted';x.acquisition.abortedAt=now();log('Abort Acquisition',`${s.idn} / ${x.injectionId}`);save();renderChromSelected()}
function resetStandaloneAcquisition(seqId,injId){const {x}=findInjection(seqId,injId);if(!x)return;if(window.__hplcStandalone?.raf)cancelAnimationFrame(window.__hplcStandalone.raf);window.__hplcStandalone=null;x.status='Pending';x.result=null;x.acquisition={status:'Ready',currentTime:0,totalTime:Number(x.runTime)||10};ensureAcquisitionData(x);save();log('Reset Acquisition',x.injectionId);renderChromSelected()}
