function assayContext(){
  const methods=state.methods||[];
  let methodId=window.__assayMethodId||'';
  if(!methodId&&methods[0])methodId=methods[0].id;
  const seqs=sequenceData().filter(s=>!methodId||s.method===methodId);
  let seqId=window.__assaySequenceId;
  let seq=seqs.find(s=>s.id===seqId)||seqs.find(s=>s.injectionList?.some(i=>i.status==='Completed'))||seqs[0];
  if(seq){seqId=seq.id;window.__assaySequenceId=seqId;methodId=seq.method||methodId;window.__assayMethodId=methodId}
  const injections=seq?.injectionList||[];
  let injId=window.__assayInjectionId;
  let x=injections.find(i=>i.id===injId)||injections.find(i=>i.status==='Completed')||injections[0];
  if(x){injId=x.id;window.__assayInjectionId=injId}
  return {methods,seqs,seq,injections,x,methodId,seqId,injId};
}
