function assayEnsureRecord(x){
  state.assays=state.assays||[];
  let a=assayRecordFor(x);
  if(!a){a={id:uid('ASS'),injectionId:x.id,injectionLabel:x.injectionId,status:'DRAFT',selectedPeakIndex:null,calculationLog:[],qc:{status:'DRAFT'},qa:{status:'Pending'}};state.assays.push(a)}
  a.calculationLog=a.calculationLog||[];a.qc=a.qc||{status:'DRAFT'};a.qa=a.qa||{status:'Pending'};
  return a;
}
function assayBadge(s){const v=String(s||'Pending');const c=v==='PASS'||v==='Approved'||v==='Passed'?'approved':(v==='FAIL'||v==='Rejected'?'rejected':v==='DRAFT'?'draft':'pending');return `<span class="badge ${c}">${esc(v)}</span>`}
function assayCanEdit(){return role()==='QC'||role()==='Admin'}
function assayCanQA(){return role()==='QA'||role()==='Admin'}
function assaySpec(method){
  const m=method||{}; const s=m.specification||m.assaySpecification||m.assaySpec;
  if(typeof s==='object'&&s){const lo=Number(s.lower??s.min??s.low),hi=Number(s.upper??s.max??s.high);if(Number.isFinite(lo)&&Number.isFinite(hi))return {lower:lo,upper:hi,text:`${lo.toFixed(1)} – ${hi.toFixed(1)} %`}}
  const txt=String(m.assaySpecification||m.specification||'');const nums=txt.match(/\d+(?:\.\d+)?/g);if(nums?.length>=2)return {lower:Number(nums[0]),upper:Number(nums[1]),text:`${Number(nums[0]).toFixed(1)} – ${Number(nums[1]).toFixed(1)} %`};
  return {lower:98,upper:102,text:'98.0 – 102.0 %'};
}
function assaySample(x){return {...assayDemo().assaySample,...(x?.assaySample||{})}}
function assayStatus(x){return x?.status||'Pending'}
function assayPeakData(x){
  const raw=(x?.result?.peaks?.length?x.result.peaks:(x?.result?.chromatogramData?.length?resultFromChromatogram(x,x.result.chromatogramData).peaks:assayDemo().result.peaks));
  return raw.map(p=>({...p,rt:Number(p.rt),area:Number(p.area||0),height:Number(p.height||0)}));
}
function assayMainPeak(x){const peaks=assayPeakData(x);return peaks.find(p=>String(p.identification||'').toLowerCase().includes('paracetamol')||String(p.identification||'').toLowerCase().includes('analyte'))||peaks.reduce((a,b)=>b.height>a.height?b:a,peaks[0])}
function assaySelectedPeakIndex(x,a){const peaks=assayPeakData(x);if(a?.selectedPeakIndex!=null&&peaks[a.selectedPeakIndex])return Number(a.selectedPeakIndex);const idx=peaks.findIndex(p=>String(p.identification||'').toLowerCase().includes('paracetamol')||String(p.identification||'').toLowerCase().includes('analyte'));return idx>=0?idx:(peaks.length?0:null)}
function assayCalculation(a,x,method){
  const sample=assaySample(x),peaks=assayPeakData(x),idx=assaySelectedPeakIndex(x,a),peak=idx==null?null:peaks[idx];
  const input=a?.calculation?.input||{};
  const stdArea=Number(input.standardPeakArea||a?.calculation?.standardPeakArea||985214);
  const stdConc=Number(input.standardConcentration||100);
  const dilution=Number(input.dilutionFactor||sample.dilutionFactor||1);
  const purity=Number(input.standardPurity||sample.potency||100);
  const label=Number(input.labelClaim||sample.labelClaim||500);
  const sampleArea=Number(input.samplePeakArea||peak?.area||0);
  const concentration=stdArea>0?(sampleArea/stdArea)*stdConc*dilution*(purity/100):0;
  const assay=label>0?(concentration/label)*100:0;
  const spec=assaySpec(method); const valid=stdArea>0&&sampleArea>0&&stdConc>0&&dilution>0&&label>0&&idx!=null; const result=valid?(assay>=spec.lower&&assay<=spec.upper?'PASS':'FAIL'):'PENDING';
  return {idx,peak,stdArea,stdConc,dilution,purity,label,sampleArea,concentration,assay,spec,result,valid};
}
function assayInjectionNavigation(delta){const ctx=assayContext();const arr=ctx.injections||[];if(!arr.length)return;let i=arr.findIndex(v=>v.id===ctx.injId);i=Math.max(0,Math.min(arr.length-1,i+delta));window.__assayInjectionId=arr[i].id;log('Select Injection',arr[i].injectionId);save();renderAssay(document.getElementById('content'))}
function renderAssay(c){
  const ctx=assayContext(),x=ctx.x||assayDemo(),sample=assaySample(ctx.x),a=assayEnsureRecord(x),peaks=assayPeakData(x),method=state.methods.find(m=>m.id===ctx.methodId),calc=assayCalculation(a,x,method),selected=calc.idx;
  const methodOptions=ctx.methods.length?ctx.methods.map(m=>`<option value="${esc(m.id)}" ${ctx.methodId===m.id?'selected':''}>${esc(m.methodId)} — ${esc(m.name)}</option>`).join(''):`<option value="">M-001 — Analysis of Paracetamol</option>`;
  const seqOptions=ctx.seqs.length?ctx.seqs.map(s=>`<option value="${esc(s.id)}" ${ctx.seqId===s.id?'selected':''}>${esc(s.idn)}${s.name?' — '+esc(s.name):''}</option>`).join(''):`<option value="">SEQ-20260918-001</option>`;
  const injOptions=ctx.injections.length?ctx.injections.map(i=>`<option value="${esc(i.id)}" ${ctx.injId===i.id?'selected':''}>${esc(i.injectionId)}${i.sampleName?' — '+esc(i.sampleName):''}</option>`).join(''):`<option value="">INJ-001</option>`;
  const selectedPeak=selected==null?null:peaks[selected];
  const reviewStatus=a.status||'DRAFT';
  c.innerHTML=header('Assay / Data Review','Calculate assay results and perform QC review before submitting for QA approval.')+
  `<div class="assay-review-page">
    <div class="panel assay-selection no-print"><div class="assay-selection-grid">
      <div class="field"><label>Analytical Method</label><select id="assayMethod" class="select" onchange="assayMethodChanged()">${methodOptions}</select></div>
      <div class="field"><label>Sequence</label><select id="assaySequence" class="select" onchange="assaySequenceChanged()">${seqOptions}</select></div>
      <div class="field"><label>Injection</label><select id="assayInjection" class="select" onchange="assayInjectionChanged()">${injOptions}</select></div>
      <div class="field"><label>Sample</label><select id="assaySampleFilter" class="select" onchange="assayInjectionChanged()"><option>${esc(x.sampleName||sample.productName||'—')}</option></select></div>
      <div class="field"><label>Sample Type</label><select id="assaySampleType" class="select"><option>${esc(x.sampleType||'Sample')}</option><option>Standard</option><option>Blank</option><option>System Suitability</option></select></div>
      <div class="field"><label>Status</label><select id="assayStatusFilter" class="select"><option>${esc(reviewStatus)}</option><option>DRAFT</option><option>Pending QA Review</option><option>Approved</option><option>Revision Required</option></select></div>
      <div class="assay-filter-buttons"><button class="btn" onclick="resetAssayFilters()">Reset</button><button class="btn blue" onclick="searchAssayReview()">Search</button></div>
    </div></div>

    <div class="assay-injection-card panel">
      <div class="panel-head"><h3>Injection / Sample Information</h3><div class="assay-nav-buttons no-print"><button class="btn mini-btn" onclick="assayInjectionNavigation(-1)">‹ Previous</button><button class="btn mini-btn" onclick="assayInjectionNavigation(1)">Next ›</button><button class="btn mini-btn" onclick="viewAssayChromatogram()">View Chromatogram</button></div></div>
      <div class="assay-injection-grid">${[['Sequence',ctx.seq?.idn||'—'],['Injection',x.injectionId],['Sample ID',sample.sampleId||x.sampleName||'—'],['Sample Type',x.sampleType||'—'],['Analytical Method',assayMethodLabel(ctx.methodId)],['Instrument',seqInstrumentLabel(ctx.seq?.instrument)||x.instrument||'—'],['Run Date & Time',x.acquisitionDate||'—'],['Status',x.status==='Completed'?'Data Ready':assayStatus(x)]].map(r=>`<div><span>${esc(r[0])}</span><b>${r[0]==='Status'?badge(r[1]):esc(r[1])}</b></div>`).join('')}</div>
    </div>

    <div class="assay-review-two-col">
      <div class="panel"><div class="panel-head"><h3>1. Peak Selection</h3><span class="panel-subtitle">Select the analyte peak for calculation.</span></div>
        <div class="table-wrap"><table class="table assay-select-table"><thead><tr><th>#</th><th>Select</th><th>RT (min)</th><th>Area</th><th>Height</th><th>Identification</th></tr></thead><tbody>${peaks.map((p,i)=>`<tr class="${selected===i?'assay-selected-row':''}"><td>${i+1}</td><td><input type="radio" name="assayPeak" ${selected===i?'checked':''} onclick="selectAssayPeak(${i})"></td><td>${p.rt.toFixed(3)}</td><td>${p.area.toLocaleString('en-US')}</td><td>${p.height.toLocaleString('en-US')}</td><td>${esc(p.identification||'Unknown')}</td></tr>`).join('')}</tbody></table></div>
      </div>
      <div class="panel"><div class="panel-head"><h3>Chromatogram Preview</h3><button class="btn mini-btn no-print" onclick="viewAssayChromatogram()">View Full Chromatogram ↗</button></div><div class="assay-chart-wrap assay-interactive-chart">${assayReviewChromatogram(x,peaks,selected)}</div></div>
    </div>

    <div class="panel"><div class="panel-head"><h3>Peak Table</h3><div class="assay-head-actions"><button class="btn mini-btn" onclick="processAssayPeaks()">⚙ Process Peaks</button><button class="btn mini-btn" onclick="saveAssayPeakResult()">▣ Save Peak Result</button></div></div>
      <div class="table-wrap"><table class="table assay-peak-table"><thead><tr><th>Peak #</th><th>RT (min)</th><th>Area</th><th>Height</th><th>Area %</th><th>Height %</th><th>Resolution</th><th>Tailing Factor</th><th>Identification</th><th>Status</th><th>Action</th></tr></thead><tbody>${peaks.map((p,i)=>`<tr><td>${i+1}</td><td>${p.rt.toFixed(3)}</td><td>${p.area.toLocaleString('en-US')}</td><td>${p.height.toLocaleString('en-US')}</td><td>${esc(p.areaPct??'—')}%</td><td>${esc(p.heightPct??'—')}%</td><td>${esc(p.resolution??'—')}</td><td>${esc(p.tailing??'—')}</td><td>${esc(p.identification||'Unknown')}</td><td>${badge('Reviewed')}</td><td><div class="actions"><button class="btn mini-btn" onclick="viewAssayPeak(${i})">View</button><button class="btn mini-btn" ${assayCanEdit()?'':'disabled'} onclick="editAssayPeak(${i})">Edit</button><button class="btn mini-btn" onclick="selectAssayPeak(${i})">Select</button></div></td></tr>`).join('')}</tbody></table></div>
    </div>

    <div class="panel"><div class="panel-head"><h3>Sample Details</h3><button class="btn mini-btn no-print" ${assayCanEdit()?'':'disabled'} onclick="editAssaySampleDetails()">Edit Sample</button></div><div class="sample-review-grid">${[['Sample ID',sample.sampleId],['Batch No.',sample.batchNo],['Sample Type',x.sampleType],['Sample Weight',sample.sampleWeight?sample.sampleWeight+' g':'—'],['Dilution Factor',sample.dilutionFactor||'1'],['Label Claim',sample.labelClaim?(sample.labelClaim+' '+(sample.labelClaimUnit||'')):'—'],['Solvent',sample.solvent],['Sample Preparation',sample.samplePreparation],['Prepared By',sample.preparedBy],['Preparation Date',sample.preparationDate],['Comments',sample.comments]].map(r=>`<div><span>${esc(r[0])}</span><b>${esc(r[1]||'—')}</b></div>`).join('')}</div></div>

    <div class="panel assay-calc-section"><div class="panel-head"><h3>Assay Calculation</h3><div class="assay-head-actions no-print"><button class="btn mini-btn" onclick="calculateAssay()">Calculate</button><button class="btn mini-btn" ${assayCanEdit()?'':'disabled'} onclick="saveAssayCalculation()">Save Calculation</button><button class="btn mini-btn" onclick="viewCalculationLog()">View Calculation Log</button></div></div>
      <div class="assay-calc-form"><div class="calc-input-box"><h4>Calculation Inputs</h4><div class="formgrid"><div class="field"><label>Standard Peak Area</label><input id="calc_std_area" type="number" class="input" value="${esc(a.calculation?.input?.standardPeakArea??985214)}" ${assayCanEdit()?'':'disabled'}></div><div class="field"><label>Sample Peak Area</label><input id="calc_sample_area" type="number" class="input" value="${esc(a.calculation?.input?.samplePeakArea??selectedPeak?.area??0)}" disabled></div><div class="field"><label>Standard Concentration</label><input id="calc_std_conc" type="number" class="input" value="${esc(a.calculation?.input?.standardConcentration??100)}" ${assayCanEdit()?'':'disabled'}></div><div class="field"><label>Dilution / Preparation Factor</label><input id="calc_dilution" type="number" class="input" value="${esc(a.calculation?.input?.dilutionFactor??sample.dilutionFactor??1)}" ${assayCanEdit()?'':'disabled'}></div><div class="field"><label>Potency / Purity (%)</label><input id="calc_purity" type="number" class="input" value="${esc(a.calculation?.input?.standardPurity??sample.potency??100)}" ${assayCanEdit()?'':'disabled'}></div><div class="field"><label>Label Claim</label><input id="calc_label" type="number" class="input" value="${esc(a.calculation?.input?.labelClaim??sample.labelClaim??500)}" ${assayCanEdit()?'':'disabled'}></div></div></div>
      <div class="calc-result-box"><h4>Calculated Result</h4><div class="calc-result-lines"><div><span>Selected Peak</span><b>${selectedPeak?esc(selectedPeak.name)+' · '+selectedPeak.rt.toFixed(3)+' min':'Not selected'}</b></div><div><span>Sample Concentration</span><b>${calc.valid?calc.concentration.toFixed(2):'—'} µg/mL</b></div><div class="assay-highlight"><span>Assay</span><b>${calc.valid?calc.assay.toFixed(2):'—'} %</b></div><div><span>Specification</span><b>${esc(calc.spec.text)}</b></div><div><span>Result</span><b class="result-pill ${calc.result==='PASS'?'pass':calc.result==='FAIL'?'fail':'pending'}">${calc.result}</b></div></div></div></div>
      <div class="calculation-formula"><b>Formula:</b> (Sample Peak Area / Standard Peak Area) × Standard Concentration × Dilution/Preparation Factor × Purity correction ÷ Label Claim × 100. ${method?.assayFormula?`Method formula: ${esc(method.assayFormula)}`:'Uses the stored Analytical Method parameters when available.'}</div>
    </div>

    <div class="panel assay-result-panel"><div class="panel-head"><h3>Assay Result</h3></div><div class="assay-result-table"><table class="table"><thead><tr><th>Parameter</th><th>Result</th><th>Specification</th><th>Status</th></tr></thead><tbody><tr><td>Assay (%)</td><td>${calc.valid?calc.assay.toFixed(2)+' %':'—'}</td><td>${esc(calc.spec.text)}</td><td>${assayBadge(calc.result)}</td></tr><tr><td>Retention Time</td><td>${selectedPeak?selectedPeak.rt.toFixed(3)+' min':'—'}</td><td>Method acceptance</td><td>${selectedPeak?'Available':'PENDING'}</td></tr><tr><td>Resolution</td><td>${selectedPeak?.resolution??'—'}</td><td>Method acceptance</td><td>${selectedPeak?.resolution&&Number(selectedPeak.resolution)>=2?'PASS':'PENDING'}</td></tr><tr><td>Tailing Factor</td><td>${selectedPeak?.tailing??'—'}</td><td>Method acceptance</td><td>${selectedPeak?.tailing&&Number(selectedPeak.tailing)<=2?'PASS':'PENDING'}</td></tr></tbody></table></div></div>

    <div class="panel"><div class="panel-head"><h3>Calculation Log</h3><button class="btn mini-btn no-print" onclick="viewCalculationLog()">View Calculation Log</button></div><div class="table-wrap">${a.calculationLog?.length?`<table class="table"><thead><tr><th>Calculation ID</th><th>Injection</th><th>Selected Peak</th><th>Sample Area</th><th>Standard Area</th><th>Assay</th><th>Result</th><th>Calculated By</th><th>Date/Time</th></tr></thead><tbody>${a.calculationLog.map(l=>`<tr><td>${esc(l.id)}</td><td>${esc(x.injectionId)}</td><td>${esc(l.peak)}</td><td>${Number(l.sampleArea||0).toLocaleString('en-US')}</td><td>${Number(l.standardArea||0).toLocaleString('en-US')}</td><td>${Number(l.assay||0).toFixed(2)}%</td><td>${assayBadge(l.result)}</td><td>${esc(l.by)}</td><td>${esc(l.date)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No calculation has been saved for this injection.</div>'}</div></div>

    <div class="panel"><div class="panel-head"><h3>Previous Results</h3></div><div class="table-wrap">${renderPreviousAssayResults(x,sample)}</div></div>

    <div class="assay-status-grid"><div class="panel"><div class="panel-head"><h3>Current Status</h3></div><div class="current-status-simple"><div><span>Status</span><b>${assayBadge(reviewStatus)}</b></div><div><span>Selected Peak</span><b>${selectedPeak?esc(selectedPeak.name)+' · '+selectedPeak.rt.toFixed(3)+' min':'—'}</b></div><div><span>Review Status</span><b>${esc(a.qc?.status||'DRAFT')}</b></div><div><span>Reviewer</span><b>${esc(a.qc?.by||'—')}</b></div><div><span>Review Date</span><b>${esc(a.qc?.date||'—')}</b></div><div><span>Comment</span><b>${esc(a.qc?.comment||'—')}</b></div></div></div>
      <div class="panel"><div class="panel-head"><h3>QC Review</h3></div><div class="review-card-lines"><div><span>Review Status</span><b>${assayBadge(a.qc?.status||'DRAFT')}</b></div><div><span>Prepared By</span><b>${esc(a.qc?.by||state.session?.username||'QC User')}</b></div><div><span>Prepared Date</span><b>${esc(a.qc?.date||'—')}</b></div><div><span>Selected Peak</span><b>${selectedPeak?esc(selectedPeak.name):'—'}</b></div><div><span>Calculation Status</span><b>${calc.valid?'Calculated':'Pending'}</b></div><div><span>Assay Result</span><b>${calc.valid?calc.assay.toFixed(2)+' %':'—'}</b></div><div><span>Specification</span><b>${calc.valid?calc.result:'Pending'}</b></div><div><span>QC Comment</span><b>${esc(a.qc?.comment||'—')}</b></div></div><div class="review-buttons no-print"><button class="btn" ${assayCanEdit()?'':'disabled'} onclick="saveAssayReview()">Save Review</button><button class="btn blue" ${assayCanEdit()?'':'disabled'} onclick="submitAssayToQA()">Submit for QA Review</button></div></div>
      <div class="panel"><div class="panel-head"><h3>QA Review</h3></div><div class="review-card-lines"><div><span>Status</span><b>${assayBadge(a.qa?.status||'Pending')}</b></div><div><span>Reviewed By</span><b>${esc(a.qa?.by||'—')}</b></div><div><span>Date/Time</span><b>${esc(a.qa?.date||'—')}</b></div><div><span>Comment</span><b>${esc(a.qa?.comment||'—')}</b></div><div><span>E-Signature</span><b>${a.qa?.signature?'Signed':'—'}</b></div></div><div class="qa-actions no-print"><button class="btn" ${assayCanQA()&&a.status==='Pending QA Review'?'':'disabled'} onclick="approveAssayReview()">✓ Approve & Sign</button><button class="btn danger" ${assayCanQA()&&a.status==='Pending QA Review'?'':'disabled'} onclick="requestAssayRevision()">Request Revision</button></div></div></div>

    <div class="panel"><div class="panel-head"><h3>Supporting Documents / Attachments</h3><button class="btn mini-btn no-print" ${assayCanEdit()?'':'disabled'} onclick="addAssayAttachment()">＋ Add File</button></div><div class="attachments-list">${renderAssayAttachments(a,x)}</div></div>
    <div class="panel"><div class="panel-head"><h3>Comments</h3></div><textarea id="assayGeneralComment" class="textarea" placeholder="Enter comments..." ${assayCanEdit()?'':'disabled'}>${esc(a.comment||'')}</textarea><div class="assay-footer-actions no-print"><button class="btn" ${assayCanEdit()?'':'disabled'} onclick="saveAssayComment()">Save</button><button class="btn" onclick="exportAssayPDF()">Export PDF</button><button class="btn" onclick="printAssayReview()">Print</button></div></div>
  </div>`;
}
function assayReviewChromatogram(x,peaks,selectedIndex){
  const data=ensureAcquisitionData(x||assayDemo()),W=620,H=240,L=48,R=14,T=14,B=40,plotW=W-L-R,plotH=H-T-B,total=Number(x?.runTime||10),maxY=Math.max(1,...data.map(d=>Number(d.y)||0))*1.08,xp=t=>L+(t/total)*plotW,yp=v=>T+plotH-(v/maxY)*plotH;
  const pts=data.map(d=>`${xp(Number(d.t)).toFixed(2)},${yp(Number(d.y)).toFixed(2)}`).join(' ');
  const grid=[0,.25,.5,.75,1].map(f=>{const yy=T+plotH-f*plotH;return `<line class="gridline" x1="${L}" y1="${yy}" x2="${W-R}" y2="${yy}"/><text x="3" y="${yy+3}">${Math.round(maxY*f).toLocaleString()}</text>`}).join('');
  const peakMarks=peaks.map((p,i)=>`<g class="assay-peak-hit ${selectedIndex===i?'selected':''}" onclick="selectAssayPeak(${i})"><line x1="${xp(p.rt)}" y1="${yp(p.height)}" x2="${xp(p.rt)}" y2="${T+plotH}" class="assay-peak-guide"/><circle cx="${xp(p.rt)}" cy="${yp(p.height)}" r="${selectedIndex===i?5:4}" class="assay-peak-dot"/><text x="${xp(p.rt)}" y="${Math.max(11,yp(p.height)-8)}" text-anchor="middle" class="peak-label">${p.rt.toFixed(3)}</text></g>`).join('');
  return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Chromatogram preview"><g>${grid}</g><line class="axis" x1="${L}" y1="${T+plotH}" x2="${W-R}" y2="${T+plotH}"/><line class="axis" x1="${L}" y1="${T}" x2="${L}" y2="${T+plotH}"/><polyline points="${pts}" class="assay-trace"/>${peakMarks}<text x="${W/2}" y="${H-6}" text-anchor="middle">Retention Time (min)</text><text x="13" y="${H/2+20}" transform="rotate(-90 13 ${H/2+20})" text-anchor="middle">UV Response (mAU)</text><text x="${L}" y="${H-21}">0</text><text x="${W-R}" y="${H-21}" text-anchor="end">${total.toFixed(2)}</text></svg>`;
}
function selectAssayPeak(i){const ctx=assayContext(),x=ctx.x;if(!x)return;const a=assayEnsureRecord(x);a.selectedPeakIndex=i;a.calculation=a.calculation||{};a.calculation.input=a.calculation.input||{};a.calculation.input.samplePeakArea=assayPeakData(x)[i]?.area||0;save();log('Select Peak',`${x.injectionId} — Peak ${i+1}`);renderAssay(document.getElementById('content'))}
function saveAssayCalculation(){const ctx=assayContext(),x=ctx.x;if(!x||!assayCanEdit())return;const a=assayEnsureRecord(x),r=assayCalculation(a,x,state.methods.find(m=>m.id===ctx.methodId));if(!r.valid){alert('Please complete the calculation inputs first.');return}if(!a.calculation?.calculationId){calculateAssay();return}log('Save Calculation',`${x.injectionId} — ${a.calculation.calculationId}`);save();renderAssay(document.getElementById('content'))}
function calculateAssay(){const ctx=assayContext(),x=ctx.x;if(!x){alert('Please select an injection.');return}if(!assayCanEdit()){alert('Only QC can perform assay calculation.');return}const a=assayEnsureRecord(x),peaks=assayPeakData(x),idx=assaySelectedPeakIndex(x,a);const vals={standardPeakArea:Number(document.getElementById('calc_std_area')?.value||0),samplePeakArea:idx==null?0:Number(peaks[idx]?.area||0),standardConcentration:Number(document.getElementById('calc_std_conc')?.value||0),dilutionFactor:Number(document.getElementById('calc_dilution')?.value||0),standardPurity:Number(document.getElementById('calc_purity')?.value||0),labelClaim:Number(document.getElementById('calc_label')?.value||0)};if(idx==null){alert('Select a peak before calculation.');return}if(!(vals.standardPeakArea>0)||!(vals.samplePeakArea>0)||!(vals.standardConcentration>0)||!(vals.dilutionFactor>0)||!(vals.labelClaim>0)){alert('Standard Peak Area, Sample Peak Area, Standard Concentration, Dilution Factor, and Label Claim must be valid positive values.');return}a.calculation={input:vals};const result=assayCalculation(a,x,state.methods.find(m=>m.id===ctx.methodId));a.calculation.result=result;a.calculation.calculationId=uid('CALC');a.calculation.calculatedBy=state.session?.username||'QC';a.calculation.calculatedAt=now();a.calculationLog.unshift({id:a.calculation.calculationId,peak:peaks[idx].name+' · '+peaks[idx].rt.toFixed(3)+' min',sampleArea:result.sampleArea,standardArea:result.stdArea,assay:result.assay,result:result.result,by:a.calculation.calculatedBy,date:a.calculation.calculatedAt,formula:'(Sample Area / Standard Area) × Standard Concentration × Dilution × Purity correction ÷ Label Claim × 100'});a.status='DRAFT';log('Calculate Assay',`${x.injectionId} — ${result.assay.toFixed(2)}% (${result.result})`);save();renderAssay(document.getElementById('content'))}
function viewPreviousAssayResult(id){const a=(state.assays||[]).find(v=>v.id===id);if(!a)return;openModal('Previous Result',`<div class="detail-grid">${[['Calculation ID',a.calculation?.calculationId||'—'],['Injection',a.injectionLabel||a.injectionId],['Selected Peak',a.calculation?.result?.peak?.name||'—'],['Sample Area',a.calculation?.result?.sampleArea?.toLocaleString?.('en-US')||'—'],['Assay',a.calculation?.result?.assay!=null?Number(a.calculation.result.assay).toFixed(2)+' %':'—'],['Result',a.calculation?.result?.result||'PENDING'],['Status',a.status||'DRAFT']].map(r=>`<div class="detail-item"><span>${esc(r[0])}</span><b>${esc(r[1])}</b></div>`).join('')}</div>`,`<button class="btn" onclick="closeModal()">Close</button>`)}
function renderPreviousAssayResults(x,sample){const rows=(state.assays||[]).filter(a=>a.injectionId!==x.id&&a.injectionId!==x.injectionId&&String(a.sampleId||a.assaySample?.sampleId||'')===String(sample.sampleId||''));if(!rows.length)return '<div class="empty">No previous results available for this sample.</div>';return `<table class="table"><thead><tr><th>No.</th><th>Injection</th><th>Sample ID</th><th>RT</th><th>Peak Area</th><th>Assay</th><th>Result</th><th>Review Status</th><th>Reviewer</th><th>Review Date</th><th>Action</th></tr></thead><tbody>${rows.map((a,i)=>`<tr><td>${i+1}</td><td>${esc(a.injectionLabel||a.injectionId)}</td><td>${esc(a.sampleId||sample.sampleId)}</td><td>${esc(a.calculation?.result?.peak?.rt?.toFixed?.(3)||'—')}</td><td>${Number(a.calculation?.result?.sampleArea||0).toLocaleString('en-US')}</td><td>${a.calculation?.result?.assay!=null?Number(a.calculation.result.assay).toFixed(2)+'%':'—'}</td><td>${assayBadge(a.calculation?.result?.result||'PENDING')}</td><td>${badge(a.status||'DRAFT')}</td><td>${esc(a.qc?.by||'—')}</td><td>${esc(a.qc?.date||'—')}</td><td><button class="btn mini-btn" onclick="viewPreviousAssayResult('${a.id}')">View</button></td></tr>`).join('')}</tbody></table>`}
function saveAssayReview(){const ctx=assayContext(),x=ctx.x;if(!x||!assayCanEdit())return;const a=assayEnsureRecord(x);a.qc={status:'Reviewed',by:state.session?.username||'QC User',date:now(),comment:document.getElementById('assayGeneralComment')?.value.trim()||'QC review saved.'};a.comment=a.qc.comment;log('Save QC Review',x.injectionId);save();renderAssay(document.getElementById('content'))}
function submitAssayToQA(){const ctx=assayContext(),x=ctx.x;if(!x||!assayCanEdit())return;const a=assayEnsureRecord(x);if(a.status==='Approved'){alert('Approved Data Review is locked.');return}const calc=assayCalculation(a,x,state.methods.find(m=>m.id===ctx.methodId));if(assaySelectedPeakIndex(x,a)==null){alert('Select a peak before submitting for QA review.');return}if(!calc.valid||!a.calculation?.calculationId){alert('Please complete and save the assay calculation before submitting for QA review.');return}if(x.status!=='Completed'){alert('Injection must be completed before submission.');return}a.status='Pending QA Review';a.qc={...(a.qc||{}),status:'Reviewed',by:state.session?.username||'QC User',date:a.qc?.date||now(),comment:document.getElementById('assayGeneralComment')?.value.trim()||a.qc?.comment||'QC review completed.'};a.submittedBy=state.session?.username||'QC User';a.submittedAt=now();log('Data Review submitted',`${x.injectionId} — QC submitted analytical result for QA review`);save();renderAssay(document.getElementById('content'))}
function approveAssayReview(){if(!assayCanQA()){alert('Only QA can approve Data Review.');return}const ctx=assayContext(),x=ctx.x,a=assayEnsureRecord(x);if(a.status!=='Pending QA Review'){alert('Data Review must be submitted to QA before approval.');return}openModal('Approve & Sign',`<div class="field"><label>QA Review Comment *</label><textarea id="qa_assay_comment" class="textarea"></textarea></div><div class="field" style="margin-top:10px"><label>QA Password / Electronic Signature *</label><input id="qa_assay_pass" type="password" class="input"></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn blue" onclick="confirmAssayApproval()">Approve & Sign</button>`)}
function confirmAssayApproval(){const ctx=assayContext(),x=ctx.x,a=assayEnsureRecord(x),pass=document.getElementById('qa_assay_pass')?.value||'',comment=document.getElementById('qa_assay_comment')?.value.trim()||'';if(pass!=='qa123'){alert('Invalid QA electronic signature password.');return}if(!comment){alert('QA Review Comment is required.');return}a.status='Approved';a.qa={status:'Approved',by:state.session?.username||'QA User',date:now(),comment,signature:'Signed'};a.comment=comment;log('Data Review QA review',x.injectionId);log('Data Review APPROVED',x.injectionId);save();closeModal();renderAssay(document.getElementById('content'))}
function requestAssayRevision(){if(!assayCanQA()){alert('Only QA can request revision.');return}const ctx=assayContext(),x=ctx.x,a=assayEnsureRecord(x);if(a.status!=='Pending QA Review'){alert('Data Review must be submitted to QA before requesting revision.');return}openModal('Request Revision',`<div class="field"><label>QA Review Comment *</label><textarea id="qa_revision_comment" class="textarea" placeholder="Describe required revision..."></textarea></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn danger" onclick="confirmAssayRevision()">Request Revision</button>`)}
function confirmAssayRevision(){const ctx=assayContext(),x=ctx.x,a=assayEnsureRecord(x),comment=document.getElementById('qa_revision_comment')?.value.trim();if(!comment){alert('QA Review Comment is required.');return}a.status='Revision Required';a.qa={status:'Revision Required',by:state.session?.username||'QA User',date:now(),comment};log('QA Request Revision',`${x.injectionId}: ${comment}`);save();closeModal();renderAssay(document.getElementById('content'))}
function viewAssayPeak(i){const p=assayPeakData(assaySelected())[i];if(!p)return;openModal('Peak Details',`<div class="detail-grid">${[['Peak Name',p.name],['Retention Time',p.rt.toFixed(3)+' min'],['Area',p.area.toLocaleString('en-US')],['Height',p.height.toLocaleString('en-US')],['Area %',(p.areaPct??'—')+'%'],['Height %',(p.heightPct??'—')+'%'],['Resolution',p.resolution??'—'],['Tailing Factor',p.tailing??'—'],['Identification',p.identification||'Unknown']].map(r=>`<div class="detail-item"><span>${esc(r[0])}</span><b>${esc(r[1])}</b></div>`).join('')}</div>`,`<button class="btn" onclick="closeModal()">Close</button>`)}
function editAssayPeak(i){if(!assayCanEdit()){alert('Only QC can edit peak data.');return}const ctx=assayContext(),p=assayPeakData(ctx.x)[i];openModal('Edit Peak',`<div class="formgrid"><div class="field"><label>Peak Name</label><input id="ap_name" class="input" value="${esc(p.name)}"></div><div class="field"><label>Retention Time</label><input id="ap_rt" type="number" step="0.001" class="input" value="${p.rt}"></div><div class="field"><label>Area</label><input id="ap_area" type="number" class="input" value="${p.area}"></div><div class="field"><label>Height</label><input id="ap_height" type="number" class="input" value="${p.height}"></div><div class="field"><label>Area %</label><input id="ap_areaPct" class="input" value="${esc(p.areaPct??'')}"></div><div class="field"><label>Height %</label><input id="ap_heightPct" class="input" value="${esc(p.heightPct??'')}"></div><div class="field"><label>Resolution</label><input id="ap_resolution" class="input" value="${esc(p.resolution??'')}"></div><div class="field"><label>Tailing Factor</label><input id="ap_tailing" class="input" value="${esc(p.tailing??'')}"></div><div class="field full"><label>Identification</label><input id="ap_identification" class="input" value="${esc(p.identification??'')}"></div></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveAssayPeak(${i})">Save Peak</button>`)}
function saveAssayPeak(i){const ctx=assayContext();if(!ctx.x||!assayCanEdit())return;const peaks=assayPeakData(ctx.x),p=peaks[i];p.name=document.getElementById('ap_name').value.trim();p.rt=Number(document.getElementById('ap_rt').value);p.area=Number(document.getElementById('ap_area').value);p.height=Number(document.getElementById('ap_height').value);p.areaPct=document.getElementById('ap_areaPct').value;p.heightPct=document.getElementById('ap_heightPct').value;p.resolution=document.getElementById('ap_resolution').value;p.tailing=document.getElementById('ap_tailing').value;p.identification=document.getElementById('ap_identification').value.trim();ctx.x.result=ctx.x.result||{};ctx.x.result.peaks=peaks;const a=assayEnsureRecord(ctx.x);a.selectedPeakIndex=i;save();log('Edit Peak',ctx.x.injectionId);closeModal();renderAssay(document.getElementById('content'))}
function processAssayPeaks(){const ctx=assayContext(),x=ctx.x;if(!x)return;if(!assayCanEdit()){alert('Only QC can process peaks.');return}x.result=x.result||{};x.result.peaks=assayPeakData(x);x.result.processingStatus='Processed';const a=assayEnsureRecord(x);a.processedAt=now();log('Process Peaks',x.injectionId);save();renderAssay(document.getElementById('content'))}
function saveAssayPeakResult(){const ctx=assayContext(),x=ctx.x;if(!x)return;if(!assayCanEdit()){alert('Only QC can save peak result.');return}x.result=x.result||{};x.result.peaks=assayPeakData(x);x.result.processingStatus='Processed';log('Save Peak Result',x.injectionId);save();alert('Peak result saved successfully.');renderAssay(document.getElementById('content'))}
function viewCalculationLog(){const ctx=assayContext(),x=ctx.x,a=assayEnsureRecord(x);const logs=a.calculationLog||[];openModal('Calculation Log',logs.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Calculation ID</th><th>Selected Peak</th><th>Sample Area</th><th>Standard Area</th><th>Assay</th><th>Result</th><th>By</th><th>Date</th></tr></thead><tbody>${logs.map(l=>`<tr><td>${esc(l.id)}</td><td>${esc(l.peak)}</td><td>${Number(l.sampleArea||0).toLocaleString('en-US')}</td><td>${Number(l.standardArea||0).toLocaleString('en-US')}</td><td>${Number(l.assay||0).toFixed(2)}%</td><td>${assayBadge(l.result)}</td><td>${esc(l.by)}</td><td>${esc(l.date)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No calculation log available.</div>','<button class="btn" onclick="closeModal()">Close</button>')}
function editAssaySampleDetails(){if(!assayCanEdit()){alert('Only QC can edit sample data.');return}const ctx=assayContext(),x=ctx.x,s=assaySample(x);openModal('Edit Sample',`<div class="formgrid">${[['Product Name','productName'],['Sample ID','sampleId'],['Batch No.','batchNo'],['Manufacturing Date','manufacturingDate'],['Expiry Date','expiryDate'],['Sample Weight','sampleWeight'],['Sample Preparation','samplePreparation'],['Dilution Factor','dilutionFactor'],['Label Claim','labelClaim'],['Label Claim Unit','labelClaimUnit'],['Potency / Standard Purity','potency'],['Sample Solvent','solvent'],['Prepared By','preparedBy'],['Preparation Date','preparationDate']].map(r=>`<div class="field"><label>${r[0]}${['productName','sampleId','batchNo'].includes(r[1])?' *':''}</label><input id="sd_${r[1]}" class="input" value="${esc(s[r[1]]||'')}"></div>`).join('')}<div class="field full"><label>Comments</label><textarea id="sd_comments" class="textarea">${esc(s.comments||'')}</textarea></div></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveAssaySampleDetails()">Save</button>`)}
function saveAssaySampleDetails(){const ctx=assayContext();if(!ctx.x||!assayCanEdit())return;const keys=['productName','sampleId','batchNo','manufacturingDate','expiryDate','sampleWeight','samplePreparation','dilutionFactor','labelClaim','labelClaimUnit','potency','solvent','preparedBy','preparationDate'];const s={};keys.forEach(k=>s[k]=document.getElementById('sd_'+k)?.value.trim()||'');s.comments=document.getElementById('sd_comments')?.value.trim()||'';if(!s.productName||!s.sampleId||!s.batchNo){alert('Product Name, Sample ID, and Batch No. are required.');return}if(s.sampleWeight&&Number(s.sampleWeight)<=0){alert('Sample Weight must be a positive number.');return}if(s.dilutionFactor&&Number(s.dilutionFactor)<=0){alert('Dilution Factor must be a positive number.');return}if(s.labelClaim&&Number(s.labelClaim)<=0){alert('Label Claim must be a positive number.');return}ctx.x.assaySample=s;save();log('Edit Sample',ctx.x.injectionId);alert('Sample details saved successfully.');closeModal();renderAssay(document.getElementById('content'))}
function editAssayInjection(){const ctx=assayContext(),x=ctx.x||assayDemo();if(!assayCanEdit()){alert('Only QC can edit injection information.');return}openModal('Edit Injection Information',`<div class="formgrid"><div class="field"><label>Sample Name</label><input id="ai_sample" class="input" value="${esc(x.sampleName||'')}"></div><div class="field"><label>Sample Type</label><input id="ai_type" class="input" value="${esc(x.sampleType||'Sample')}"></div><div class="field"><label>Run Time (min)</label><input id="ai_run" type="number" class="input" value="${esc(x.runTime||10)}"></div></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveAssayInjection()">Save</button>`)}
function saveAssayInjection(){const ctx=assayContext();if(!ctx.x||!assayCanEdit())return;ctx.x.sampleName=document.getElementById('ai_sample').value.trim();ctx.x.sampleType=document.getElementById('ai_type').value;ctx.x.runTime=Number(document.getElementById('ai_run').value)||10;save();log('Edit Injection Information',ctx.x.injectionId);closeModal();renderAssay(document.getElementById('content'))}
function saveAssayComment(){const ctx=assayContext(),x=ctx.x;if(!x||!assayCanEdit())return;const a=assayEnsureRecord(x);a.comment=document.getElementById('assayGeneralComment')?.value.trim()||'';a.qc=a.qc||{};a.qc.comment=a.comment;log('Save Review Comment',x.injectionId);save();renderAssay(document.getElementById('content'))}
function renderAssayAttachments(a,x){const arr=a.attachments||[];return arr.length?arr.map((f,i)=>`<div class="attachment-item"><span>▧ ${esc(f.name)}</span><small>${esc(f.type||'File')} · ${esc(f.size||'—')} · ${esc(f.date||'')}</small><span class="attachment-actions"><button class="icon-action" onclick="viewAssayAttachment(${i})">◉</button><button class="icon-action" onclick="downloadAssayAttachment(${i})">⇩</button><button class="icon-action" ${assayCanEdit()?'':'disabled'} onclick="deleteAssayAttachment(${i})">×</button></span></div>`).join(''):`<div class="attachment-empty">No attachments. Click Add File to upload evidence.</div>`}
function addAssayAttachment(){const ctx=assayContext(),x=ctx.x;if(!x||!assayCanEdit())return;const input=document.createElement('input');input.type='file';input.multiple=true;input.onchange=()=>{if(!input.files?.length)return;const a=assayEnsureRecord(x);a.attachments=a.attachments||[];let pending=input.files.length;[...input.files].forEach(f=>{const r=new FileReader();r.onload=()=>{a.attachments.push({name:f.name,type:f.type||'File',size:Math.max(1,Math.round(f.size/1024))+' KB',date:now(),data:r.result});pending--;if(pending===0){log('Upload Attachment',x.injectionId);save();renderAssay(document.getElementById('content'))}};r.readAsDataURL(f)});};input.click()}
function viewAssayAttachment(i){const a=assayEnsureRecord(assaySelected()),f=a.attachments?.[i];if(!f)return;openModal('Attachment Preview',`<div class="notice"><b>${esc(f.name)}</b><br>${esc(f.type||'File')} · ${esc(f.size||'—')}</div>${String(f.type||'').startsWith('image/')&&f.data?`<img src="${f.data}" style="max-width:100%;max-height:360px;object-fit:contain">`:f.type==='application/pdf'&&f.data?`<iframe src="${f.data}" style="width:100%;height:420px;border:0"></iframe>`:'<div class="empty">Preview is not supported for this file type.</div>'}`,'<button class="btn" onclick="closeModal()">Close</button>')}
function downloadAssayAttachment(i){const a=assayEnsureRecord(assaySelected()),f=a.attachments?.[i];if(!f)return;if(f.data){const link=document.createElement('a');link.href=f.data;link.download=f.name;link.click();log('Download Attachment',f.name)}else alert('No file data is stored for this attachment.')}
function deleteAssayAttachment(i){if(!assayCanEdit())return;const ctx=assayContext(),x=ctx.x,a=assayEnsureRecord(x);if(!confirm('Delete this attachment?'))return;a.attachments.splice(i,1);log('Delete Attachment',x.injectionId);save();renderAssay(document.getElementById('content'))}
