function toggleAssayPeaks(el){document.querySelectorAll('.assay-peak-check').forEach(x=>x.checked=el.checked)}
function ursIsAdmin(){return role()==='Admin'}
function ursIsQA(){return role()==='QA'}
function ursIsQC(){return role()==='QC'}
function ursCanEdit(){return ursIsQC()||ursIsAdmin()}
function ursInit(u){
  u.tests=Array.isArray(u.tests)?u.tests:[]; u.attachments=Array.isArray(u.attachments)?u.attachments:[]; u.comments=Array.isArray(u.comments)?u.comments:[]; u.history=Array.isArray(u.history)?u.history:[];
  u.module=u.module||'General'; u.category=u.category||'Functional Testing'; u.version=u.version||'1.0'; u.assignedTo=u.assignedTo||''; u.status=u.status==='Passed'?'Pass':(u.status==='Failed'?'Fail':(u.status||'Not Executed'));
  u.criteria=u.criteria||''; u.verification=u.verification||'Functional Testing'; u.description=u.req||'';
  u.qcReview=u.qcReview||{status:'Pending',by:'',date:'',comment:''}; u.qaReview=u.qaReview||{status:'Pending',by:'',date:'',comment:'',signature:''};
  return u;
}
function ursAll(){return (state.urs||[]).map(ursInit)}
function ursDisplayStatus(u){
  ursInit(u);
  const ts=u.tests||[];
  if(u.reviewStatus==='Pending QA Review') return 'Pending QA';
  if(u.reviewStatus==='Approved' && ts.length && ts.every(t=>t.status==='Pass')) return 'Passed';
  if(u.reviewStatus==='Revision Required') return 'Failed';
  if(!ts.length) return u.status==='Not Executed'?'Not Tested':(u.status||'Not Tested');
  if(ts.some(t=>t.status==='Fail')) return 'Failed';
  if(ts.some(t=>t.status==='Pass')) return ts.every(t=>t.status==='Pass')?'Passed':'In Progress';
  if(ts.some(t=>t.status==='Pending')) return 'In Progress';
  return 'Not Tested';
}
function ursSyncStatus(u){
  ursInit(u);
  const display=ursDisplayStatus(u);
  const internal={Passed:'Pass',Failed:'Fail',Pending:'Pending', 'Pending QA':'Pending', 'In Progress':'Pending', 'Not Tested':'Not Executed'};
  u.status=internal[display]||u.status||'Not Executed';
  return display;
}
function ursAddHistory(u,action,field='',oldValue='',newValue='',remarks=''){ursInit(u);u.history.unshift({date:now(),user:state.session?.username||'system',role:role(),action,field,oldValue,newValue,remarks});u.history=u.history.slice(0,300);log(`URS ${action}`,`${u.idn||u.id||''}${remarks?` — ${remarks}`:''}`)}
function ursSummary(arr){return {total:arr.length,pass:arr.filter(u=>ursDisplayStatus(u)==='Passed').length,fail:arr.filter(u=>ursDisplayStatus(u)==='Failed').length,pending:arr.filter(u=>ursDisplayStatus(u)==='Pending QA').length,notExecuted:arr.filter(u=>ursDisplayStatus(u)==='Not Tested').length,inProgress:arr.filter(u=>ursDisplayStatus(u)==='In Progress').length}}
function ursFilterState(){return window.__ursFilter||{q:'',module:'All Modules',category:'All Categories',status:'All Status',assigned:'All Users',tab:'All',page:1,size:10}}
function ursUsers(){const s=new Set();ursAll().forEach(u=>{if(u.assignedTo)s.add(u.assignedTo);(u.tests||[]).forEach(t=>{if(t.assignedTo)s.add(t.assignedTo)})});Object.values(USERS).forEach(x=>s.add(x.username));return [...s]}
function ursSetTab(tab){window.__ursFilter={...ursFilterState(),tab,page:1};renderURS(document.getElementById('content'))}
function ursDownloadSummary(){const all=ursAll(),rows=[['URS ID','Requirement','Category','Status','Last Updated','Review Status','Reviewed By','Review Date & Time','QA Comment','Electronic Signature'],...all.map(u=>[u.idn,u.req,u.category||u.module,ursDisplayStatus(u),u.lastUpdated||u.updatedAt||u.createdDate||'',u.reviewStatus||'Not Tested',u.qaReview?.by||'',u.qaReview?.date||'',u.qaReview?.comment||'',u.qaReview?.signature||''])];const csv=rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`URS_Summary_${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);log('URS Download Summary',`${all.length} requirement(s)`)}
function ursSelect(id){window.__ursSelected=id;renderURS(document.getElementById('content'))}
function ursInlineStatusClass(status){return ({'Not Tested':'not-tested','In Progress':'in-progress','Passed':'passed','Failed':'failed','Pending QA':'pending-qa'}[status]||'not-tested')}
function ursInlineBadge(status){return `<span class="urs-inline-badge ${ursInlineStatusClass(status)}">${esc(status)}</span>`}
function ursCategoryClass(v){const x=String(v||'').toLowerCase();if(x.includes('security'))return 'security';if(x.includes('instrument'))return 'instrument';if(x.includes('data'))return 'data';return 'default'}
function ursRenderDetail(u){
  if(!u)return `<div class="urs-detail-empty">Select a URS requirement to view its details.</div>`;
  const status=ursDisplayStatus(u), tests=u.tests||[], reviewed=u.qaReview||{};
  const created=u.createdDate||u.createdAt||u.created||u.lastUpdated||u.updatedAt||'—';
  const reviewStatus=u.reviewStatus||status;
  return `<div class="urs-detail-card">
    <div class="urs-detail-top"><div><h2>${esc(u.idn)}</h2><p>${esc(u.req)}</p></div>${ursInlineBadge(status)}</div>
    <div class="urs-detail-meta">
      <div><span>Category</span><b>${esc(u.module||u.category||'General')}</b></div>
      <div><span>Priority</span><b>${esc(u.risk||'—')}</b></div>
      <div><span>Version</span><b>${esc(u.version||'1.0')}</b></div>
      <div><span>Created Date</span><b>${esc(created)}</b></div>
    </div>
    <div class="urs-detail-section"><h3>Acceptance Criteria</h3><div class="urs-detail-box">${esc(u.criteria||'—')}</div></div>
    <div class="urs-detail-section"><h3>Verification Method</h3><div class="urs-detail-box">${esc(u.verification||'Functional Testing')}</div></div>
    <div class="urs-detail-actions">
      <button class="btn" onclick="ursEdit('${u.id}')">Edit</button>
      <button class="btn danger" onclick="ursDelete('${u.id}')">Delete</button>
      <button class="btn primary" onclick="ursOpenAddTest('${u.id}')">Test</button>
    </div>
    <div class="urs-review-section">
      <h3>Review</h3>
      <div class="urs-review-row"><span>Review Status</span><b>${esc(reviewStatus)}</b></div>
      <div class="urs-review-row"><span>Reviewed by</span><b>${esc(reviewed.by||'—')}</b></div>
      <div class="urs-review-row"><span>Review Date &amp; Time</span><b>${esc(reviewed.date||'—')}</b></div>
      <div class="urs-review-row"><span>QA Comment</span><b>${esc(reviewed.comment||'—')}</b></div>
      <div class="urs-review-row"><span>Electronic Signature</span><b>${esc(reviewed.signature||'—')}</b></div>
    </div>
  </div>`;
}
function renderURS(c){
  const fs=ursFilterState(), all=ursAll();
  const statusTab=fs.tab||'All';
  let arr=all.filter(u=>(!fs.q||`${u.idn} ${u.req}`.toLowerCase().includes(fs.q.toLowerCase()))&&(fs.module==='All Modules'||u.module===fs.module)&&(fs.category==='All Categories'||u.category===fs.category)&&(fs.status==='All Status'||ursDisplayStatus(u)===({'Pass':'Passed','Fail':'Failed','Pending':'Pending QA','Not Executed':'Not Tested'}[fs.status]||fs.status))&&(fs.assigned==='All Users'||u.assignedTo===fs.assigned)&&(statusTab==='All'||ursDisplayStatus(u)===statusTab));
  const sum=ursSummary(all),pages=Math.max(1,Math.ceil(arr.length/fs.size));fs.page=Math.min(fs.page,pages);window.__ursFilter=fs;
  const from=arr.length?(fs.page-1)*fs.size+1:0,to=Math.min(fs.page*fs.size,arr.length),rows=arr.slice((fs.page-1)*fs.size,fs.page*fs.size);
  let selectedId=window.__ursSelected;
  if(!selectedId||!arr.some(u=>u.id===selectedId)) selectedId=rows[0]?.id||arr[0]?.id||null;
  window.__ursSelected=selectedId;
  const selected=all.find(u=>u.id===selectedId)||null;
  const tabs=[['All',sum.total],['Not Tested',sum.notExecuted],['In Progress',sum.inProgress],['Passed',sum.pass],['Failed',sum.fail],['Pending QA',sum.pending]];
  c.innerHTML=`<div class="urs-page urs-reference-page">
    <div class="title-row urs-standard-header"><div class="title"><div class="eyebrow">COMPUTERIZED SYSTEM VALIDATION</div><h1>User Requirement Specification (URS)</h1><p class="subtitle">Define and verify critical HPLC-UV system requirements.</p></div></div>
    <div class="urs-control-shell">
      <div class="urs-control-top"><div class="urs-status-tabs">${tabs.map(([name,count])=>`<button class="urs-status-tab ${statusTab===name?'active':''}" onclick="ursSetTab('${name}')">${name} (${count})</button>`).join('')}</div><div class="urs-top-actions"><button class="urs-download-btn" onclick="ursDownloadSummary()"><span class="urs-svg">⇩</span> Download URS Summary</button><button class="urs-add-btn" onclick="ursOpenAdd()">＋ Add URS</button></div></div>
      <div class="urs-search-row"><div class="urs-search-box"><span class="urs-search-icon">⌕</span><input id="ursQ" value="${esc(fs.q)}" placeholder="Search URS ID, requirement, or keyword..." onkeydown="if(event.key==='Enter')ursQuickFilter()"></div><select id="ursCategory" class="urs-ref-select" onchange="ursQuickFilter()"><option>All Categories</option>${['Security','Instrument','Data Integrity','Audit Trail','Analytical Method','Sequence','Chromatogram','Assay / Data Review','Approval','Validation Report','General'].map(x=>`<option ${fs.category===x?'selected':''}>${x}</option>`).join('')}</select><select id="ursStatus" class="urs-ref-select" onchange="ursQuickFilter()"><option>All Status</option>${['Not Tested','In Progress','Passed','Failed','Pending QA'].map(x=>`<option ${fs.status===x?'selected':''}>${x}</option>`).join('')}</select><button class="urs-reset-btn" onclick="ursResetFilters()">Reset</button></div>
    </div>
    <div class="urs-reference-grid">
      <div class="urs-reference-list">
        <div class="urs-ref-table-wrap"><table class="urs-ref-table"><thead><tr><th class="check-col"><input type="checkbox" onchange="ursToggleAll(this)"></th><th>ID</th><th>REQUIREMENT</th><th>CATEGORY</th><th>STATUS</th><th>LAST UPDATED</th><th class="dots-col"></th></tr></thead><tbody>${rows.length?rows.map(u=>{const ds=ursDisplayStatus(u),sel=u.id===selectedId;return `<tr class="${sel?'selected':''}" onclick="ursSelect('${u.id}')"><td class="check-col" onclick="event.stopPropagation()"><input type="checkbox" class="urs-row-check" value="${esc(u.id)}"></td><td><button class="urs-id-link" onclick="event.stopPropagation();ursSelect('${u.id}')">${esc(u.idn)}</button></td><td class="urs-requirement-cell" title="${esc(u.req)}">${esc(u.req)}</td><td><span class="urs-category-pill ${ursCategoryClass(u.module)}">${esc(u.module||u.category||'General')}</span></td><td>${ursInlineBadge(ds)}</td><td>${esc(u.lastUpdated||u.updatedAt||'—')}</td><td class="dots-col"><button class="urs-dots" title="Actions" onclick="event.stopPropagation();ursMore('${u.id}',event)">⋮</button></td></tr>`}).join(''):`<tr><td colspan="7"><div class="urs-ref-empty">No URS data matches the current filters.</div></td></tr>`}</tbody></table></div>
        <div class="urs-ref-pagination"><span>Showing ${from}–${to} of ${arr.length} requirements</span><div class="urs-page-controls"><button class="urs-page-btn" ${fs.page<=1?'disabled':''} onclick="ursPage(${fs.page-1})">‹</button>${Array.from({length:pages},(_,i)=>i+1).slice(Math.max(0,fs.page-3),Math.min(pages,fs.page+2)).map(i=>`<button class="urs-page-btn ${i===fs.page?'active':''}" onclick="ursPage(${i})">${i}</button>`).join('')}<button class="urs-page-btn" ${fs.page>=pages?'disabled':''} onclick="ursPage(${fs.page+1})">›</button></div></div>
      </div>
      <aside class="urs-reference-detail">${ursRenderDetail(selected)}</aside>
    </div>
  </div>`;
}
function ursQuickFilter(){const prev=ursFilterState();window.__ursFilter={...prev,q:document.getElementById('ursQ')?.value.trim()||'',category:document.getElementById('ursCategory')?.value||'All Categories',status:document.getElementById('ursStatus')?.value||'All Status',page:1};renderURS(document.getElementById('content'))}
function ursApplyFilters(){const prev=ursFilterState();window.__ursFilter={q:document.getElementById('ursQ')?.value.trim()||'',module:prev.module||'All Modules',category:document.getElementById('ursCategory')?.value||'All Categories',status:document.getElementById('ursStatus')?.value||'All Status',assigned:prev.assigned||'All Users',tab:prev.tab||'All',page:1,size:10};log('URS Search','Filter applied');renderURS(document.getElementById('content'))}
function ursResetFilters(){window.__ursFilter={q:'',module:'All Modules',category:'All Categories',status:'All Status',assigned:'All Users',tab:'All',page:1,size:10};log('URS Reset','Filters reset');renderURS(document.getElementById('content'))}
function ursPage(p){window.__ursFilter=ursFilterState();window.__ursFilter.page=p;renderURS(document.getElementById('content'))}
function ursToggleAll(el){document.querySelectorAll('.urs-row-check').forEach(x=>x.checked=el.checked)}
function ursNextId(){const nums=ursAll().map(u=>parseInt(String(u.idn||'').replace(/\D/g,''),10)).filter(Number.isFinite);return `URS-${String((nums.length?Math.max(...nums):0)+1).padStart(3,'0')}`}
function ursOpenAdd(){if(!ursIsQC()&&!ursIsAdmin()){alert('Only QC or Admin can add URS.');return}openModal('Add User Requirement Specification',`<div class="urs-add-urs-form"><div class="urs-add-urs-field"><label>URS ID</label><input id="u2_id" class="input urs-add-urs-input" value="${esc(ursNextId())}"></div><div class="urs-add-urs-field"><label>Requirement <span>*</span></label><textarea id="u2_req" class="textarea urs-add-urs-textarea" placeholder="Enter the user requirement..."></textarea></div><div class="urs-add-urs-field"><label>Acceptance Criteria <span>*</span></label><textarea id="u2_criteria" class="textarea urs-add-urs-textarea" placeholder="Enter the acceptance criteria..."></textarea></div><div class="urs-add-urs-hidden"><input id="u2_risk" value="High"><input id="u2_module" value="General"><input id="u2_version" value="1.0"><input id="u2_cat" value="Functional Testing"><input id="u2_ver" value="Functional Testing"></div></div>`,`<button class="btn urs-add-urs-cancel" onclick="closeModal()">Cancel</button><button class="btn primary urs-add-urs-save" onclick="ursSaveNew()">Save URS</button>`)}
function ursSaveNew(){const idn=document.getElementById('u2_id').value.trim(),req=document.getElementById('u2_req').value.trim();if(!idn||!req){alert('Requirement ID and Requirement Description are required.');return}if(ursAll().some(u=>u.idn===idn)){alert('URS ID already exists.');return}const u=ursInit({id:uid('URS'),idn,req,description:req,risk:document.getElementById('u2_risk').value,module:document.getElementById('u2_module').value,category:document.getElementById('u2_cat').value,version:document.getElementById('u2_version').value.trim(),criteria:document.getElementById('u2_criteria').value.trim(),verification:document.getElementById('u2_ver').value,status:'Not Executed',assignedTo:'',tests:[],attachments:[],comments:[],history:[]});state.urs.push(u);ursAddHistory(u,'Create');save();closeModal();renderURS(document.getElementById('content'));alert('URS saved successfully.')}
function ursEdit(id){
  if(!ursCanEdit()){alert('Only QC or Admin can edit URS.');return}
  const u=ursAll().find(x=>x.id===id);
  if(!u)return;
  openModal(`Edit ${esc(u.idn)}`,
    `<div class="urs-reference-edit-modal">
      <div class="urs-reference-edit-field">
        <label>URS ID</label>
        <input id="ue_id" class="input" value="${esc(u.idn)}">
      </div>
      <div class="urs-reference-edit-field">
        <label>Requirement <span>*</span></label>
        <textarea id="ue_req" class="textarea">${esc(u.req)}</textarea>
      </div>
      <div class="urs-reference-edit-field">
        <label>Acceptance Criteria <span>*</span></label>
        <textarea id="ue_criteria" class="textarea">${esc(u.criteria||'')}</textarea>
      </div>
    </div>`,
    `<button class="btn urs-reference-edit-cancel" onclick="closeModal()">Cancel</button><button class="btn primary urs-reference-edit-save" onclick="ursSaveEdit('${id}')">Save Changes</button>`
  );
  document.getElementById('modal')?.classList.add('urs-reference-edit-open');
}
function ursSaveEdit(id){
  const u=ursAll().find(x=>x.id===id);
  if(!u||!ursCanEdit()){alert('Only QC or Admin can edit URS.');return}
  const idn=document.getElementById('ue_id').value.trim();
  const req=document.getElementById('ue_req').value.trim();
  const criteria=document.getElementById('ue_criteria').value.trim();
  if(!idn||!req||!criteria){alert('URS ID, Requirement, and Acceptance Criteria are required.');return}
  if(ursAll().some(x=>x.id!==id&&x.idn===idn)){alert('URS ID already exists.');return}
  const old={idn:u.idn,req:u.req,criteria:u.criteria};
  u.idn=idn;
  u.req=req;
  u.description=req;
  u.criteria=criteria;
  u.lastUpdated=now();
  ursAddHistory(u,'Edit','URS Details',JSON.stringify(old),JSON.stringify({idn,req,criteria}),'URS details updated');
  save();
  closeModal();
  renderURS(document.getElementById('content'));
}
function ursOpenAddTest(prefillId=''){
  if(!ursIsQC()&&!ursIsAdmin()){alert('Only QC or Admin can add Test.');return}
  const us=ursAll();
  if(!us.length){alert('Create a URS first.');return}
  const selected=us.find(u=>u.id===prefillId)||us[0];
  const nextTest='TST-'+String(us.reduce((m,u)=>Math.max(m,...(u.tests||[]).map(t=>parseInt(String(t.testId||'').replace(/\D/g,''),10)||0)),0)+1).padStart(3,'0');
  window.__ursNewTestFile=null;
  const existingAttachments=(selected.attachments||[]);
  const attachmentOptions=['<option value="">No attachment</option>',...existingAttachments.map((f,i)=>`<option value="${esc(String(i))}">${esc(f.name)}</option>`)].join('');
  openModal(`${esc(selected.idn)} — URS Test`,
    `<div class="urs-test-reference-form">
      <input id="ut_id" type="hidden" value="${esc(nextTest)}">
      <input id="ut_urs" type="hidden" value="${esc(selected.id)}">
      <div class="urs-test-reference-field">
        <label>URS ID</label>
        <input class="input urs-test-reference-input" value="${esc(selected.idn)}" readonly>
      </div>
      <div class="urs-test-reference-field">
        <label>Requirement</label>
        <textarea class="textarea urs-test-reference-textarea" readonly>${esc(selected.req||'')}</textarea>
      </div>
      <div class="urs-test-reference-field">
        <label>Acceptance Criteria</label>
        <textarea class="textarea urs-test-reference-textarea" readonly>${esc(selected.criteria||'')}</textarea>
      </div>
      <div class="urs-test-reference-field">
        <label>Actual Result <span>*</span></label>
        <textarea id="ut_actual" class="textarea urs-test-reference-textarea actual" maxlength="500" placeholder="Enter the observed actual result..."></textarea>
      </div>
      <div class="urs-test-reference-field">
        <label>Supporting Evidence</label>
        <select id="ut_attachment" class="select urs-test-reference-input">${attachmentOptions}</select>
      </div>
      <div class="urs-test-reference-field">
        <label>Upload New Evidence</label>
        <input id="ut_file" class="urs-test-reference-file" type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,.png,.jpg,.jpeg">
      </div>
      <div class="urs-test-reference-field">
        <label>Test Result <span>*</span></label>
        <select id="ut_result" class="select urs-test-reference-input">
          <option value="">Select result</option>
          <option value="Pass">Pass</option>
          <option value="Fail">Fail</option>
        </select>
        <div class="urs-test-reference-help">QC must explicitly select the observed test result. The system will save the selection exactly as entered.</div>
      </div>
      <div class="urs-test-reference-hidden">
        <input id="ut_cat" value="Functional Testing">
        <input id="ut_risk" value="Medium">
        <input id="ut_ver" value="Functional Testing">
        <input id="ut_assigned" value="">
      </div>
    </div>`,
    `<button class="btn urs-test-reference-cancel" onclick="closeModal()">Cancel</button><button class="btn primary urs-test-reference-confirm" onclick="ursConfirmNewTest()">Confirm Test</button>`
  );
  setTimeout(()=>{
    const fi=document.getElementById('ut_file');
    fi?.addEventListener('change',()=>{window.__ursNewTestFile=fi.files?.[0]||null});
  },0);
}
function ursConfirmNewTest(){
  if(!ursIsQC()&&!ursIsAdmin()){alert('Only QC or Admin can confirm a Test.');return}
  const tid=document.getElementById('ut_id')?.value.trim(),uid2=document.getElementById('ut_urs')?.value,us=ursAll(),u=us.find(x=>x.id===uid2);
  const actual=document.getElementById('ut_actual')?.value.trim()||'',result=document.getElementById('ut_result')?.value||'';
  if(!u||!tid||!actual||!result){alert('Actual Result and Test Result are required.');return}
  if(us.some(x=>(x.tests||[]).some(t=>t.testId===tid))){alert('Test ID already exists.');return}
  const selectedIndex=document.getElementById('ut_attachment')?.value||'';
  const createTest=(evidence)=>{
    const t={id:uid('TST'),testId:tid,category:document.getElementById('ut_cat')?.value||'Functional Testing',description:u.req||'',expectedResult:u.criteria||'',verificationMethod:document.getElementById('ut_ver')?.value||u.verification||'Functional Testing',assignedTo:document.getElementById('ut_assigned')?.value||'',risk:document.getElementById('ut_risk')?.value||'Medium',status:result,actualResult:actual,executedBy:state.session.username,executionDate:now(),evidence:evidence||[]};
    u.tests=u.tests||[];u.tests.push(t);ursSyncStatus(u);ursAddHistory(u,'Create Test','Test Result','',result,`${tid} test executed`);save();closeModal();ursView(u.id,'execution');
  };
  const evidence=[];
  if(selectedIndex!=='' && u.attachments?.[Number(selectedIndex)]){
    const f=u.attachments[Number(selectedIndex)];evidence.push({id:uid('EV'),name:f.name,size:f.size,type:f.type||'File',date:now(),uploadedBy:state.session.username,data:f.data||null,sourceAttachmentId:f.id});
  }
  const f=window.__ursNewTestFile;
  if(!f){createTest(evidence);return}
  if(f.size>10*1024*1024){alert('Maximum file size is 10 MB.');return}
  const r=new FileReader();
  r.onload=()=>{evidence.push({id:uid('EV'),name:f.name,size:Math.max(1,Math.round(f.size/1024))+' KB',type:f.type||'File',date:now(),uploadedBy:state.session.username,data:r.result});createTest(evidence)};
  r.readAsDataURL(f);
}
function ursMore(id,e){e?.stopPropagation();const u=ursAll().find(x=>x.id===id);if(!u)return;openModal('URS Actions',`<div class="urs-more-menu"><button onclick="closeModal();ursView('${id}')">View</button><button onclick="closeModal();ursEdit('${id}')">Edit</button><button onclick="closeModal();ursDuplicate('${id}')">Duplicate</button><button onclick="closeModal();ursDelete('${id}')">Delete</button><button onclick="closeModal();ursExecutePick('${id}')">Execute Test</button><button onclick="closeModal();ursViewHistory('${id}')">View History</button></div>`,'<button class="btn" onclick="closeModal()">Close</button>')}
function ursDuplicate(id){if(!ursIsAdmin()){alert('Only Admin can duplicate URS.');return}const src=ursAll().find(x=>x.id===id);if(!src)return;const copy=ursInit(JSON.parse(JSON.stringify(src)));copy.id=uid('URS');copy.idn=ursNextId();copy.tests=[];copy.attachments=[];copy.comments=[];copy.history=[];copy.status='Not Executed';state.urs.push(copy);ursAddHistory(copy,'Duplicate');save();renderURS(document.getElementById('content'))}
function ursDelete(id){if(!ursIsAdmin()){alert('Only Admin can delete URS.');return}const u=ursAll().find(x=>x.id===id);if(!u||!confirm(`Delete ${u.idn}?`))return;state.urs=state.urs.filter(x=>x.id!==id);log('URS Delete',u.idn);save();renderURS(document.getElementById('content'))}
function ursView(id,tab='execution'){const u=ursAll().find(x=>x.id===id);if(!u)return;ursSyncStatus(u);const tests=u.tests||[],selected=tests[0];openModal(`${esc(u.idn)} — URS Details`,`<div class="urs-details-head"><div><div class="eyebrow">URS DETAILS</div><h3>${esc(u.req)}</h3></div><div><button class="btn" onclick="ursEdit('${id}')">Edit</button>${ursIsQA()&&u.reviewStatus==='Pending QA Review'?`<button class="btn primary" onclick="ursQAReview('${id}')">QA Review</button>`:''}</div></div><div class="urs-detail-grid">${[['URS ID',u.idn],['Requirement',u.req],['Module',u.module],['Test ID',tests.map(t=>t.testId).join(', ')||'—'],['Risk Level',u.risk],['Acceptance Criteria',u.criteria||'—'],['Verification Method',u.verification||'—'],['Status',ursSyncStatus(u)],['Assigned To',u.assignedTo||'—'],['Version',u.version||'—']].map(x=>`<div><span>${x[0]}</span><b>${esc(x[1])}</b></div>`).join('')}</div><div class="urs-tabs"><button class="${tab==='execution'?'active':''}" onclick="ursView('${id}','execution')">Test Execution</button><button class="${tab==='attachments'?'active':''}" onclick="ursView('${id}','attachments')">Attachments (${u.attachments.length})</button><button class="${tab==='comments'?'active':''}" onclick="ursView('${id}','comments')">Comments (${u.comments.length})</button><button class="${tab==='history'?'active':''}" onclick="ursView('${id}','history')">History</button></div>${tab==='execution'?ursExecutionView(u,selected):tab==='attachments'?ursAttachmentsView(u):tab==='comments'?ursCommentsView(u):ursHistoryView(u)}`,'<button class="btn" onclick="closeModal()">Close</button>')}
function ursExecutionView(u,selected){return `<div class="urs-execution-layout"><div><div class="panel inset"><div class="panel-head"><h4>Test Execution</h4><button class="btn" onclick="ursOpenAddTest('${u.id}')">＋ Add Test</button></div>${u.tests.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Select</th><th>Test ID</th><th>Category</th><th>Status</th><th>Assigned To</th><th>Action</th></tr></thead><tbody>${u.tests.map(t=>`<tr><td><input type="radio" name="ursTestPick" ${selected?.id===t.id?'checked':''} onchange="ursSelectTest('${u.id}','${t.id}')"></td><td>${esc(t.testId)}</td><td>${esc(t.category)}</td><td>${badge(t.status)}</td><td>${esc(t.assignedTo||'—')}</td><td><button class="icon-action" onclick="ursExecuteTest('${u.id}','${t.id}')">▶</button> <button class="icon-action" onclick="ursEditTest('${u.id}','${t.id}')">✎</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No tests linked to this URS.</div>'}</div>${selected?ursTestPanel(u,selected):''}</div><div><div class="panel inset"><h4>Expected Result</h4><div class="notice">${esc(selected?.expectedResult||'Select a test to view its Expected Result.')}</div></div><div class="panel inset"><div class="panel-head"><h4>Test Evidence</h4><button class="btn" ${ursIsQC()?'':'disabled'} onclick="ursAddEvidence('${u.id}','${selected?.id||''}')">＋ Add File</button></div>${selected?ursEvidenceList(selected):'<div class="empty">Select a test.</div>'}</div></div></div>`}
function ursTestPanel(u,t){return `<div class="urs-test-form panel inset"><div class="formgrid"><div class="field full"><label>Actual Result * <span class="char-count" id="ursCharCount">${(t.actualResult||'').length}/500</span></label><textarea id="ursActual_${t.id}" class="textarea" maxlength="500" oninput="document.getElementById('ursCharCount').textContent=this.value.length+'/500'">${esc(t.actualResult||'')}</textarea></div><div class="field"><label>Test Status *</label><select id="ursTestStatus_${t.id}" class="select">${['Not Executed','Pending','Pass','Fail'].map(x=>`<option ${t.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Executed By</label><input class="input" value="${esc(t.executedBy||state.session?.username||'')}" disabled></div><div class="field"><label>Execution Date</label><input class="input" value="${esc(t.executionDate||'')}" disabled></div></div><div class="urs-exec-buttons"><button class="btn" ${ursIsQC()?'':'disabled'} onclick="ursSaveResult('${u.id}','${t.id}')">Save Result</button><button class="btn primary" ${ursIsQC()?'':'disabled'} onclick="ursSubmitQA('${u.id}','${t.id}')">Submit to QA</button></div></div>`}
function ursSelectTest(id,tid){window.__ursSelectedTest=tid;ursView(id,'execution')}
function ursExecutePick(id){const u=ursAll().find(x=>x.id===id);if(!u||!u.tests.length){alert('No test is linked to this URS.');return}ursExecuteTest(u.id,u.tests[0].id)}
function ursExecuteTest(uid2,tid){const u=ursAll().find(x=>x.id===uid2),t=u?.tests.find(x=>x.id===tid);if(!u||!t)return;if(!ursIsQC()){alert('Only QC can execute tests.');return}ursView(uid2,'execution');setTimeout(()=>{const ta=document.getElementById(`ursActual_${tid}`);ta?.focus()},50)}
function ursSaveResult(uid2,tid){const u=ursAll().find(x=>x.id===uid2),t=u?.tests.find(x=>x.id===tid);if(!u||!t||!ursIsQC())return;const actual=document.getElementById(`ursActual_${tid}`)?.value.trim()||'',st=document.getElementById(`ursTestStatus_${tid}`)?.value||'Not Executed';if(!actual){alert('Actual Result is required.');return}const old=t.status;t.actualResult=actual;t.status=st;t.executedBy=state.session.username;t.executionDate=now();ursSyncStatus(u);ursAddHistory(u,'Update Result','Test Status',old,st,`${t.testId} execution saved`);save();ursView(uid2,'execution')}
function ursSubmitQA(uid2,tid){const u=ursAll().find(x=>x.id===uid2),t=u?.tests.find(x=>x.id===tid);if(!u||!t||!ursIsQC())return;if(!t.actualResult||t.status==='Not Executed'){alert('Actual Result and Test Status are required before submitting to QA.');return}ursSyncStatus(u);u.submittedBy=state.session.username;u.submittedDate=now();u.reviewStatus='Pending QA Review';ursAddHistory(u,'Submit to QA','Review Status','','Pending QA Review','QC submitted analytical result for QA review');save();alert('Data submitted for QA review.');ursView(uid2,'execution')}
function ursAddEvidence(uid2,tid){const u=ursAll().find(x=>x.id===uid2),t=u?.tests.find(x=>x.id===tid);if(!u||!t||!ursIsQC())return;const input=document.createElement('input');input.type='file';input.accept='.pdf,.doc,.docx,.xls,.xlsx,.png,.jpg,.jpeg';input.onchange=()=>{const f=input.files?.[0];if(!f)return;if(f.size>10*1024*1024){alert('Maximum file size is 10 MB.');return}const r=new FileReader();r.onload=()=>{t.evidence=t.evidence||[];t.evidence.push({id:uid('EV'),name:f.name,size:Math.max(1,Math.round(f.size/1024))+' KB',type:f.type||'File',date:now(),uploadedBy:state.session.username,data:r.result});ursAddHistory(u,'Upload Evidence','File','',f.name,'Test evidence uploaded');save();ursView(uid2,'execution')};r.readAsDataURL(f)};input.click()}
function ursEvidenceList(t){const a=t.evidence||[];return a.length?`<div class="urs-evidence-list">${a.map((f,i)=>`<div><span>▧ ${esc(f.name)}</span><small>${esc(f.size)} • ${esc(f.date)}</small><span><button class="icon-action" onclick="ursPreviewEvidence('${t.id}',${i})">◉</button><button class="icon-action" onclick="ursDownloadEvidence('${t.id}',${i})">⇩</button><button class="icon-action" ${ursIsQC()?'':'disabled'} onclick="ursDeleteEvidence('${t.id}',${i})">×</button></span></div>`).join('')}</div>`:'<div class="empty">No evidence uploaded.</div>'}
function ursFindTest(tid){for(const u of ursAll()){const t=(u.tests||[]).find(x=>x.id===tid);if(t)return [u,t]}return [null,null]}
function ursPreviewEvidence(tid,i){const [u,t]=ursFindTest(tid),f=t?.evidence?.[i];if(!f)return;openModal('Test Evidence Preview',`<div class="notice"><b>${esc(f.name)}</b><br>${esc(f.type)} · ${esc(f.size)}</div>${String(f.type).startsWith('image/')&&f.data?`<img src="${f.data}" style="max-width:100%;max-height:420px;object-fit:contain">`:f.type==='application/pdf'&&f.data?`<iframe src="${f.data}" style="width:100%;height:420px;border:0"></iframe>`:'<div class="empty">Preview is not supported for this file type.</div>'}`,'<button class="btn" onclick="closeModal()">Close</button>')}
function ursDownloadEvidence(tid,i){const [,t]=ursFindTest(tid),f=t?.evidence?.[i];if(!f)return;const a=document.createElement('a');a.href=f.data;a.download=f.name;a.click()}
function ursDeleteEvidence(tid,i){const [u,t]=ursFindTest(tid);if(!u||!t||!ursIsQC()||!confirm('Delete this evidence?'))return;const f=t.evidence.splice(i,1)[0];ursAddHistory(u,'Delete Evidence','File',f?.name||'','',`${t.testId} evidence deleted`);save();ursView(u.id,'execution')}
function ursAttachmentsView(u){return `<div class="urs-attachment-tab"><div class="panel inset"><div class="panel-head"><h4>Attachments</h4><button class="btn" ${ursIsQC()||ursIsAdmin()?'':'disabled'} onclick="ursAddGeneralAttachment('${u.id}')">＋ Add File</button></div>${u.attachments.length?`<table class="table"><thead><tr><th>No.</th><th>File Name</th><th>Type</th><th>Size</th><th>Uploaded By</th><th>Date Uploaded</th><th>Description</th><th>Actions</th></tr></thead><tbody>${u.attachments.map((f,i)=>`<tr><td>${i+1}</td><td>${esc(f.name)}</td><td>${esc(f.type)}</td><td>${esc(f.size)}</td><td>${esc(f.uploadedBy)}</td><td>${esc(f.date)}</td><td>${esc(f.description||'')}</td><td><button class="icon-action" onclick="ursPreviewGeneralAttachment('${u.id}',${i})">◉</button><button class="icon-action" onclick="ursDownloadGeneralAttachment('${u.id}',${i})">⇩</button><button class="icon-action" ${ursIsQC()||ursIsAdmin()?'':'disabled'} onclick="ursDeleteGeneralAttachment('${u.id}',${i})">×</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No attachments available.</div>'}</div></div>`}
function ursAddGeneralAttachment(id){const u=ursAll().find(x=>x.id===id);if(!u||(ursIsQA()&&!ursIsAdmin()))return;const input=document.createElement('input');input.type='file';input.onchange=()=>{const f=input.files?.[0];if(!f)return;if(f.size>10*1024*1024){alert('Maximum file size is 10 MB.');return}const r=new FileReader();r.onload=()=>{u.attachments.push({id:uid('ATT'),name:f.name,type:f.type||'File',size:Math.max(1,Math.round(f.size/1024))+' KB',uploadedBy:state.session.username,date:now(),description:'Supporting document',data:r.result});ursAddHistory(u,'Upload File','Attachment','',f.name,'Attachment uploaded');save();ursView(id,'attachments')};r.readAsDataURL(f)};input.click()}
function ursPreviewGeneralAttachment(id,i){const u=ursAll().find(x=>x.id===id),f=u?.attachments?.[i];if(!f)return;openModal('Attachment Preview',`<div class="notice"><b>${esc(f.name)}</b><br>${esc(f.type)} · ${esc(f.size)}</div>${String(f.type).startsWith('image/')&&f.data?`<img src="${f.data}" style="max-width:100%;max-height:420px">`:f.type==='application/pdf'&&f.data?`<iframe src="${f.data}" style="width:100%;height:420px;border:0"></iframe>`:'<div class="empty">Preview is not supported for this file type.</div>'}`,'<button class="btn" onclick="closeModal()">Close</button>')}
function ursDownloadGeneralAttachment(id,i){const u=ursAll().find(x=>x.id===id),f=u?.attachments?.[i];if(!f)return;const a=document.createElement('a');a.href=f.data;a.download=f.name;a.click()}
function ursDeleteGeneralAttachment(id,i){const u=ursAll().find(x=>x.id===id);if(!u||(ursIsQA()&&!ursIsAdmin())||!confirm('Delete this attachment?'))return;const f=u.attachments.splice(i,1)[0];ursAddHistory(u,'Delete File','Attachment',f?.name||'','',`Attachment deleted`);save();ursView(id,'attachments')}
function ursCommentsView(u){return `<div class="urs-comments-layout"><div class="panel inset"><div class="urs-comment-thread">${u.comments.length?u.comments.map((m,i)=>`<div class="urs-comment"><div class="avatar">${esc((m.user||'U')[0].toUpperCase())}</div><div><b>${esc(m.user)}</b><small>${esc(m.role)} • ${esc(m.date)}</small><p>${esc(m.text)}</p></div><button class="icon-action" onclick="ursCommentMore('${u.id}',${i})">⋮</button></div>`).join(''):'<div class="empty">No comments yet.</div>'}</div><div class="field" style="margin-top:10px"><label>Write a comment...</label><textarea id="ursCommentText" class="textarea" placeholder="Write a comment..."></textarea></div><div class="urs-comment-actions"><button class="btn" onclick="ursAttachComment('${u.id}')">Attach</button><button class="btn primary" onclick="ursPostComment('${u.id}')">Post Comment</button></div></div><div class="panel inset"><h4>Comment Information</h4><div class="urs-comment-info">${[['Total Comments',u.comments.length],['Created By',u.createdBy||'—'],['Created Date',u.createdDate||'—'],['Last Updated',u.comments[0]?.date||u.createdDate||'—']].map(x=>`<div><span>${x[0]}</span><b>${esc(x[1])}</b></div>`).join('')}</div><div class="field"><label>Filter Comments</label><select class="select" id="ursCommentUser"><option>All Users</option>${[...new Set(u.comments.map(x=>x.user))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><select class="select" id="ursCommentDate"><option>All Dates</option><option>Today</option></select></div><button class="btn" onclick="ursFilterComments('${u.id}')">Reset</button></div></div>`}
function ursPostComment(id){const u=ursAll().find(x=>x.id===id),text2=document.getElementById('ursCommentText')?.value.trim();if(!u||!text2){alert('Comment cannot be empty.');return}u.comments.unshift({id:uid('COM'),user:state.session.username,role:role(),date:now(),text:text2,attachment:null});u.createdBy=u.createdBy||state.session.username;u.createdDate=u.createdDate||now();ursAddHistory(u,'Add Comment','Comment','','',text2.slice(0,80));save();ursView(id,'comments')}
function ursCommentMore(id,i){const u=ursAll().find(x=>x.id===id),m=u?.comments?.[i];if(!m)return;openModal('Comment',`<div class="notice"><b>${esc(m.user)}</b> · ${esc(m.role)}<br>${esc(m.date)}<hr>${esc(m.text)}</div>`,'<button class="btn" onclick="closeModal()">Close</button>')}
function ursAttachComment(){alert('Comment attachment can be added from the Evidence/Attachments sections.');}
function ursFilterComments(id){ursView(id,'comments')}
function ursHistoryView(u){return `<div class="panel inset"><div class="urs-history-meta">${[['URS ID',u.idn],['Module',u.module],['Test ID',(u.tests||[]).map(t=>t.testId).join(', ')||'—'],['Current Status',ursSyncStatus(u)],['Assigned To',u.assignedTo||'—']].map(x=>`<div><span>${x[0]}</span><b>${esc(x[1])}</b></div>`).join('')}</div><table class="table"><thead><tr><th>Date/Time</th><th>User</th><th>Role</th><th>Action</th><th>Field</th><th>Old Value</th><th>New Value</th><th>Remarks</th></tr></thead><tbody>${u.history.length?u.history.map(h=>`<tr><td>${esc(h.date)}</td><td>${esc(h.user)}</td><td>${esc(h.role)}</td><td>${esc(h.action)}</td><td>${esc(h.field||'—')}</td><td class="ellipsis">${esc(h.oldValue||'—')}</td><td class="ellipsis">${esc(h.newValue||'—')}</td><td>${esc(h.remarks||'—')}</td></tr>`).join(''):'<tr><td colspan="8">No history.</td></tr>'}</tbody></table></div>`}
function ursViewHistory(id){ursView(id,'history')}
function ursEditTest(uid2,tid){const u=ursAll().find(x=>x.id===uid2),t=u?.tests.find(x=>x.id===tid);if(!u||!t)return;if(!ursIsAdmin()&&!ursIsQC()){alert('Only QC or Admin can edit test data.');return}openModal('Edit Test',`<div class="formgrid"><div class="field"><label>Test ID *</label><input id="uet_id" class="input" value="${esc(t.testId)}"></div><div class="field"><label>Category</label><select id="uet_cat" class="select">${['Functional Testing','Workflow Testing','Security Testing','Data Integrity Testing','Calculation Testing','Integration Testing','Other'].map(x=>`<option ${t.category===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Test Description *</label><textarea id="uet_desc" class="textarea">${esc(t.description||'')}</textarea></div><div class="field full"><label>Expected Result *</label><textarea id="uet_expected" class="textarea">${esc(t.expectedResult||'')}</textarea></div><div class="field"><label>Verification Method</label><input id="uet_ver" class="input" value="${esc(t.verificationMethod||'')}"></div><div class="field"><label>Assigned To</label><input id="uet_assigned" class="input" value="${esc(t.assignedTo||'')}"></div></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="ursSaveTestEdit('${uid2}','${tid}')">Save</button>`)}
function ursSaveTestEdit(uid2,tid){const u=ursAll().find(x=>x.id===uid2),t=u?.tests.find(x=>x.id===tid);if(!u||!t)return;const old=t.testId;t.testId=document.getElementById('uet_id').value.trim();t.category=document.getElementById('uet_cat').value;t.description=document.getElementById('uet_desc').value.trim();t.expectedResult=document.getElementById('uet_expected').value.trim();t.verificationMethod=document.getElementById('uet_ver').value.trim();t.assignedTo=document.getElementById('uet_assigned').value;if(!t.testId||!t.description||!t.expectedResult){alert('Complete required fields.');return}ursAddHistory(u,'Edit Test','Test ID',old,t.testId,'Test updated');save();closeModal();ursView(uid2,'execution')}
function ursTestTabData(u){return u.tests?.[0]}
function ursQAReview(id){const u=ursAll().find(x=>x.id===id);if(!u)return;if(!ursIsQA()){alert('Only QA can perform QA review.');return}if(u.reviewStatus!=='Pending QA Review'){alert('This URS is not pending QA review.');return}openModal('QA Review',`<div class="notice"><b>${esc(u.idn)}</b><br>Status: ${esc(ursSyncStatus(u))}<br>QC: ${esc(u.submittedBy||'—')}</div><div class="field"><label>QA Comment *</label><textarea id="ursQaComment" class="textarea"></textarea></div><div class="field" style="margin-top:10px"><label>Password / Electronic Signature *</label><input id="ursQaPass" type="password" class="input"></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="ursApprove('${id}')">Approve</button><button class="btn" onclick="ursRequestRevision('${id}')">Request Revision</button>`)}
function ursApprove(id){const u=ursAll().find(x=>x.id===id);if(!u||!ursIsQA())return;const pw=document.getElementById('ursQaPass')?.value,comment=document.getElementById('ursQaComment')?.value.trim();if(pw!==USERS.qa.password){alert('Invalid QA electronic signature password.');return}if(!comment){alert('QA Comment is required.');return}u.qaReview={status:'Approved',by:state.session.username,date:now(),comment,signature:'Electronic signature verified'};u.reviewStatus='Approved';ursAddHistory(u,'Approve','Review Status','Pending QA Review','Approved','Data Review QA approval');save();closeModal();ursView(id,'history')}
function ursRequestRevision(id){const u=ursAll().find(x=>x.id===id);if(!u||!ursIsQA())return;const pw=document.getElementById('ursQaPass')?.value,comment=document.getElementById('ursQaComment')?.value.trim();if(pw!==USERS.qa.password){alert('Invalid QA electronic signature password.');return}if(!comment){alert('QA Comment is required.');return}u.qaReview={status:'Revision Required',by:state.session.username,date:now(),comment,signature:'Electronic signature verified'};u.reviewStatus='Revision Required';ursAddHistory(u,'Request Revision','Review Status','Pending QA Review','Revision Required',comment);save();closeModal();ursView(id,'history')}
function ursOpenReview(id){ursQAReview(id)}
function ursExportMenu(e){e?.stopPropagation();openModal('URS Import / Export',`<div class="urs-export-menu"><button class="btn" onclick="closeModal();ursImport()">Import URS</button><button class="btn" onclick="closeModal();ursExport('urs')">Export URS</button><button class="btn" onclick="closeModal();ursExport('tests')">Export Test Results</button><button class="btn" onclick="closeModal();ursExport('verification')">Export Verification Data</button></div>`,'<button class="btn" onclick="closeModal()">Close</button>')}
function ursImport(){if(!ursIsAdmin()){alert('Only Admin can import URS.');return}const input=document.createElement('input');input.type='file';input.accept='.json,.csv';input.onchange=()=>{const f=input.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{let data;if(f.name.toLowerCase().endsWith('.json'))data=JSON.parse(r.result);else{const lines=String(r.result).split(/\r?\n/).filter(Boolean),head=lines.shift().split(',').map(x=>x.trim());data=lines.map(line=>{const vals=line.split(',');return Object.fromEntries(head.map((h,i)=>[h,vals[i]||'']))})}const arr=Array.isArray(data)?data:(data.urs||[]);let added=0;arr.forEach(raw=>{if(!raw.idn||ursAll().some(x=>x.idn===raw.idn))return;const u=ursInit({...raw,id:uid('URS'),tests:Array.isArray(raw.tests)?raw.tests:[]});state.urs.push(u);ursAddHistory(u,'Import');added++});save();renderURS(document.getElementById('content'));alert(`${added} URS imported.`)}catch(err){alert('Import failed: invalid file format.')}};r.readAsText(f)};input.click()}
function ursExport(kind){const all=ursAll();let payload;if(kind==='urs')payload=all;else if(kind==='tests')payload=all.flatMap(u=>(u.tests||[]).map(t=>({...t,ursId:u.idn})));else payload=all.map(u=>({ursId:u.idn,requirement:u.req,module:u.module,testId:(u.tests||[]).map(t=>t.testId).join('|'),status:ursSyncStatus(u),assignedTo:u.assignedTo,history:u.history}));const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`URS_${kind}_${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);log('URS Export',kind)}
function ursExportPDF(){window.print()}

function csvIsQC(){return role()==='QC'}
function csvIsQA(){return role()==='QA'}
function csvIsAdmin(){return role()==='Admin'}
function csvCanManage(){return csvIsQC()||csvIsAdmin()}
function csvStatusClass(s){return ({'Pending Execution':'pending','Pending QA Review':'review','Approved':'approved','Failed':'failed'}[s]||'pending')}
function csvRoleGuide(){
 const r=role();
 if(r==='QC')return `<b>QC workflow:</b> create validation tests, execute IQ/OQ/PQ tests, record actual results and PASS/FAIL, then submit passing executions to QA review.`;
 if(r==='QA')return `<b>QA workflow:</b> independently review completed executions, verify evidence/results, add review comments, and approve or request revision using an electronic signature.`;
 return `<b>Admin workflow:</b> manage the validation test master list and system records. Execution remains a QC responsibility and final review/approval remains a QA responsibility.`;
}
function csvCounts(){const a=state.tests;return {total:a.length,pending:a.filter(t=>t.status==='Pending Execution').length,review:a.filter(t=>t.status==='Pending QA Review').length,approved:a.filter(t=>t.status==='Approved').length,failed:a.filter(t=>t.status==='Failed').length}}
function renderCSV(c){
 const oldCat=document.getElementById('testCat')?.value||window.__csvCat||'All';
 const oldStatus=document.getElementById('testStatus')?.value||window.__csvStatus||'All';
 window.__csvCat=oldCat;window.__csvStatus=oldStatus;
 const n=csvCounts();
 const add=csvCanManage()?`<button class="btn primary" onclick="addTest()">＋ Add Test</button>`:'';
 c.innerHTML=header('CSV Validation Center','Execute, review, approve, and track IQ/OQ/PQ validation tests.',add)+`
 <div class="csv-role-guide">${csvRoleGuide()}</div>
 <div class="csv-summary-grid">
   <button onclick="csvSetStatus('All')"><span>Total Tests</span><b>${n.total}</b></button>
   <button onclick="csvSetStatus('Pending Execution')"><span>Pending Execution</span><b>${n.pending}</b></button>
   <button onclick="csvSetStatus('Pending QA Review')"><span>Pending QA Review</span><b>${n.review}</b></button>
   <button onclick="csvSetStatus('Approved')"><span>Approved</span><b>${n.approved}</b></button>
   <button onclick="csvSetStatus('Failed')"><span>Failed / Revision</span><b>${n.failed}</b></button>
 </div>
 <div class="panel csv-validation-panel">
   <div class="toolbar csv-toolbar"><div class="filters">
     <select id="testCat" class="select" onchange="csvRememberFilters()"><option>All</option>${['IQ','OQ','PQ'].map(x=>`<option ${oldCat===x?'selected':''}>${x}</option>`).join('')}</select>
     <select id="testStatus" class="select" onchange="csvRememberFilters()"><option>All</option>${['Pending Execution','Pending QA Review','Approved','Failed'].map(x=>`<option ${oldStatus===x?'selected':''}>${x}</option>`).join('')}</select>
     <input id="csvSearch" class="input csv-search" placeholder="Search Test ID or requirement..." value="${esc(window.__csvSearch||'')}" oninput="csvRememberFilters()">
     <button class="btn" onclick="csvResetFilters()">Reset</button>
   </div></div><div id="csvTestTable">${testTable()}</div>
 </div>`;
}
function csvRememberFilters(){window.__csvCat=document.getElementById('testCat')?.value||'All';window.__csvStatus=document.getElementById('testStatus')?.value||'All';window.__csvSearch=document.getElementById('csvSearch')?.value||'';document.getElementById('csvTestTable').innerHTML=testTable()}
function csvSetStatus(s){window.__csvStatus=s;renderCSV(document.getElementById('content'))}
function csvResetFilters(){window.__csvCat='All';window.__csvStatus='All';window.__csvSearch='';renderCSV(document.getElementById('content'))}
function testTable(){
 let cat=document.getElementById('testCat')?.value||window.__csvCat||'All',st=document.getElementById('testStatus')?.value||window.__csvStatus||'All',q=(document.getElementById('csvSearch')?.value||window.__csvSearch||'').toLowerCase();
 let arr=state.tests.filter(t=>(cat==='All'||t.category===cat)&&(st==='All'||t.status===st)&&(!q||`${t.testId} ${t.req} ${t.criteria}`.toLowerCase().includes(q)));
 return arr.length?`<div class="table-wrap"><table class="table csv-table"><thead><tr><th>Test ID</th><th>Category</th><th>Requirement</th><th>Acceptance Criteria</th><th>Executed By</th><th>Status</th><th>Action</th></tr></thead><tbody>${arr.map(t=>`<tr><td><b>${esc(t.testId)}</b></td><td>${esc(t.category)}</td><td>${esc(t.req)}</td><td>${esc(t.criteria)}</td><td>${esc(t.executedBy||'—')}</td><td>${badge(t.status)}</td><td><div class="actions">${csvActionButtons(t)}</div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty csv-empty"><b>No validation tests found</b><br><small>${csvCanManage()?'Use “Add Test” to create an IQ/OQ/PQ validation test.':'No tests currently require action for this filter.'}</small></div>`
}
function csvActionButtons(t){
 let b=`<button class="btn" onclick="viewTest('${t.id}')">View</button>`;
 if(csvIsQC()&&(['Pending Execution','Failed'].includes(t.status))) b=`<button class="btn blue" onclick="executeTest('${t.id}')">${t.status==='Failed'?'Re-execute':'Execute'}</button>`+b;
 if(csvIsQA()&&t.status==='Pending QA Review') b=`<button class="btn blue" onclick="reviewTest('${t.id}')">Review</button>`+b;
 if(csvCanManage()&&t.status==='Pending Execution') b+=`<button class="btn" onclick="editCSVTest('${t.id}')">Edit</button><button class="btn danger" onclick="deleteCSVTest('${t.id}')">Delete</button>`;
 return b;
}
function addTest(){if(!csvCanManage()){alert('Only QC or Admin can create validation tests.');return}openModal('Add Validation Test',`<div class="formgrid"><div class="field"><label>Test ID *</label><input id="t_id" class="input" placeholder="e.g. OQ-001"></div><div class="field"><label>Category *</label><select id="t_cat" class="select"><option>IQ</option><option>OQ</option><option>PQ</option></select></div><div class="field full"><label>Requirement *</label><textarea id="t_req" class="textarea" placeholder="Describe the validation requirement"></textarea></div><div class="field full"><label>Acceptance Criteria *</label><textarea id="t_cri" class="textarea" placeholder="Define objective acceptance criteria"></textarea></div></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveTest()">Save Test</button>`)}
function saveTest(){if(!csvCanManage())return;let t={id:uid('T'),testId:document.getElementById('t_id').value.trim(),category:document.getElementById('t_cat').value,req:document.getElementById('t_req').value.trim(),criteria:document.getElementById('t_cri').value.trim(),status:'Pending Execution',actual:'',executionResult:'',executedBy:'',executedAt:'',review:null,createdBy:state.session.username,createdAt:now()};if(!t.testId||!t.req||!t.criteria){alert('Complete all required fields.');return}if(state.tests.some(x=>x.testId.toLowerCase()===t.testId.toLowerCase())){alert('Test ID already exists.');return}state.tests.push(t);log('Add Validation Test',t.testId);save();closeModal();renderCSV(document.getElementById('content'))}
function editCSVTest(id){if(!csvCanManage())return;const t=state.tests.find(x=>x.id===id);if(!t||t.status!=='Pending Execution'){alert('Only tests pending execution can be edited.');return}openModal(`Edit ${esc(t.testId)}`,`<div class="formgrid"><div class="field"><label>Test ID *</label><input id="te_id" class="input" value="${esc(t.testId)}"></div><div class="field"><label>Category *</label><select id="te_cat" class="select">${['IQ','OQ','PQ'].map(x=>`<option ${t.category===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Requirement *</label><textarea id="te_req" class="textarea">${esc(t.req)}</textarea></div><div class="field full"><label>Acceptance Criteria *</label><textarea id="te_cri" class="textarea">${esc(t.criteria)}</textarea></div></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveCSVTestEdit('${id}')">Save Changes</button>`)}
function saveCSVTestEdit(id){const t=state.tests.find(x=>x.id===id);if(!t||!csvCanManage())return;const testId=document.getElementById('te_id').value.trim(),req=document.getElementById('te_req').value.trim(),criteria=document.getElementById('te_cri').value.trim();if(!testId||!req||!criteria){alert('Complete all required fields.');return}if(state.tests.some(x=>x.id!==id&&x.testId.toLowerCase()===testId.toLowerCase())){alert('Test ID already exists.');return}t.testId=testId;t.category=document.getElementById('te_cat').value;t.req=req;t.criteria=criteria;t.updatedBy=state.session.username;t.updatedAt=now();log('Edit Validation Test',t.testId);save();closeModal();renderCSV(document.getElementById('content'))}
function deleteCSVTest(id){const t=state.tests.find(x=>x.id===id);if(!t||!csvCanManage()||t.status!=='Pending Execution')return;if(!confirm(`Delete ${t.testId}?`))return;state.tests=state.tests.filter(x=>x.id!==id);log('Delete Validation Test',t.testId);save();renderCSV(document.getElementById('content'))}
function executeTest(id){if(!csvIsQC()){alert('Test execution is assigned to QC.');return}let t=state.tests.find(x=>x.id===id);if(!t||!['Pending Execution','Failed'].includes(t.status))return;openModal(`Execute ${esc(t.testId)}`,`<div class="notice"><b>Requirement</b><br>${esc(t.req)}<br><br><b>Acceptance Criteria</b><br>${esc(t.criteria)}</div><div class="field"><label>Actual Result *</label><textarea id="t_actual" class="textarea" placeholder="Record the observed result">${esc(t.actual||'')}</textarea></div><div class="field" style="margin-top:10px"><label>Execution Result *</label><select id="t_result" class="select" style="width:100%"><option ${t.executionResult==='PASS'?'selected':''}>PASS</option><option ${t.executionResult==='FAIL'?'selected':''}>FAIL</option></select></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveExecution('${id}')">Submit Execution</button>`)}
function saveExecution(id){if(!csvIsQC())return;let t=state.tests.find(x=>x.id===id),actual=document.getElementById('t_actual').value.trim();if(!actual){alert('Actual Result is required.');return}t.actual=actual;t.executionResult=document.getElementById('t_result').value;t.status=t.executionResult==='FAIL'?'Failed':'Pending QA Review';t.executedBy=state.session.username;t.executedAt=now();t.review=null;log('Execute Test',`${t.testId} — ${t.executionResult}`);save();closeModal();renderCSV(document.getElementById('content'))}
function reviewTest(id){if(!csvIsQA()){alert('Final test review is assigned to QA.');return}let t=state.tests.find(x=>x.id===id);if(!t||t.status!=='Pending QA Review')return;openModal(`QA Review — ${esc(t.testId)}`,`<div class="notice"><b>Requirement</b><br>${esc(t.req)}<br><br><b>Acceptance Criteria</b><br>${esc(t.criteria)}<br><br><b>Actual Result</b><br>${esc(t.actual)}<br><br><b>QC Execution Result</b><br>${esc(t.executionResult)}</div><div class="field"><label>QA Decision *</label><select id="trd" class="select" style="width:100%"><option>Approve</option><option>Request Revision</option></select></div><div class="field" style="margin-top:10px"><label>QA Comment *</label><textarea id="trc" class="textarea" placeholder="Enter review rationale"></textarea></div><div class="field" style="margin-top:10px"><label>QA Password / Electronic Signature *</label><input id="trp" type="password" class="input" style="width:100%"></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn blue" onclick="submitTestReview('${id}')">Submit Review</button>`)}
function submitTestReview(id){if(!csvIsQA())return;const pw=document.getElementById('trp').value,comment=document.getElementById('trc').value.trim();if(pw!==USERS.qa.password){alert('Invalid QA electronic signature password.');return}if(!comment){alert('QA Comment is required.');return}let t=state.tests.find(x=>x.id===id),d=document.getElementById('trd').value;t.review={by:state.session.username,date:now(),decision:d,comment,signature:'Electronic signature verified'};t.status=d==='Approve'?'Approved':'Failed';log('QA Test Review',`${t.testId} — ${d}`);save();closeModal();renderCSV(document.getElementById('content'))}
function viewTest(id){let t=state.tests.find(x=>x.id===id);if(!t)return;openModal(`${esc(t.testId)} — Validation Test Details`,`<table class="info-table">${[['Category',t.category],['Requirement',t.req],['Acceptance Criteria',t.criteria],['Actual Result',t.actual||'No Data'],['Execution Result',t.executionResult||'No Data'],['Executed By',t.executedBy||'No Data'],['Executed At',t.executedAt||'No Data'],['Status',t.status],['QA Reviewed By',t.review?.by||'No Data'],['QA Review Date',t.review?.date||'No Data'],['QA Decision',t.review?.decision||'No Data'],['QA Comment',t.review?.comment||'No Data'],['Electronic Signature',t.review?.signature||'No Data']].map(x=>`<tr><td>${x[0]}</td><td>${esc(x[1])}</td></tr>`).join('')}</table>`,`<button class="btn" onclick="closeModal()">Close</button>`)}

function renderReport(c){let total=state.tests.length,approved=state.tests.filter(t=>t.status==='Approved').length,failed=state.tests.filter(t=>t.status==='Failed').length;c.innerHTML=header('Validation Report','System-generated validation summary from current CSV Validation Center data.',`<button class="btn primary" onclick="window.print()">Export PDF</button>`)+`<div class="panel"><div class="mini-grid"><div class="mini">Total Tests<b>${total}</b></div><div class="mini">Approved<b>${approved}</b></div><div class="mini">Failed<b>${failed}</b></div></div><div style="margin-top:15px"><h3 style="font-size:11px">Validation Summary</h3>${['IQ','OQ','PQ'].map(cat=>{let a=state.tests.filter(t=>t.category===cat),d=a.filter(t=>t.status==='Approved').length,p=a.length?Math.round(d/a.length*100):0;return `<div style="margin:12px 0"><div style="display:flex;justify-content:space-between;font-size:9px"><span>${cat}</span><b>${p}%</b></div><div class="progress"><i style="width:${p}%"></i></div></div>`}).join('')}</div></div>`}

function auditFilterState(){return window.__auditFilters||{q:'',role:'All Roles',action:'All Actions',period:'All Time',page:1,size:15}}
function auditActionGroup(action=''){const a=String(action).toLowerCase();if(a.includes('login')||a.includes('logout'))return 'Authentication';if(a.includes('urs'))return 'URS';if(a.includes('validation report')||a.includes('report'))return 'Validation Report';if(a.includes('test'))return 'CSV Validation';if(a.includes('assay')||a.includes('peak')||a.includes('data review'))return 'Data Review';if(a.includes('method'))return 'Analytical Method';if(a.includes('instrument'))return 'Instrument';if(a.includes('sequence'))return 'Sequence';return 'System'}
function auditFiltered(){const f=auditFilterState(),q=f.q.toLowerCase();return state.activities.filter(x=>{const text=`${x.date} ${x.user} ${x.role} ${x.action} ${x.detail}`.toLowerCase();return (!q||text.includes(q))&&(f.role==='All Roles'||x.role===f.role)&&(f.action==='All Actions'||auditActionGroup(x.action)===f.action)});}
function renderAudit(c){const f=auditFilterState(),acts=state.activities||[],users=new Set(acts.map(x=>x.user)).size,today=new Date().toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}),todayCount=acts.filter(x=>String(x.date||'').includes(today)).length,roles=['All Roles',...new Set(acts.map(x=>x.role).filter(Boolean))],groups=['All Actions','Authentication','URS','CSV Validation','Validation Report','Data Review','Analytical Method','Instrument','Sequence','System'];c.innerHTML=header('Audit Trail','Trace user actions recorded by the system.',`<div class="audit-header-actions"><button class="btn" onclick="auditExportCSV()">Export CSV</button><button class="btn primary" onclick="auditExportPDF()">Export PDF</button></div>`)+`<div class="audit-summary-grid"><div class="audit-summary-card"><span>Total Events</span><b>${acts.length}</b><small>Recorded system activities</small></div><div class="audit-summary-card"><span>Active Users</span><b>${users}</b><small>Users represented in the log</small></div><div class="audit-summary-card"><span>Today</span><b>${todayCount}</b><small>Events recorded today</small></div><div class="audit-summary-card"><span>Data Integrity</span><b>ALCOA+</b><small>Read-only traceability record</small></div></div><div class="panel audit-panel"><div class="audit-toolbar"><div class="audit-search"><span>⌕</span><input id="auditQ" class="input" value="${esc(f.q)}" placeholder="Search user, action, or details..." oninput="auditApplyFilters()"></div><select id="auditRole" class="select" onchange="auditApplyFilters()">${roles.map(x=>`<option ${f.role===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="auditAction" class="select" onchange="auditApplyFilters()">${groups.map(x=>`<option ${f.action===x?'selected':''}>${esc(x)}</option>`).join('')}</select><button class="btn" onclick="auditResetFilters()">Reset</button></div><div class="audit-note"><b>Audit Trail is read-only.</b> Entries are created automatically by system activity and cannot be edited or deleted by QC, QA, or Admin.</div><div id="auditTable"></div></div>`;filterAudit()}
function auditApplyFilters(){const f=auditFilterState();f.q=document.getElementById('auditQ')?.value||'';f.role=document.getElementById('auditRole')?.value||'All Roles';f.action=document.getElementById('auditAction')?.value||'All Actions';f.page=1;window.__auditFilters=f;filterAudit()}
function auditResetFilters(){window.__auditFilters={q:'',role:'All Roles',action:'All Actions',period:'All Time',page:1,size:15};renderAudit(document.getElementById('content'))}
function auditPage(delta){const f=auditFilterState(),a=auditFiltered(),pages=Math.max(1,Math.ceil(a.length/f.size));f.page=Math.max(1,Math.min(pages,f.page+delta));window.__auditFilters=f;filterAudit()}
function filterAudit(){const f=auditFilterState(),a=auditFiltered(),pages=Math.max(1,Math.ceil(a.length/f.size));f.page=Math.min(f.page,pages);const rows=a.slice((f.page-1)*f.size,f.page*f.size),el=document.getElementById('auditTable');if(!el)return;el.innerHTML=a.length?`<div class="audit-result-head"><span>Showing ${((f.page-1)*f.size)+1}–${Math.min(f.page*f.size,a.length)} of ${a.length} event(s)</span><span>Page ${f.page} of ${pages}</span></div><div class="table-wrap"><table class="table audit-table"><thead><tr><th>Date & Time</th><th>User</th><th>Role</th><th>Module</th><th>Action</th><th>Details</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr onclick="showActivity('${x.id}')" title="View activity details"><td>${esc(x.date)}</td><td><b>${esc(x.user)}</b></td><td><span class="audit-role-badge">${esc(x.role)}</span></td><td><span class="audit-module-badge">${esc(auditActionGroup(x.action))}</span></td><td>${esc(x.action)}</td><td class="audit-detail-cell">${esc(x.detail)}</td><td><button class="icon-action" onclick="event.stopPropagation();showActivity('${x.id}')" title="View details">›</button></td></tr>`).join('')}</tbody></table></div><div class="audit-pagination"><button class="btn" onclick="auditPage(-1)" ${f.page<=1?'disabled':''}>Previous</button><button class="btn" onclick="auditPage(1)" ${f.page>=pages?'disabled':''}>Next</button></div>`:'<div class="empty">No audit trail entries match the selected filters.</div>'}
function auditExportCSV(){const a=auditFiltered();if(!a.length){alert('No audit trail data to export.');return}const rows=[['Date & Time','User','Role','Module','Action','Details'],...a.map(x=>[x.date,x.user,x.role,auditActionGroup(x.action),x.action,x.detail])];const csv=rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));link.download=`Audit_Trail_${new Date().toISOString().slice(0,10)}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),500);log('Export Audit Trail CSV',`${a.length} event(s)`)}
function auditExportPDF(){const a=auditFiltered();if(!a.length){alert('No audit trail data to export.');return}const lines=['HPLC-UV CSV Validation System','Audit Trail Report',`Generated: ${new Date().toLocaleString()}`,`Generated by: ${state.session?.username||'system'} (${role()})`,`Records: ${a.length}`,'','Date & Time | User | Role | Module | Action | Details',...a.map(x=>`${x.date} | ${x.user} | ${x.role} | ${auditActionGroup(x.action)} | ${x.action} | ${x.detail}`),'','Audit Trail records are system-generated and read-only.'];const pdf=makeSimplePDF(lines);const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([pdf],{type:'application/pdf'}));link.download=`Audit_Trail_${new Date().toISOString().slice(0,10)}.pdf`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);log('Export Audit Trail PDF',`${a.length} event(s)`)}


/* Administration access control — only requested change */
function administrationIsAdmin(){
  return String(state.session?.role||'').toUpperCase()==='ADMIN';
}
function enforceAdministrationViewOnly(root){
  if(!root || administrationIsAdmin()) return;
  root.classList.add('administration-view-only');
  root.querySelectorAll('input,textarea,select').forEach(el=>{
    el.disabled=true;
    el.setAttribute('aria-readonly','true');
  });
  root.querySelectorAll('button').forEach(btn=>{
    const t=(btn.textContent||'').trim().toLowerCase();
    const allowed=['close','view','details','refresh','search','reset','filter','overview','system configuration','user & role management','security & access','data maintenance'];
    if(!allowed.some(x=>t.includes(x))) btn.disabled=true;
  });
}
function adminEnsure(){
 state.adminSettings=state.adminSettings||{sessionTimeout:30,minPasswordLength:8,requireUppercase:true,requireNumber:true,requireSpecial:false,failedLoginLimit:5,auditRetention:365,autoBackup:false,lastBackup:'Never'};
 state.adminUserStatus=state.adminUserStatus||{qc:true,qa:true,admin:true};
 window.__adminTab=window.__adminTab||'overview';
}
function adminGuard(){if(role()!=='Admin'){alert('Administration is restricted to Admin.');go('dashboard');return false}return true}
function adminSetTab(tab){if(!adminGuard())return;window.__adminTab=tab;renderAdmin(document.getElementById('content'))}
function adminStatCard(label,value,note){return `<div class="admin-stat"><span>${label}</span><b>${esc(value)}</b><small>${note}</small></div>`}
function renderAdmin(c){

 adminEnsure(); const tab=window.__adminTab; const aset=state.adminSettings;
 const active=Object.values(state.adminUserStatus).filter(Boolean).length;
 const tabs=[['overview','Overview'],['configuration','System Configuration'],['users','User & Role Management'],['security','Security & Access'],['maintenance','Data Maintenance']];
 let body='';
 if(tab==='overview') body=`<div class="admin-summary">${adminStatCard('System ID',state.config.systemId,'Validated system identifier')}${adminStatCard('Software Version',state.config.softwareVersion,'Current configured version')}${adminStatCard('Active Accounts',String(active),'QC, QA and Admin access')}${adminStatCard('Audit Records',String(state.activities.length),'Immutable activity records')}</div>
 <div class="admin-grid"><div class="panel"><div class="panel-head"><div><h3>System Status</h3><p class="admin-muted">Current controlled configuration</p></div><span class="admin-ready">● System Ready</span></div><div class="admin-info">${[['Application',state.config.application],['Detector',state.config.detector],['Data Integrity',state.config.dataIntegrity],['Last Validation',state.config.lastValidation||'Not set'],['Next Validation Due',state.config.nextDue||'Not set']].map(x=>`<div><span>${x[0]}</span><b>${esc(x[1])}</b></div>`).join('')}</div><button class="btn" onclick="adminSetTab('configuration')">Manage Configuration</button></div>
 <div class="panel"><div class="panel-head"><div><h3>Administration Tasks</h3><p class="admin-muted">Common Admin responsibilities</p></div></div><div class="admin-task-list"><button onclick="adminSetTab('users')"><b>User & Role Management</b><span>Manage account availability and credentials ›</span></button><button onclick="adminSetTab('security')"><b>Security & Access Policy</b><span>Configure session and password controls ›</span></button><button onclick="adminSetTab('maintenance')"><b>Data Maintenance</b><span>Backup, restore and controlled reset ›</span></button><button onclick="go('audit')"><b>Review Audit Trail</b><span>Inspect recorded system activity ›</span></button></div></div></div>`;
 if(tab==='configuration') body=`<div class="panel"><div class="panel-head"><div><h3>System Configuration</h3><p class="admin-muted">Admin-controlled application identity and validation dates.</p></div></div><div class="formgrid"><div class="field"><label>Application</label><input id="cfg_app" class="input" value="${esc(state.config.application)}"></div><div class="field"><label>System ID</label><input id="cfg_id" class="input" value="${esc(state.config.systemId)}"></div><div class="field"><label>Detector</label><input id="cfg_det" class="input" value="${esc(state.config.detector)}"></div><div class="field"><label>Software Version</label><input id="cfg_ver" class="input" value="${esc(state.config.softwareVersion)}"></div><div class="field"><label>Data Integrity</label><input id="cfg_di" class="input" value="${esc(state.config.dataIntegrity)}"></div><div class="field"><label>Last Validation</label><input id="cfg_last" type="date" class="input" value="${esc(state.config.lastValidation)}"></div><div class="field"><label>Next Due</label><input id="cfg_next" type="date" class="input" value="${esc(state.config.nextDue)}"></div></div><div class="admin-actions"><button class="btn primary" onclick="saveConfig()">Save Configuration</button><button class="btn" onclick="adminReloadConfig()">Discard Changes</button></div></div>`;
 if(tab==='users') body=`<div class="panel"><div class="panel-head"><div><h3>User & Role Management</h3><p class="admin-muted">Manage system account availability. Functional permissions remain role-based.</p></div></div><table class="table admin-user-table"><thead><tr><th>Role</th><th>Username</th><th>Access</th><th>Responsibility</th><th>Actions</th></tr></thead><tbody>${Object.entries(USERS).map(([k,u])=>`<tr><td><b>${u.label}</b><br><small>${u.role}</small></td><td>${esc(u.username)}</td><td><span class="admin-access ${state.adminUserStatus[k]?'on':'off'}">${state.adminUserStatus[k]?'Active':'Disabled'}</span></td><td>${k==='qc'?'Execute tests and submit records for QA review':k==='qa'?'Independent review, approval and controlled disposition':'System configuration, access control and maintenance'}</td><td><button class="btn" onclick="adminUserDetails('${k}')">View</button> ${k!=='admin'?`<button class="btn" onclick="adminToggleUser('${k}')">${state.adminUserStatus[k]?'Disable':'Enable'}</button>`:''} <button class="btn" onclick="adminChangePassword('${k}')">Reset Password</button></td></tr>`).join('')}</tbody></table></div>`;
 if(tab==='security') body=`<div class="panel"><div class="panel-head"><div><h3>Security & Access Policy</h3><p class="admin-muted">Configure local access controls for this validation system.</p></div></div><div class="formgrid"><div class="field"><label>Session Timeout (minutes)</label><input id="adm_timeout" type="number" min="5" max="240" class="input" value="${aset.sessionTimeout}"></div><div class="field"><label>Failed Login Limit</label><input id="adm_failed" type="number" min="3" max="10" class="input" value="${aset.failedLoginLimit}"></div><div class="field"><label>Minimum Password Length</label><input id="adm_minpass" type="number" min="6" max="32" class="input" value="${aset.minPasswordLength}"></div><div class="field"><label>Audit Retention (days)</label><input id="adm_retention" type="number" min="30" class="input" value="${aset.auditRetention}"></div></div><div class="admin-checks"><label><input id="adm_upper" type="checkbox" ${aset.requireUppercase?'checked':''}> Require uppercase character</label><label><input id="adm_number" type="checkbox" ${aset.requireNumber?'checked':''}> Require numeric character</label><label><input id="adm_special" type="checkbox" ${aset.requireSpecial?'checked':''}> Require special character</label></div><div class="admin-actions"><button class="btn primary" onclick="adminSaveSecurity()">Save Security Policy</button><button class="btn" onclick="adminSetTab('security')">Reset Form</button></div></div>`;
 if(tab==='maintenance') body=`<div class="admin-grid"><div class="panel"><div class="panel-head"><div><h3>Backup & Restore</h3><p class="admin-muted">Create a portable JSON backup of local validation data.</p></div></div><div class="admin-info"><div><span>Last Backup</span><b>${esc(aset.lastBackup||'Never')}</b></div><div><span>Stored Records</span><b>${state.activities.length} audit events · ${state.tests.length} validation tests</b></div></div><div class="admin-actions"><button class="btn primary" onclick="adminBackup()">Export Backup</button><button class="btn" onclick="adminRestore()">Import Backup</button></div></div><div class="panel admin-danger"><div class="panel-head"><div><h3>Controlled Data Reset</h3><p class="admin-muted">Reset local demo data only after explicit confirmation.</p></div></div><p>This action clears locally stored application data and returns the system to its seeded state.</p><button class="btn danger" onclick="resetData()">Reset Local Demo Data</button></div></div>`;
 c.innerHTML=header('Administration',administrationIsAdmin()?'System configuration, access control, security, and maintenance.':'System configuration and administration information (view only).')+`<div class="admin-role-banner"><div><b>Administration Workspace</b><span>${administrationIsAdmin()?'Administration controls enabled':'QC / QA access is read-only'}</span></div><span class="admin-lock">${administrationIsAdmin()?'🔒 Admin Access':'View Only'}</span></div><div class="admin-tabs">${tabs.map(x=>`<button class="${tab===x[0]?'active':''}" onclick="adminSetTab('${x[0]}')">${x[1]}</button>`).join('')}</div>${body}`;
 if(!administrationIsAdmin()) enforceAdministrationViewOnly(c);
}
function saveConfig(){if(!adminGuard())return;state.config.application=document.getElementById('cfg_app').value.trim();state.config.systemId=document.getElementById('cfg_id').value.trim();state.config.detector=document.getElementById('cfg_det').value.trim();state.config.softwareVersion=document.getElementById('cfg_ver').value.trim();state.config.dataIntegrity=document.getElementById('cfg_di').value.trim();state.config.lastValidation=document.getElementById('cfg_last').value;state.config.nextDue=document.getElementById('cfg_next').value;if(!state.config.application||!state.config.systemId){alert('Application and System ID are required.');return}log('Administration: Update Configuration',state.config.systemId);save();alert('System configuration saved.');renderAdmin(document.getElementById('content'))}
function adminReloadConfig(){renderAdmin(document.getElementById('content'))}
function adminUserDetails(k){adminEnsure();const u=USERS[k];openModal('User Access Details',`<div class="detail-grid"><div class="detail-item"><span>Role</span><b>${esc(u.label)} (${esc(u.role)})</b></div><div class="detail-item"><span>Username</span><b>${esc(u.username)}</b></div><div class="detail-item"><span>Account Status</span><b>${state.adminUserStatus[k]?'Active':'Disabled'}</b></div><div class="detail-item"><span>Authentication</span><b>Role + username + password</b></div></div>`,'<button class="btn" onclick="closeModal()">Close</button>')}
function adminToggleUser(k){if(!adminGuard()||k==='admin')return;adminEnsure();const next=!state.adminUserStatus[k];if(!confirm(`${next?'Enable':'Disable'} ${USERS[k].label} account?`))return;state.adminUserStatus[k]=next;log('Administration: Account Access',`${USERS[k].username} — ${next?'Enabled':'Disabled'}`);save();renderAdmin(document.getElementById('content'))}
function adminChangePassword(k){if(!adminGuard())return;adminEnsure();const u=USERS[k];openModal('Reset Password — '+u.role,`<div class="field"><label>Username</label><input class="input" value="${esc(u.username)}" disabled></div><div class="field"><label>New Password *</label><input id="admin_new_password" type="password" class="input" autocomplete="new-password"></div><div class="field"><label>Confirm Password *</label><input id="admin_confirm_password" type="password" class="input" autocomplete="new-password"></div><div class="notice">Password must satisfy the current Security & Access Policy.</div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="adminSavePassword('${k}')">Save Password</button>`)}
function adminSavePassword(k){if(!adminGuard())return;adminEnsure();const p=document.getElementById('admin_new_password').value,c=document.getElementById('admin_confirm_password').value,a=state.adminSettings;if(p!==c){alert('Password confirmation does not match.');return}if(p.length<a.minPasswordLength||(a.requireUppercase&&!/[A-Z]/.test(p))||(a.requireNumber&&!/[0-9]/.test(p))||(a.requireSpecial&&!/[^A-Za-z0-9]/.test(p))){alert('Password does not satisfy the current security policy.');return}USERS[k].password=p;log('Administration: Reset Password',`${USERS[k].username} credential updated`);save();closeModal();alert('Password updated.')}
function adminSaveSecurity(){if(!adminGuard())return;adminEnsure();const a=state.adminSettings;a.sessionTimeout=Number(document.getElementById('adm_timeout').value);a.failedLoginLimit=Number(document.getElementById('adm_failed').value);a.minPasswordLength=Number(document.getElementById('adm_minpass').value);a.auditRetention=Number(document.getElementById('adm_retention').value);a.requireUppercase=document.getElementById('adm_upper').checked;a.requireNumber=document.getElementById('adm_number').checked;a.requireSpecial=document.getElementById('adm_special').checked;if(a.sessionTimeout<5||a.minPasswordLength<6||a.failedLoginLimit<3||a.auditRetention<30){alert('Review the minimum allowed security values.');return}log('Administration: Update Security Policy',`Timeout ${a.sessionTimeout} min; password min ${a.minPasswordLength}`);save();alert('Security policy saved.');renderAdmin(document.getElementById('content'))}
function adminBackup(){if(!adminGuard())return;adminEnsure();const payload={exportedAt:new Date().toISOString(),application:'HPLC-UV CSV Validation System',state};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`HPLC_CSV_Backup_${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);state.adminSettings.lastBackup=now();log('Administration: Export Backup','Local validation data backup exported');save();renderAdmin(document.getElementById('content'))}
function adminRestore(){if(!adminGuard())return;const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=()=>{const f=input.files?.[0];if(!f)return;const rd=new FileReader();rd.onload=()=>{try{const x=JSON.parse(rd.result);if(!x.state||!x.state.config||!Array.isArray(x.state.activities)){throw new Error('Invalid backup')}if(!confirm('Import this backup and replace current local data?'))return;state=x.state;adminEnsure();log('Administration: Import Backup',f.name);save();renderAdmin(document.getElementById('content'));alert('Backup restored successfully.')}catch(e){alert('Invalid or unsupported backup file.')}};rd.readAsText(f)};input.click()}
function resetData(){if(!adminGuard())return;if(confirm('Reset all locally stored application data? This cannot be undone.')){localStorage.removeItem(KEY);state=load();adminEnsure();log('Administration: Reset Data','Local demo data reset');save();renderAdmin(document.getElementById('content'))}}
function showNotifications(){openModal('Notifications',state.notifications.length?state.notifications.map((n,i)=>`<div class="attach-row"><span>${esc(n.text)}</span><a class="link" onclick="state.notifications.splice(${i},1);save();closeModal();showNotifications()">Dismiss</a></div>`).join(''):'<div class="empty">No notifications</div>','<button class="btn" onclick="state.notifications=[];save();closeModal()">Clear All</button>')}
function globalSearch(q){q=q.trim().toLowerCase();if(!q)return;const m=state.methods.find(x=>JSON.stringify(x).toLowerCase().includes(q));if(m){go('methods');setTimeout(()=>{document.getElementById('methodQ').value=q;filterMethods()},0);return}const t=state.tests.find(x=>JSON.stringify(x).toLowerCase().includes(q));if(t){go('csv');return}alert('No matching record found.')}
function loginPage(){document.getElementById('root').innerHTML=`<div class="login-page">
<div class="login-card">
  <div class="login-brand">
    <div class="login-logo">HPLC</div>
    <h1>HPLC-UV CSV Validation<br>System</h1>
    <p>Computerized System Validation in Laboratory</p>
  </div>
  <div class="login-divider"></div>
  <div class="login-title">Login as</div>

  <div class="roles">
    <button type="button" class="role active" data-role="qc" onclick="selectRole('qc',this)">
      <span class="ricon">${LOGIN_ICONS.qc}</span>
      <strong>Quality<br>Control</strong>
      <span>(QC)</span>
    </button>
    <button type="button" class="role" data-role="qa" onclick="selectRole('qa',this)">
      <span class="ricon">${LOGIN_ICONS.qa}</span>
      <strong>Quality<br>Assurance</strong>
      <span>(QA)</span>
    </button>
    <button type="button" class="role" data-role="admin" onclick="selectRole('admin',this)">
      <span class="ricon">${LOGIN_ICONS.admin}</span>
      <strong>Administration</strong>
      <span>(Admin)</span>
    </button>
  </div>

  <div class="field login-field">
    <label>Username</label>
    <input id="loginUser" class="input" autocomplete="username" placeholder="Enter username">
  </div>

  <div class="field login-field password-field">
    <label>Password</label>
    <div class="password-wrap">
      <input id="loginPass" type="password" class="input" autocomplete="current-password" placeholder="Enter password">
      <button type="button" class="eye" aria-label="Show password" onclick="togglePass()"><img src="data:image/png;base64," alt="" class="password-eye-img"></button>
    </div>
  </div>

  <div id="loginErr" class="login-error"></div>
  <button class="btn primary fullbtn" onclick="login()">Sign In</button>
</div>
</div>`}
function selectRole(k,el){selectedRole=k;document.querySelectorAll('.role').forEach(x=>x.classList.remove('active'));el.classList.add('active');document.getElementById('loginErr').textContent=''}
function togglePass(){let x=document.getElementById('loginPass'),b=document.querySelector('.eye');x.type=x.type==='password'?'text':'password';if(b)b.setAttribute('aria-label',x.type==='password'?'Hide password':'Show password')}
function login(){const u=USERS[selectedRole],un=document.getElementById('loginUser').value,pw=document.getElementById('loginPass').value;if(un!==u.username||pw!==u.password){document.getElementById('loginErr').textContent='Invalid credentials for the selected role.';return}state.session={role:u.role,username:u.username,label:u.label};save();log('Login','Successful login');save();currentPage='dashboard';layout()}
function logout(){log('Logout','User logged out');state.session=null;save();loginPage()}
if(state.session)layout();else loginPage();

